    /// Resolve every non-hidden specialist's delegation `modelOptions`
    /// (PROTOCOL §5.11) through the 3-tier fold, for injection into the
    /// per-agent `workspace_api` tool description at bridge creation. Each
    /// listed specialist also carries the default a no-`model`
    /// `agent.delegate` would pin, computed by
    /// [`agent_ops::resolve_agent_default_model`] against the *same*
    /// per-specialist provider [`agent_ops::resolve_delegate_provider_preview`]
    /// resolves (mirroring [`agent_ops::resolve_delegate_provider`], the
    /// provider `agent.delegate` itself spawns on) — not a single
    /// settings-derived provider shared across every specialist, so a
    /// specialist pinned to another provider (frontmatter `codingAgent` or a
    /// compound `model` prefix) still shows the default it actually pins.
    /// Specialists without options (the default) are omitted; resolution
    /// failure yields an empty list — spawning never fails on this.
    pub(crate) fn specialist_model_options(
        &self,
        workspace_path: Option<&Path>,
    ) -> Vec<intent_acp::SpecialistModelOptions> {
        use serde_json::Value;
        let Ok(listed) = self.specialists_service().list(workspace_path) else {
            return Vec::new();
        };
        let Some(specs) = listed.get("specialists").and_then(Value::as_array) else {
            return Vec::new();
        };
        specs
            .iter()
            .filter(|def| !def.get("hidden").and_then(Value::as_bool).unwrap_or(false))
            .filter_map(|def| {
                let id = def.get("id").and_then(Value::as_str)?;
                let options: Vec<intent_acp::SpecialistModelOption> = def
                    .get("modelOptions")
                    .and_then(Value::as_array)?
                    .iter()
                    .filter_map(|o| {
                        Some(intent_acp::SpecialistModelOption {
                            model: o.get("model").and_then(Value::as_str)?.to_string(),
                            hint: o
                                .get("hint")
                                .and_then(Value::as_str)
                                .unwrap_or("")
                                .to_string(),
                            reasoning_effort: o
                                .get("reasoningEffort")
                                .and_then(Value::as_str)
                                .unwrap_or("")
                                .to_string(),
                        })
                    })
                    .collect();
                if options.is_empty() {
                    return None;
                }
                let provider =
                    agent_ops::resolve_delegate_provider_preview(self, Some(id), workspace_path);
                Some(intent_acp::SpecialistModelOptions {
                    specialist: id.to_string(),
                    default_model: agent_ops::resolve_agent_default_model(
                        self,
                        Some(id),
                        workspace_path,
                        Some(&provider),
                    ),
                    options,
                })
            })
            .collect()
    }

    /// [`Self::specialist_model_options`] with the project tier derived from
    /// the stored workspace record (worktree path, else repository path) —
    /// the same security-motivated derivation the spawn-time model resolution
    /// uses. Lookup failure degrades to the user/bundled tiers only.
    pub(crate) async fn specialist_model_options_for_workspace(
        &self,
        workspace_id: &WorkspaceId,
    ) -> Vec<intent_acp::SpecialistModelOptions> {
        let wp = self
            .store
            .get_workspace(workspace_id)
            .await
            .ok()
            .and_then(|w| crate::git_ops::worktree_path(&w));
        self.specialist_model_options(wp.as_deref())
    }

    /// Non-empty trimmed string at `key` in a session's raw metadata JSON —
    /// the read shape shared by the `behaviorPrompt` override slot and the
    /// frozen specialist-identity snapshot keys (`specialistName` /
    /// `specialistRoleReminder`) persisted at creation by `agent_create_op`.
    fn session_metadata_str(session: &AgentSession, key: &str) -> Option<String> {
        session
            .metadata
            .as_ref()
            .and_then(|m| m.get(key))
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
    }

    /// Resolve the `[Role Reminder: You are a {name}. {reminder}]` prefix to
    /// prepend to a specialist agent's next turn, or `None` when the agent has no
    /// specialist or its specialist yields no reminder (port of acp-provider.ts
    /// role-reminder injection). Rebuilt every turn (interval = 1); the reminder
    /// is added to the outbound provider prompt only and never persisted.
    pub(crate) async fn agent_role_reminder(&self, agent_id: &AgentId) -> Option<String> {
        let session = self.store.get_agent_session(agent_id).await.ok()?;
        let specialist_id = session.specialist.as_deref()?;
        // Frozen identity snapshot (persisted at creation by `agent_create_op`):
        // when present it wins over live 3-tier resolution, so later edits or
        // deletes of specialist files never change this agent's reminder. A
        // frozen name without a frozen reminder means creation resolved no
        // usable reminder — stay silent rather than falling back live.
        if let Some(name) = Self::session_metadata_str(&session, "specialistName") {
            let reminder = Self::session_metadata_str(&session, "specialistRoleReminder")?;
            return Some(crate::harness::latest().role_reminder_prefix(&name, &reminder));
        }
        // Legacy sessions (no frozen keys): live 3-tier resolution, unchanged.
        let workspace_path = self
            .store
            .get_workspace(&session.workspace_id)
            .await
            .ok()
            .and_then(|w| w.path.or(w.worktree_path))
            .map(PathBuf::from);
        // Embedded floor pinned to the session's stamped harness version
        // (H2); the wrapper wording stays latest-owned (turn envelope, H6).
        let entry = crate::harness::resolve_entry(&session.harness_version);
        let (name, reminder) = self
            .specialists_service()
            .with_embedded(entry.doctrine.specialists)
            .resolve_role_reminder(specialist_id, workspace_path.as_deref())?;
        Some(crate::harness::latest().role_reminder_prefix(&name, &reminder))
    }

    /// Resolve the spawn-prompt specialist injection for an agent (PP-1): the
    /// behavior prompt (the session's persisted `metadata.behaviorPrompt`
    /// override wins over the specialist file's body — the TS
    /// `resolveSpecialistConfig` precedence) plus the specialist's display name
    /// and role reminder for the footer. `None` for non-specialist agents with
    /// no behavior-prompt override, leaving their prompt unchanged.
    pub(crate) async fn agent_specialist_injection(
        &self,
        agent_id: &AgentId,
        workspace_path: Option<&Path>,
    ) -> Option<crate::rules::SpecialistPromptInjection> {
        let session = self.store.get_agent_session(agent_id).await.ok()?;
        let override_bp = Self::session_metadata_str(&session, "behaviorPrompt");
        // Frozen identity snapshot (persisted at creation by `agent_create_op`):
        // on a specialist session, `specialistName` presence marks a snapshot
        // and the whole triple is read frozen — the body from the
        // `behaviorPrompt` override slot (absent when the specialist had no
        // body at creation), skipping live resolution entirely so file
        // edits/deletes never change the injection. Gated on
        // `session.specialist` (mirroring `agent_role_reminder` and the
        // write-side invariant that snapshots are only written for specialist
        // sessions), so a caller-supplied `specialistName` on a
        // non-specialist session stays inert. Legacy sessions fall through to
        // live resolution below.
        if session.specialist.is_some() {
            if let Some(name) = Self::session_metadata_str(&session, "specialistName") {
                return Some(crate::rules::SpecialistPromptInjection {
                    behavior_prompt: override_bp,
                    specialist_name: Some(name),
                    role_reminder: Self::session_metadata_str(&session, "specialistRoleReminder"),
                });
            }
        }
        // Embedded floor pinned to the session's stamped harness version
        // (H2) so respawns under a newer binary keep the pinned prompts.
        let entry = crate::harness::resolve_entry(&session.harness_version);
        let resolved = session.specialist.as_deref().and_then(|id| {
            self.specialists_service()
                .with_embedded(entry.doctrine.specialists)
                .resolve_prompt_injection(id, workspace_path)
        });
        match (override_bp, resolved) {
            (bp_override, Some((bp_file, name, reminder))) => {
                Some(crate::rules::SpecialistPromptInjection {
                    behavior_prompt: bp_override.or(bp_file),
                    specialist_name: Some(name),
                    role_reminder: reminder,
                })
            }
            (Some(bp), None) => Some(crate::rules::SpecialistPromptInjection {
                behavior_prompt: Some(bp),
                specialist_name: None,
                role_reminder: None,
            }),
            (None, None) => None,
        }
    }

