    async fn park_pending_marker_mutation(&self, operation: &str, _message_id: &str) {
        let Some(park) = &self.pending_marker_mutation_park else {
            return;
        };
        if park.target != operation || park.claimed.swap(true, std::sync::atomic::Ordering::AcqRel)
        {
            return;
        }
        park.entered.notify_waiters();
        park.release.notified().await;
    }

    /// Park immediately before the scoped attention write when the test seam
    /// is armed (no-op in production wiring).
    async fn park_attention_write(&self) {
        if let Some(park) = &self.attention_write_park {
            park.entered.notify_one();
            park.release.notified().await;
        }
    }

    /// Test seam: observe/park the underlying `git.diffs` walk on the
    /// blocking pool so single-flight coalescing tests are deterministic.
    /// Production wiring keeps `None`.
    #[cfg(test)]
    pub(crate) fn with_git_diffs_walk_probe(mut self, probe: Arc<dyn Fn() + Send + Sync>) -> Self {
        self.git_diffs_walk_probe = Some(probe);
        self
    }

    /// Test seam: number of followers currently awaiting the in-flight
    /// `git.diffs` walk for `key`.
    #[cfg(test)]
    pub(crate) fn git_diffs_waiters(&self, key: &git_diff_singleflight::DiffKey) -> usize {
        self.git_diffs_inflight.waiters(key)
    }

    /// Test seam: observe/park the underlying working-tree status scan on the
    /// blocking pool so single-flight coalescing tests are deterministic.
    /// Production wiring keeps `None`.
    #[cfg(test)]
    pub(crate) fn with_git_status_scan_probe(mut self, probe: Arc<dyn Fn() + Send + Sync>) -> Self {
        self.git_status_scan_probe = Some(probe);
        self
    }

    /// Test seam: number of followers currently awaiting the in-flight
    /// working-tree status scan for `worktree`.
    #[cfg(test)]
    pub(crate) fn git_status_waiters(&self, worktree: &Path) -> usize {
        self.git_status_cache.waiters(worktree)
    }

    /// Test seam: number of followers currently awaiting the in-flight full
    /// `accept-changes.getStatus` build for `workspace_id`.
    #[cfg(test)]
    pub(crate) fn ac_status_waiters(&self, workspace_id: &WorkspaceId) -> usize {
        self.ac_status_inflight.waiters(workspace_id)
    }

    /// Test-only: rebuild the status cache with a compressed fallback TTL so
    /// expiry coverage completes in milliseconds.
    #[cfg(test)]
    pub(crate) fn with_git_status_cache_ttl(mut self, ttl: std::time::Duration) -> Self {
        self.git_status_cache = Arc::new(git_status_cache::GitStatusCache::with_ttl(ttl));
        self
    }

    /// The shared event-invalidated working-tree status cache (monorepo#1648),
    /// handed to the composition root so the [`GitStatusRefresher`]'s
    /// watcher-driven recompute repopulates the same entries the read path
    /// serves instead of running a competing scan.
    pub fn git_status_cache(&self) -> Arc<git_status_cache::GitStatusCache> {
        Arc::clone(&self.git_status_cache)
    }

    /// The current working-tree status for `worktree` (monorepo#1648): served
    /// from the per-worktree cache when live, otherwise one single-flighted
    /// blocking-pool scan whose result every concurrent caller shares and
    /// which repopulates the cache.
    async fn scan_git_status(&self, worktree: &Path) -> Result<Arc<intent_core::GitStatus>> {
        self.git_status_cache
            .get(worktree, self.git_status_scan_probe.clone())
            .await
    }

    /// Handle on the status cache for a daemon-owned git mutation to
    /// invalidate once it has changed the worktree, so the next read rescans
    /// rather than serving the pre-mutation snapshot. Cloned into the mutation
    /// future because the invalidation happens inside an `async move` block.
    fn git_status_invalidator(&self) -> Arc<git_status_cache::GitStatusCache> {
        Arc::clone(&self.git_status_cache)
    }

    /// Resolve the target path for a workspace-scoped `git.*` read
    /// (monorepo#2053): with `git_root_id` set, look up the registered git
    /// root and validate it belongs to `ws` — an unknown id or one registered
    /// to another workspace is `InvalidParams` (`-32602`) so a caller cannot
    /// read an arbitrary root through a foreign workspace. Without it, fall
    /// back to the workspace worktree exactly as before (`None` when the
    /// workspace has no local path).
    async fn resolve_git_read_root(
        &self,
        ws: &Workspace,
        git_root_id: Option<&WorkspaceGitRootId>,
    ) -> Result<Option<PathBuf>> {
        let Some(id) = git_root_id else {
            return Ok(git_ops::worktree_path(ws));
        };
        let root = match self.store.get_workspace_git_root(id).await {
            Ok(r) => r,
            Err(Error::NotFound(_)) => {
                return Err(Error::InvalidParams(format!("Unknown git root: {id}")))
            }
            Err(e) => return Err(e),
        };
        if root.workspace_id != ws.id {
            // Same message as the unknown-id case so a foreign root is not
            // distinguishable from a nonexistent one.
            return Err(Error::InvalidParams(format!("Unknown git root: {id}")));
        }
        Ok(Some(PathBuf::from(root.path)))
    }

    /// Hydrate the in-memory script registry from the persisted definitions
    /// (§5.8; FE `.workspace/scripts.json` parity). Called once by the
    /// composition root on boot so `script.*` survives daemon restarts; runtime
    /// state starts fresh (idle), except that a service-mode script still
    /// carrying the stored-on-write `was_running` marker hydrates with
    /// `previouslyRunning: true` so clients can re-render its tab. Returns the
    /// number of scripts loaded.
    pub async fn hydrate_scripts(&self) -> Result<usize> {
        self.script_manager().hydrate().await
    }

    /// Clean daemon shutdown (monorepo#1526): flag every managed script with
    /// user-stop semantics (so no auto-restart races the teardown), kill every
    /// PTY session the host tracks — scripts and terminals alike — in one
    /// concurrent group-kill sweep bounded by a single SIGTERM grace, then
    /// await the supervisor settles under a bounded backstop. Returns
    /// `(scripts_stopped, ptys_killed)`.
    pub async fn shutdown_pty_sessions(&self) -> (usize, usize) {
        self.script_manager().stop_all().await
    }

    /// Derive the read-only [`WorkspaceActivity`] for a workspace from the live
    /// in-flight agent count (§9.9): `AgentRunning` iff any session is in flight
    /// OR if a pending idle debounce is scheduled (grace window). During the grace
    /// window after the last agent ends, the workspace is still considered
    /// `AgentRunning` until the debounce fires, ensuring list/get/update responses
    /// and the event stream agree on the derived state.
    pub(crate) fn workspace_activity(&self, workspace_id: &WorkspaceId) -> WorkspaceActivity {
        let map = self.agent_activity.lock().unwrap();
        match map.get(workspace_id) {
            Some(count) if *count > 0 => WorkspaceActivity::AgentRunning,
            _ => {
                // Check if there's a pending idle debounce (grace window).
                if let Ok(debouncers) = self.idle_debouncers.lock() {
                    if debouncers.contains_key(workspace_id) {
                        return WorkspaceActivity::AgentRunning;
                    }
                }
                WorkspaceActivity::Idle
            }
        }
    }

    /// Derive `lastActivity` as the max of the persisted value, `updatedAt`,
    /// `createdAt`, every workspace note's `updated_at`, and every agent
    /// session's `updated_at` (FE `deriveWorkspaceLastActivity` parity, §9.1).
    /// Called on `workspace.*` mutation paths (update/archive/unarchive) that
    /// return a `Workspace` on the wire so clients never have to recompute it;
    /// the `workspace.list`/`workspace.get` read paths derive the same value
    /// inline as part of [`Services::enrich_workspace_aggregates`] to keep the
    /// aggregate scan single-pass. Keep the two in sync when the derivation
    /// rules change. Store failures fall back to the workspace's own
    /// timestamps rather than failing the caller.
    pub(crate) async fn derive_last_activity(&self, ws: &mut Workspace) {
        let mut activity_max = latest_activity_candidate(&[
            ws.last_activity.as_deref(),
            Some(ws.updated_at.as_str()),
            Some(ws.created_at.as_str()),
        ]);
        if let Ok(notes) = self.store.list_notes(&ws.id).await {
            for note in &notes {
                activity_max =
                    latest_activity_candidate(&[activity_max.as_deref(), Some(&note.updated_at)]);
            }
        }
        // Finding F1: message-free session read for hot paths. Only `updated_at`
        // matters for lastActivity derivation, so skip message hydration.
        if let Ok(sessions) = self.store.list_agent_session_summaries(&ws.id).await {
            for session in &sessions {
                activity_max = latest_activity_candidate(&[
                    activity_max.as_deref(),
                    Some(&session.updated_at),
                ]);
            }
        }
        if activity_max.is_some() {
            ws.last_activity = activity_max;
        }
    }

    /// [`Self::derive_last_activity`] plus persistence of the result through
    /// the scoped, monotonic column write (monorepo#1585). The mutation paths
    /// that derive `lastActivity` for their response (update/archive/
    /// unarchive) must all persist it too: without the write the caller gets
    /// a fresh derived value while the stored column stays stale, so the
    /// cheap read paths that never derive (`list_workspaces_lite`, the
    /// `workspace.subscribe` seq-0 snapshot) — or a daemon restart — serve
    /// the old timestamp until the next debounce fires. Best-effort: a store
    /// failure only logs (`ctx` names the calling RPC), the primary mutation
    /// already committed.
    pub(crate) async fn derive_and_persist_last_activity(&self, ws: &mut Workspace, ctx: &str) {
        self.derive_last_activity(ws).await;
        if let Some(derived) = ws.last_activity.as_deref() {
            if let Err(e) = self
                .store
                .bump_workspace_last_activity(&ws.id, derived)
                .await
            {
                tracing::warn!(
                    workspace = %ws.id.as_str(),
                    context = ctx,
                    error = %e,
                    "persisting derived lastActivity failed"
                );
            }
        }
    }

    /// Schedule a debounced `workspace:updated { changes: { lastActivity } }` event
    /// emission for the workspace (§10.1). Recomputes the derived `lastActivity` via
    /// the existing aggregation and emits the event only when it differs from the
    /// previously known value. Rapid calls for the same workspace coalesce into at most
    /// one event per `LAST_ACTIVITY_DEBOUNCE_MS` window, carrying the latest derived
    /// value. Cancels any pending timer for the workspace before scheduling a new one.
    /// The derived value is also persisted (scoped, monotonic column write) so the cheap
    /// read paths that do not derive — `list_workspaces_lite` and the
    /// `workspace.subscribe` seq-0 snapshot — serve a fresh `lastActivity` after a daemon
    /// restart (monorepo#1580).
    /// Best-effort: store/emit failures are logged but do not surface to the caller.
    pub(crate) fn schedule_last_activity_event(&self, workspace_id: WorkspaceId) {
        // Cancel any pending debounce timer for this workspace and increment generation.
        let gen = if let Ok(mut gen_lock) = self.last_activity_debounce_gen.lock() {
            *gen_lock = gen_lock.wrapping_add(1);
            *gen_lock
        } else {
            0
        };

        if let Ok(mut debouncers) = self.last_activity_debouncers.lock() {
            if let Some((_, handle)) = debouncers.remove(&workspace_id) {
                handle.abort();
            }
        }

        // Clone the state we'll need in the spawned task.
        let this = self.clone();
        let debouncers = self.last_activity_debouncers.clone();
        let ws_id = workspace_id.clone();

        // Debounce window: production constant, overridable via env for tests.
        let debounce_ms = std::env::var("LAST_ACTIVITY_DEBOUNCE_TEST_MS")
            .ok()
            .and_then(|s| s.parse::<u64>().ok())
            .unwrap_or(LAST_ACTIVITY_DEBOUNCE_MS);

        // Spawn a task that sleeps for the debounce window, then derives + emits.
        let handle = tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(debounce_ms)).await;

            // Get the current workspace and capture its old lastActivity.
            let mut ws = match this.store.get_workspace(&ws_id).await {
                Ok(w) => w,
                Err(e) => {
                    tracing::warn!(workspace = %ws_id.as_str(), error = %e, "schedule_last_activity_event: get_workspace failed");
                    return;
                }
            };
            let old_activity = ws.last_activity.clone();

            // Recompute lastActivity via the existing aggregation.
            this.derive_last_activity(&mut ws).await;
            let new_activity = ws.last_activity.clone();

            // Emit only when the derived value changed.
            if old_activity != new_activity {
                if let Some(new_val) = &new_activity {
                    // Persist the derived value (monorepo#1580). Without this
                    // the column keeps whatever the last full-row write left
                    // behind, so cheap read paths that do not derive
                    // (`list_workspaces_lite`, the `workspace.subscribe` seq-0
                    // snapshot) serve a stale `lastActivity` after a restart.
                    // Scoped + monotonic: only this column moves, and an
                    // out-of-order late timer can never walk the value back.
                    // A declined bump (a concurrent writer already persisted
                    // something newer) still emits below — the event is a
                    // change signal, and the concurrent task's own event
                    // carries the newer value.
                    if let Err(e) = this
                        .store
                        .bump_workspace_last_activity(&ws_id, new_val)
                        .await
                    {
                        tracing::warn!(
                            workspace = %ws_id.as_str(),
                            error = %e,
                            "schedule_last_activity_event: persist lastActivity failed"
                        );
                    }
                    publish_event(
                        &this.event_bus,
                        workspace_updated_event(
                            &ws_id,
                            serde_json::json!({ "lastActivity": new_val }),
                        ),
                    )
                    .await;
                }
            }

            // Remove ourselves from the debouncers map only if we're still the current task.
            if let Ok(mut map) = debouncers.lock() {
                if let Some((current_gen, _)) = map.get(&ws_id) {
                    if *current_gen == gen {
                        map.remove(&ws_id);
                    }
                }
            }
        });

        // Store the abort handle with generation. Only insert if no entry exists or our
        // generation is newer (prevents older schedules from overwriting newer ones).
        if let Ok(mut map) = self.last_activity_debouncers.lock() {
            let should_insert = map
                .get(&workspace_id)
                .map(|(existing_gen, _)| gen > *existing_gen)
                .unwrap_or(true);

            if should_insert {
                if let Some((_, old_handle)) =
                    map.insert(workspace_id, (gen, handle.abort_handle()))
                {
                    old_handle.abort();
                }
            } else {
                // Our generation is older; abort this task immediately.
                handle.abort();
            }
        }
    }

    /// Populate a workspace's card aggregates (`taskStats`/`agentSummary`/
    /// `cowSupported`) for the `workspace.list` / `workspace.get` emit path (§9.1).
    /// Each is computed from live state (notes / agents / FS capability) and
    /// omitted when not computable; a read failure degrades to an absent
    /// aggregate rather than failing the whole call. `lastActivity` is derived
    /// inline from the same notes/sessions scan (mirrors
    /// [`Services::derive_last_activity`] so list/get callers get both in one
    /// round-trip); keep the two derivations in lock-step when the rules or
    /// underlying store queries change.
    ///
    /// `diffSummary` is intentionally **not** computed here. Full worktree
    /// rollups are too expensive for the high-frequency list/get/subscription
    /// re-read path; desktop FE already treats the field as deprecated and
    /// fetches diffs on demand via `git.diffs`, and embedding the rollup on
    /// every workspace re-read pinned the blocking pool.
    pub(crate) async fn enrich_workspace_aggregates(&self, ws: &mut Workspace) {
        let mut activity_max = latest_activity_candidate(&[
            ws.last_activity.as_deref(),
            Some(ws.updated_at.as_str()),
            Some(ws.created_at.as_str()),
        ]);
        if let Ok(notes) = self.store.list_notes(&ws.id).await {
            for note in &notes {
                activity_max =
                    latest_activity_candidate(&[activity_max.as_deref(), Some(&note.updated_at)]);
            }
            ws.task_stats = Some(compute_task_stats(&notes));
        }
        // Finding F1: message-free session read for hot paths. `build_agent_summary`
        // only needs session metadata (id, name, status, specialist, updated_at),
        // never message bodies, so skip hydration.
        if let Ok(sessions) = self.store.list_agent_session_summaries(&ws.id).await {
            for session in &sessions {
                activity_max = latest_activity_candidate(&[
                    activity_max.as_deref(),
                    Some(&session.updated_at),
                ]);
            }
            ws.agent_summary = Some(build_agent_summary(&sessions));
        }
        // diffSummary: omitted on list/get/subscription re-reads (see method docs).
        ws.diff_summary = None;
        if activity_max.is_some() {
            ws.last_activity = activity_max;
        }
        // Compute cow_supported: CoW probe of the workspaces root. Reports
        // machine/filesystem capability regardless of checkout mode.
        ws.cow_supported = self.compute_cow_supported().await;
        // diskUsage is deliberately NOT populated here: list/get/subscription
        // re-reads never touch the DiskUsageCache or arm walks (rung 3 of the
        // derived-field ladder). Clients fetch it on demand via the dedicated
        // `workspace.diskUsage` method (monorepo#1396).
        // Derived "current cycle" display status over the active/latest PR
        // and the taskStats computed above; never persisted. See
        // [`Services::enrich_display_status`] (workspace_status module).
        self.enrich_display_status(ws).await;
    }

    /// Cheap per-workspace `taskStats` read for lite/list paths: delegates to
    /// the store-level counting query ([`Store::count_task_stats`]) which
    /// hydrates only the spec note's content (for the linked-id filter) — no
    /// other note bodies — and matches [`compute_task_stats`] semantics
    /// exactly. Wired into `list_workspaces_lite` so the workspace.subscribe
    /// seq-0 snapshot is self-sufficient for client status rendering.
    pub(crate) async fn cheap_task_stats(
        &self,
        workspace_id: &WorkspaceId,
    ) -> Result<WorkspaceTaskStats> {
        self.store.count_task_stats(workspace_id).await
    }

    /// Merge externally known PRs into each list row's `pullRequests` for the
    /// `workspace.list` / `workspace.subscribe` seq-0 emit paths: PRs
    /// persisted on the workspace's secondary git roots
    /// (`workspace_git_root.pull_requests`, monorepo#2053) and PRs known to
    /// agent PR monitors (active + completed; cancelled excluded — the same
    /// pool the FE builds after opening a workspace, PROTOCOL §6.9). Purely
    /// an emit-path merge: nothing is persisted, `workspace.pull_requests`
    /// stays daemon-owned, and no forge calls are made (rung 1 of the
    /// derived-field ladder: two SQL-filtered bulk reads + in-memory merge,
    /// O(PR-bearing rows) regardless of workspace count). Dedup is by PR
    /// `url` — the one field every source carries that stays unambiguous
    /// across repos — first-wins in source-priority order: workspace's own
    /// PRs, then git-root PRs, then monitor-derived entries. A row with
    /// nothing to merge is left untouched (a `None` stays omitted on the
    /// wire, and an empty git-root list contributes nothing rather than
    /// materializing `[]`); a store read failure degrades to serving the
    /// base rows. `include_archived` mirrors the list call's flag so the
    /// bulk reads never pay for archived workspaces the list won't return.
    pub(crate) async fn merge_external_pull_requests(
        &self,
        list: &mut [Workspace],
        include_archived: bool,
    ) {
        use std::collections::HashMap;
        let roots = match self
            .store
            .list_workspace_git_roots_with_prs(include_archived)
            .await
        {
            Ok(roots) => roots,
            Err(e) => {
                tracing::warn!(error = %e, "workspace.list: git-root PR read failed; skipping");
                Vec::new()
            }
        };
        let monitors = match self
            .store
            .load_non_cancelled_pr_monitors(include_archived)
            .await
        {
            Ok(monitors) => monitors,
            Err(e) => {
                tracing::warn!(error = %e, "workspace.list: pr monitor read failed; skipping");
                Vec::new()
            }
        };
        if roots.is_empty() && monitors.is_empty() {
            return;
        }
        // Group externally sourced PRs per workspace, git-root entries before
        // monitor-derived ones so the first-wins dedup below encodes the
        // source priority. Empty lists are skipped so they can't flip an
        // omitted workspace `pullRequests` into `[]`.
        let mut extras: HashMap<String, Vec<PullRequestInfo>> = HashMap::new();
        for root in &roots {
            if let Some(prs) = &root.pull_requests {
                if prs.is_empty() {
                    continue;
                }
                extras
                    .entry(root.workspace_id.0.clone())
                    .or_default()
                    .extend(prs.iter().cloned());
            }
        }
        for monitor in &monitors {
            extras
                .entry(monitor.workspace_id.0.clone())
                .or_default()
                .push(pr_monitor::pr_monitor_pr_info(monitor));
        }
        for ws in list.iter_mut() {
            let Some(candidates) = extras.remove(ws.id.as_str()) else {
                continue;
            };
            let merged = ws.pull_requests.get_or_insert_with(Vec::new);
            for info in candidates {
                if !merged.iter().any(|p| p.url == info.url) {
                    merged.push(info);
                }
            }
        }
    }

    /// Parse a GitHub URL and return `(owner, repo)` only if the host is exactly
    /// `github.com`. Rejects URLs with hosts like `github.com.evil.com`.
    fn parse_github_owner_repo(url: &str) -> Option<(String, String)> {
        let trimmed = url.trim();

        // HTTPS: extract host from scheme://host/... form.
        if let Some(rest) = trimmed
            .strip_prefix("https://")
            .or_else(|| trimmed.strip_prefix("http://"))
        {
            let host_end = rest.find('/').unwrap_or(rest.len());
            let host = &rest[..host_end];
            if host != "github.com" {
                return None;
            }
            let path = &rest[host_end..];
            return clone_ops::parse_owner_repo(&format!("https://github.com{path}"));
        }

        // SSH URL: ssh://[user@]host[:port]/owner/repo(.git) form.
        if let Some(rest) = trimmed.strip_prefix("ssh://") {
            let rest = rest.split_once('@').map_or(rest, |(_, r)| r);
            let host_end = rest.find('/').unwrap_or(rest.len());
            let host = &rest[..host_end];
            // Strip a numeric port; a non-numeric suffix stays part of the
            // host and fails the strict check below.
            let host = host.split_once(':').map_or(host, |(h, port)| {
                if !port.is_empty() && port.bytes().all(|b| b.is_ascii_digit()) {
                    h
                } else {
                    host
                }
            });
            if host != "github.com" {
                return None;
            }
            let path = &rest[host_end..];
            return clone_ops::parse_owner_repo(&format!("https://github.com{path}"));
        }

        // SSH scp-like: git@host:path form. Extract host before the colon.
        if let Some(at_idx) = trimmed.find('@') {
            let after_at = &trimmed[at_idx + 1..];
            if let Some(colon_idx) = after_at.find(':') {
                let host = &after_at[..colon_idx];
                if host != "github.com" {
                    return None;
                }
                let path = &after_at[colon_idx + 1..];
                return clone_ops::parse_owner_repo(&format!("git@github.com:{path}"));
            }
        }

        None
    }

    /// Spawn a background task to backfill `repository_owner` / `repository_name`
    /// for active workspaces with a local `repositoryPath` and missing owner/name.
    /// Non-blocking for the caller; each workspace is probed at most once per
    /// daemon lifecycle (tracked in a static dedupe set). FE
    /// `performBackgroundEnrichment` parity (fills only missing fields, persists
    /// once, emits `workspace:updated`).
    fn spawn_repository_owner_backfill(&self, workspaces: &[Workspace]) {
        use std::collections::HashSet;
        use std::sync::Mutex;
        static BACKFILLED: Mutex<Option<HashSet<String>>> = Mutex::new(None);

        let candidates = {
            let mut guard = BACKFILLED.lock().unwrap();
            let backfilled = guard.get_or_insert_with(HashSet::new);

            let mut candidates = Vec::new();
            for ws in workspaces {
                if ws.archived || backfilled.contains(ws.id.as_str()) {
                    continue;
                }
                let missing_owner = ws.repository_owner.is_none()
                    || ws.repository_owner.as_deref().is_some_and(|o| o.is_empty());
                let missing_name = ws.repository_name.is_none()
                    || ws.repository_name.as_deref().is_some_and(|n| n.is_empty());
                if (missing_owner || missing_name)
                    && ws.repository_path.as_deref().is_some_and(|p| !p.is_empty())
                {
                    candidates.push(BackfillCandidate {
                        workspace_id: ws.id.clone(),
                        repository_path: ws.repository_path.clone().unwrap(),
                    });
                    backfilled.insert(ws.id.0.clone());
                }
            }
            candidates
        };

        if candidates.is_empty() {
            return;
        }

        let services = self.clone();
        tokio::spawn(async move {
            for candidate in candidates {
                if let Err(e) = services.backfill_one_workspace(candidate.clone()).await {
                    tracing::debug!(
                        workspace_id = %candidate.workspace_id.as_str(),
                        error = %e.to_string(),
                        "repository owner backfill failed (non-fatal)"
                    );
                }
            }
        });
    }

    /// Backfill one workspace: derive owner/name from origin remote, persist,
    /// and emit `workspace:updated` with the changed fields. Non-github remotes
    /// are skipped silently.
    async fn backfill_one_workspace(&self, candidate: BackfillCandidate) -> Result<()> {
        let repo_path = std::path::PathBuf::from(&candidate.repository_path);
        if !repo_path.join(".git").exists() {
            return Ok(());
        }

        let origin_url = intent_git::remote::origin_url(&repo_path).ok().flatten();

        let Some(origin_url) = origin_url else {
            return Ok(());
        };

        let Some((owner, name)) = Self::parse_github_owner_repo(&origin_url) else {
            return Ok(());
        };

        // Re-read the workspace to avoid overwriting fields populated after the
        // candidate was built (backfill race guard).
        let mut ws = self.store.get_workspace(&candidate.workspace_id).await?;
        let mut changes = serde_json::Map::new();

        // Only fill fields that are still missing in the currently persisted state.
        let missing_owner = ws.repository_owner.is_none()
            || ws.repository_owner.as_deref().is_some_and(|o| o.is_empty());
        let missing_name = ws.repository_name.is_none()
            || ws.repository_name.as_deref().is_some_and(|n| n.is_empty());

        if missing_owner {
            ws.repository_owner = Some(owner.clone());
            changes.insert("repositoryOwner".to_string(), serde_json::json!(owner));
        }
        if missing_name {
            ws.repository_name = Some(name.clone());
            changes.insert("repositoryName".to_string(), serde_json::json!(name));
        }

        if changes.is_empty() {
            return Ok(());
        }

        ws.updated_at = now_iso();
        self.store.update_workspace(&ws).await?;

        publish_event(
            &self.event_bus,
            workspace_updated_event(&ws.id, serde_json::Value::Object(changes)),
        )
        .await;

        tracing::debug!(
            workspace_id = %ws.id.as_str(),
            owner = %ws.repository_owner.as_deref().unwrap_or(""),
            name = %ws.repository_name.as_deref().unwrap_or(""),
            "backfilled repository owner/name from origin remote"
        );

        Ok(())
    }

    /// Compute whether CoW isolation is supported on this machine. Probes the
    /// workspaces root's filesystem (root→root) — a machine capability,
    /// independent of any workspace or checkout mode (the FE uses it to gate
    /// the CoW opt-in toggle, which affects newly created workspaces).
    /// Resolves the root like every other consumer — the injected
    /// `workspaces_root`, else [`default_workspaces_root`]
    /// (`$INTENTD_WORKSPACES_DIR`, else `~/intent/workspaces`) — so
    /// production daemons, which never inject a root, still report the
    /// capability. Returns Some(true) if the CoW probe reports Supported;
    /// Some(false) on an unsupported filesystem; None if the probe cannot
    /// run. The live probe is offloaded to the blocking pool and cached per
    /// workspaces root by the shared aggregate cache.
    async fn compute_cow_supported(&self) -> Option<bool> {
        let workspaces_root = self
            .workspaces_root
            .clone()
            .unwrap_or_else(default_workspaces_root);
        self.workspace_aggregates
            .cow_supported(workspaces_root)
            .await
    }

    /// The daemon-managed directory whose footprint `workspace.diskUsage`
    /// reports, or `None` for rows without one (remote / skip-isolation rows
    /// and the virtual chief workspace). The directory is the provisioned
    /// checkout's parent (`<parent>/<id>/<repo-slug>` → `<parent>/<id>`,
    /// covering custom `workspace.worktreesLocation` roots) when it is named
    /// for the workspace id, else `<workspaces_root>/<id>`.
    fn disk_usage_dir(&self, ws: &Workspace) -> Option<PathBuf> {
        if ws.is_remote || ws.skip_worktree || ws.id.is_chief() {
            return None;
        }
        let dir = ws
            .worktree_path
            .as_deref()
            .filter(|p| !p.is_empty())
            .and_then(|wt| {
                let parent = Path::new(wt).parent()?;
                (parent.file_name()? == std::ffi::OsStr::new(ws.id.as_str()))
                    .then(|| parent.to_path_buf())
            })
            .unwrap_or_else(|| {
                self.workspaces_root
                    .clone()
                    .unwrap_or_else(default_workspaces_root)
                    .join(ws.id.as_str())
            });
        Some(dir)
    }

    /// `workspace.diskUsage` (§5.1): on-demand cached footprint of the
    /// workspace's daemon-managed directory — `{ diskUsage?, refreshing }`
    /// per the [`disk_usage::DiskUsageCache::poll`] semantics. Non-qualifying
    /// rows (no daemon-managed directory, or one that was never provisioned)
    /// answer `{ refreshing: false }` with the field omitted, without
    /// touching the cache; an unknown id is `NotFound`.
    pub(crate) async fn workspace_disk_usage_op(
        &self,
        id: WorkspaceId,
    ) -> Result<serde_json::Value> {
        let ws = if id.is_chief() {
            chief_workspace()
        } else {
            self.store.get_workspace(&id).await?
        };
        let Some(dir) = self.disk_usage_dir(&ws) else {
            return Ok(serde_json::json!({ "refreshing": false }));
        };
        // A never-provisioned directory can never yield a value, so don't
        // arm a walk (it would fail and leave `refreshing` forever-true).
        let is_dir = tokio::fs::metadata(&dir)
            .await
            .map(|m| m.is_dir())
            .unwrap_or(false);
        if !is_dir {
            return Ok(serde_json::json!({ "refreshing": false }));
        }
        let (usage, refreshing) = self.disk_usage.poll(dir).await;
        let mut result = serde_json::json!({ "refreshing": refreshing });
        if let Some(usage) = usage {
            result["diskUsage"] = serde_json::to_value(usage)
                .map_err(|e| Error::Internal(format!("serialize diskUsage: {e}")))?;
        }
        Ok(result)
    }

    /// The currently configured `workspace.worktreesLocation` directory for
    /// teardown sweeps: `None` when the setting is empty or the startup pin
    /// (`INTENTD_WORKSPACES_DIR`) keeps precedence, or when the expanded path
    /// is not absolute. Unlike [`resolve_workspaces_parent`] this never
    /// creates the directory — teardown must not mint new parents.
    fn configured_worktrees_location(&self) -> Option<PathBuf> {
        let pinned = self
            .settings_registry
            .as_deref()
            .and_then(|r| r.origin("workspaces.root"))
            == Some(SettingOrigin::Flag);
        if pinned {
            return None;
        }
        let location = settings::worktrees_location(&self.effective_settings());
        let location = location.trim();
        if location.is_empty() {
            return None;
        }
        let dir = PathBuf::from(intent_core::expand_tilde_string(location));
        dir.is_absolute().then_some(dir)
    }

    /// Record an agent session entering flight for `workspace_id`. On the
    /// `Idle → AgentRunning` transition (count `0 → 1`) emits a self-sufficient
    /// `workspace:activity-changed { workspaceId, activity }` (§10.1, only-on-change)
    /// and cancels any pending idle debounce. The same transition recomputes
    /// the derived `displayStatus` (a running agent promotes it to
    /// `in_progress`) so `workspace:displayStatus-changed` tracks live agent
    /// state without a client-side overlay.
    pub(crate) async fn agent_activity_begin(&self, workspace_id: &WorkspaceId) {
        let transitioned = {
            let mut map = self.agent_activity.lock().unwrap();
            let count = map.entry(workspace_id.clone()).or_insert(0);
            *count += 1;
            *count == 1
        };

        // Cancel any pending idle debounce (if the workspace was in grace window).
        if let Ok(mut debouncers) = self.idle_debouncers.lock() {
            if let Some((_, handle)) = debouncers.remove(workspace_id) {
                handle.abort();
            }
        }

        if transitioned {
            publish_event(
                &self.event_bus,
                activity_changed_event(workspace_id, WorkspaceActivity::AgentRunning),
            )
            .await;
            self.maybe_emit_display_status_changed(workspace_id).await;
        }
    }

    /// Record an agent session leaving flight for `workspace_id`. On the
    /// `AgentRunning → Idle` transition (count `1 → 0`), schedules a debounced
    /// `workspace:activity-changed { idle }` event emission after a configurable
    /// window (~3s default, env-overridable for tests). A new `agent_activity_begin`
    /// within the window cancels the idle flip. A decrement with no tracked session
    /// is a no-op.
    pub(crate) async fn agent_activity_end(&self, workspace_id: &WorkspaceId) {
        let transitioned = {
            let mut map = self.agent_activity.lock().unwrap();
            match map.get_mut(workspace_id) {
                Some(count) if *count > 0 => {
                    *count -= 1;
                    if *count == 0 {
                        map.remove(workspace_id);
                        true
                    } else {
                        false
                    }
                }
                _ => false,
            }
        };
        if transitioned {
            self.schedule_idle_debounce(workspace_id.clone());
        }
    }

    /// Schedule a debounced `workspace:activity-changed { idle }` event emission
    /// for the workspace. The event is emitted only after the workspace stays idle
    /// for the full debounce window (~3s default, env-overridable for tests). A new
    /// `agent_activity_begin` within the window cancels the pending flip.
    fn schedule_idle_debounce(&self, workspace_id: WorkspaceId) {
        // Increment generation counter and cancel any existing debouncer.
        let gen = if let Ok(mut gen_lock) = self.idle_debounce_gen.lock() {
            *gen_lock = gen_lock.wrapping_add(1);
            *gen_lock
        } else {
            0
        };

        if let Ok(mut debouncers) = self.idle_debouncers.lock() {
            if let Some((_, handle)) = debouncers.remove(&workspace_id) {
                handle.abort();
            }
        }

        // Clone the state we'll need in the spawned task.
        let this = self.clone();
        let debouncers = self.idle_debouncers.clone();
        let ws_id = workspace_id.clone();

        // Debounce window: production constant (~3s), overridable via env for tests.
        let debounce_ms = std::env::var("WORKSPACE_IDLE_DEBOUNCE_TEST_MS")
            .ok()
            .and_then(|s| s.parse::<u64>().ok())
            .unwrap_or(WORKSPACE_IDLE_DEBOUNCE_MS);

        // Spawn a task that sleeps for the debounce window, then emits idle.
        let handle = tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(debounce_ms)).await;

            // Guard emission: verify debouncer still current AND count still zero.
            let should_emit = {
                let gen_valid = if let Ok(map) = debouncers.lock() {
                    map.get(&ws_id)
                        .map(|(current_gen, _)| *current_gen == gen)
                        .unwrap_or(false)
                } else {
                    false
                };
                let count_zero = if let Ok(activity) = this.agent_activity.lock() {
                    activity.get(&ws_id).copied().unwrap_or(0) == 0
                } else {
                    false
                };
                gen_valid && count_zero
            };

            if should_emit {
                // Remove debouncer entry before emitting so reads stop reporting grace.
                // Race note: an `agent_activity_begin` that lands after the
                // should_emit check finds no handle to abort, so the client
                // can observe `agent_running` followed by this stale `idle`
                // activity event (pre-existing inversion). The displayStatus
                // recompute below is safe against it: it re-reads
                // `workspace_activity()` at emit time (count already 1 →
                // `in_progress`) and the dedup cache suppresses a bogus
                // demotion.
                if let Ok(mut map) = debouncers.lock() {
                    if let Some((current_gen, _)) = map.get(&ws_id) {
                        if *current_gen == gen {
                            map.remove(&ws_id);
                        }
                    }
                }

                publish_event(
                    &this.event_bus,
                    activity_changed_event(&ws_id, WorkspaceActivity::Idle),
                )
                .await;
                // The debounced idle flip also moves the derived displayStatus
                // (no running agent demotes a task-stage rollup to `idle`).
                this.maybe_emit_display_status_changed(&ws_id).await;
            }
        });

        // Store the abort handle with generation. Only insert if no entry exists or our
        // generation is newer (prevents older schedules from overwriting newer ones).
        if let Ok(mut map) = self.idle_debouncers.lock() {
            let should_insert = map
                .get(&workspace_id)
                .map(|(existing_gen, _)| gen > *existing_gen)
                .unwrap_or(true);

            if should_insert {
                if let Some((_, old_handle)) =
                    map.insert(workspace_id, (gen, handle.abort_handle()))
                {
                    old_handle.abort();
                }
            } else {
                // Our generation is older; abort this task immediately.
                handle.abort();
            }
        }
    }

    /// Raise the server-owned `attention` flag (§9.9) — the BE side of the
    /// blue dot. Persists `attention = level` and emits a self-sufficient
    /// `workspace:attention-changed` only when the value actually changes
    /// (§10.1). Best-effort: a missing workspace surfaces as an error.
    ///
    /// Raising `unread` never downgrades a persistent `review_required` flag
    /// (which only `workspace.dismissAttention` retires): the write is guarded
    /// on `attention = none`, so a completed turn on a review-required
    /// workspace is a no-op — no event.
    pub(crate) async fn raise_attention(
        &self,
        workspace_id: &WorkspaceId,
        level: WorkspaceAttention,
    ) -> Result<()> {
        self.park_attention_write().await;
        // Scoped, conditional write (monorepo#1481): set attention + bump
        // `updated_at` (raising IS activity) in one guarded UPDATE — never a
        // full-row replace, so a concurrent row mutation is never clobbered —
        // and let the write's row count decide "changed", so the
        // emit-only-on-change choice is atomic rather than read-based.
        let expected = match level {
            // Unread only promotes from a clear flag (see doc above).
            WorkspaceAttention::Unread => Some(WorkspaceAttention::None),
            _ => None,
        };
        let changed = self
            .store
            .set_workspace_attention(workspace_id, level, Some(&now_iso()), expected)
            .await?;
        if !changed {
            return Ok(());
        }
        publish_event(
            &self.event_bus,
            attention_changed_event(workspace_id, level),
        )
        .await;
        // Schedule debounced lastActivity event (§10.1).
        self.schedule_last_activity_event(workspace_id.clone());
        // The `unread` flag is not a displayStatus axis (§6.5), so the
        // turn-end unread raise (the sole caller) never moves the derived
        // rollup — skip the recompute (it would be a guaranteed no-op). A
        // non-`unread` raise can move the `review_required` axis, so
        // recompute-and-compare for those so the transition emits.
        if level != WorkspaceAttention::Unread {
            self.maybe_emit_display_status_changed(workspace_id).await;
        }
        Ok(())
    }

