    fn create_workspace(
        &self,
        input: WorkspaceCreate,
        idempotency_key: Option<String>,
    ) -> BoxFuture<'_, Result<WorkspaceCreateResult>> {
        let store = self.store.clone();
        let worktree_locks = self.worktree_locks.clone();
        let workspaces_root = self.workspaces_root.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        let settings_branch_prefix = settings::branch_prefix(&self.effective_settings());
        let cow_isolation = self.effective_settings().workspace.cow_isolation;
        let worktrees_location = settings::worktrees_location(&self.effective_settings());
        // Mirror-at-creation seed for the per-workspace auto-commit override
        // (spec Diagnosis §3b): the new row persists the global `git.autoCommit`
        // in force when the workspace is created.
        let global_auto_commit = self.effective_settings().git.auto_commit;
        // Startup pin (`INTENTD_WORKSPACES_DIR` → pinned `workspaces.root`)
        // keeps precedence over the `workspace.worktreesLocation` setting.
        let workspaces_root_pinned = self
            .settings_registry
            .as_deref()
            .and_then(|r| r.origin("workspaces.root"))
            == Some(SettingOrigin::Flag);
        Box::pin(async move {
            // Clone fields for logging (input moves into the closure below).
            let log_repo_path = input.repository_path.clone();
            let log_branch = input.branch.clone();

            // workspace.create carries no workspaceId → "" sentinel scope (§5.1).
            let op_store = store.clone();
            // Unified provisioning progress (PROTOCOL §5.1): when the request
            // carries a `progressId`, the closure below stashes its reporter
            // here so the wrapper can emit the exactly-one terminal
            // `git:clone:done` for every outcome — success or failure, in
            // every checkout mode. Stays empty on idempotent replays (the
            // closure never runs) and for requests without a `progressId`.
            let progress_slot: std::sync::Arc<
                std::sync::Mutex<Option<std::sync::Arc<create_progress::CreateProgress>>>,
            > = std::sync::Arc::new(std::sync::Mutex::new(None));
            let progress_slot_op = progress_slot.clone();
            // Kept at the wrapper so a failure BEFORE the closure arms the
            // slot (idempotency-store read/decode error, or an early config
            // error inside the closure such as an invalid
            // `workspace.worktreesLocation`) still gets its terminal
            // `ok:false` done below — no workspace id exists yet on those
            // paths, so that frame publishes under the empty sentinel id.
            let wrapper_progress_id = input
                .progress_id
                .as_deref()
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(str::to_string);
            let wrapper_bus = bus.clone();
            let result = with_idempotency(
                &store,
                "",
                idempotency_key,
                "workspace.create",
                move || async move {
                    let store = op_store;
                    let now = now_iso();
                    let mut input = input;
                    // Caller-supplied paths may carry a leading `~` (the FE
                    // onboarding default is `~/Developer`); expand to `$HOME`
                    // before the existing-repo check, clone targeting, and
                    // persistence — git would otherwise treat the tilde as a
                    // literal `./~` directory (intent-hq/monorepo#822).
                    if let Some(p) = input.repository_path.as_deref() {
                        input.repository_path = Some(intent_core::expand_tilde_string(p));
                    }
                    if let Some(p) = input.clone_path.as_deref() {
                        input.clone_path = Some(intent_core::expand_tilde_string(p));
                    }
                    // Unified provisioning progress (PROTOCOL §5.1): a
                    // client-supplied `progressId` arms a per-create reporter
                    // that echoes the id on every `git:clone:*` frame,
                    // normalizes percent to one non-decreasing 0–100 scale
                    // across all provisioning modes, and hands terminal-done
                    // ownership to the wrapper around this closure. Absent
                    // (or with no bus wired) every event path stays legacy.
                    let progress_id = input
                        .progress_id
                        .as_deref()
                        .map(str::trim)
                        .filter(|s| !s.is_empty())
                        .map(str::to_string);
                    // Kept alongside the resolved parent below: the known-repo
                    // registration hook checks BOTH roots (a configured
                    // `worktreesLocation` may differ from the boot root, and a
                    // path under either is daemon-managed storage).
                    let boot_root = workspaces_root
                        .clone()
                        .unwrap_or_else(default_workspaces_root);
                    let workspaces_root = resolve_workspaces_parent(
                        workspaces_root,
                        workspaces_root_pinned,
                        &worktrees_location,
                    )?;
                    // Workspace id derivation (TS `generateLocalSlug` parity):
                    // slug from the initial-agent prompt when possible, else a
                    // random adjective-animal pair; uniquified with a `-N`
                    // suffix whenever the id was ever used (live row, delete
                    // tombstone, or leftover directory) so the on-disk
                    // directory reflects intent and deleted ids are never
                    // recycled.
                    let id = derive_workspace_id(&store, &input, &workspaces_root).await;
                    let progress = progress_id.and_then(|pid| {
                        bus.clone().map(|b| {
                            std::sync::Arc::new(create_progress::CreateProgress::new(
                                b,
                                id.clone(),
                                pid,
                            ))
                        })
                    });
                    if let Some(reporter) = progress.clone() {
                        *progress_slot_op.lock().unwrap() = Some(reporter.clone());
                        reporter
                            .milestone("starting", 0, "Preparing workspace...")
                            .await;
                    }
                    // Clone orchestration (PROTOCOL §5.1): when `githubUrl` is
                    // set and `repositoryPath` is not already a local git
                    // repo, clone it *before* branch naming so the branch
                    // uniquification and worktree provisioning downstream see
                    // a real checkout. Progress is streamed under the newly
                    // minted `workspaceId`; a failure fails the whole create
                    // pre-insert (no row persisted, no partial state).
                    let existing_repo = input
                        .repository_path
                        .as_deref()
                        .filter(|p| !p.is_empty())
                        .map(PathBuf::from)
                        .filter(|p| p.join(".git").exists());
                    // Cache-hydration state: set when `githubUrl` is present
                    // without a `clonePath` — the workspace checkout is
                    // provisioned from the repo cache in the provisioning
                    // section below (after branch naming). Carries the cache
                    // path and the original GitHub URL (for the `direct`
                    // fallback's origin retarget).
                    let mut cache_hydration: Option<(PathBuf, String)> = None;
                    // `isNewRepo` creates work directly in the initialized
                    // repository folder (checkoutMode `direct`, no worktree).
                    let mut new_repo_direct = false;
                    if existing_repo.is_none() {
                        if let Some(url) = input
                            .github_url
                            .as_deref()
                            .map(str::trim)
                            .filter(|s| !s.is_empty())
                        {
                            let bus_ref = bus.clone().ok_or_else(|| {
                                Error::Internal(
                                    "event bus not wired; workspace.create clone requires streaming"
                                        .to_string(),
                                )
                            })?;
                            // Cache hydration (PROTOCOL §5.1): a `githubUrl`
                            // WITHOUT a `clonePath` hydrates the workspace
                            // from the daemon-managed repo cache
                            // (`<workspaces_root>/.repo-cache/<owner>/<repo>`)
                            // instead of cloning into `<root>/clones/`. The
                            // cache is ensured (cloned or refreshed) here —
                            // the network phase — and the standalone checkout
                            // is provisioned below, after branch naming. An
                            // explicit `clonePath` keeps the legacy network
                            // clone exactly (back-compat for older FE), as do
                            // URLs that carry no `owner/repo` pair (no cache
                            // slot to hydrate from).
                            let explicit_clone_path = input
                                .clone_path
                                .as_deref()
                                .map(str::trim)
                                .filter(|s| !s.is_empty())
                                .is_some();
                            // Hydration also requires that a checkout will
                            // actually be provisioned below: remote /
                            // `skipWorktree` / caller-supplied `worktreePath`
                            // creates keep the legacy network clone, whose
                            // `repositoryPath` exists without provisioning.
                            let provisions_checkout = !input.is_remote.unwrap_or(false)
                                && !input.skip_isolation.unwrap_or(false)
                                && input
                                    .worktree_path
                                    .as_deref()
                                    .is_none_or(|p| p.is_empty());
                            let cache_owner_repo = if explicit_clone_path
                                || !provisions_checkout
                            {
                                None
                            } else {
                                clone_ops::parse_owner_repo(url)
                            };
                            if let Some((owner, name)) = cache_owner_repo {
                                let request_id = uuid::Uuid::new_v4().to_string();
                                // Stream the same `git:clone:*` frames as a
                                // network clone so the FE initializer shows
                                // progress: a starting tick, the cache
                                // ensure (the only network-bound phase), and
                                // a terminal done. Checkout provisioning
                                // below is local-only, matching the legacy
                                // flow where worktree provisioning runs
                                // after `git:clone:done`. With a reporter
                                // armed the frames route through it instead
                                // (new `cache` phase, unified percent, no
                                // terminal frames here — the wrapper owns
                                // the exactly-one done).
                                match progress.as_deref() {
                                    Some(reporter) => {
                                        reporter
                                            .milestone(
                                                "cache",
                                                5,
                                                "Preparing repository cache...",
                                            )
                                            .await;
                                    }
                                    None => {
                                        clone_ops::publish(
                                            &bus_ref,
                                            &id,
                                            clone_ops::progress_event(
                                                &id,
                                                &request_id,
                                                "starting",
                                                0,
                                                "Preparing repository cache...",
                                                None,
                                            ),
                                        )
                                        .await;
                                    }
                                }
                                let token = github_git_token_for_url(
                                    services.settings_registry.as_deref(),
                                    url,
                                )
                                .await;
                                let cache_root = workspaces_root.join(".repo-cache");
                                // Real streaming progress for the ensure: the
                                // callback forwards raw git output to a pump
                                // task that parses it (submodule-aware) and
                                // reports on the unified scale. Await the pump
                                // after the ensure so buffered frames flush
                                // before the "cache ready" milestone.
                                let (ensure_progress, ensure_pump) = match progress.clone() {
                                    Some(reporter) => {
                                        let (cb, pump) =
                                            create_progress::cache_ensure_reporter(reporter);
                                        (Some(cb), Some(pump))
                                    }
                                    None => (None, None),
                                };
                                let ensure_result =
                                    intent_git::repo_cache::ensure_cached_repo_with_progress(
                                        &cache_root,
                                        url,
                                        &owner,
                                        &name,
                                        token.as_deref(),
                                        ensure_progress,
                                    )
                                    .await;
                                if let Some(pump) = ensure_pump {
                                    // Bounded: on the ensure's timeout path a
                                    // lingering grandchild (e.g.
                                    // git-remote-https) can hold the pipe —
                                    // and thus a callback clone — open
                                    // indefinitely; don't let it delay error
                                    // surfacing (buffered frames only matter
                                    // cosmetically there).
                                    let _ = tokio::time::timeout(
                                        std::time::Duration::from_secs(5),
                                        pump,
                                    )
                                    .await;
                                }
                                let cache_path = match ensure_result {
                                    Ok(path) => path,
                                    Err(e) => {
                                        // Legacy-clone parity: redact any
                                        // credential-bearing URL before the
                                        // detail reaches events, errors, or
                                        // logs (repo_cache redacts git stderr
                                        // at source; this also covers wrapper
                                        // messages embedding the URL).
                                        let detail = clone_ops::redact_credentials(&match e {
                                            Error::Internal(msg) => msg,
                                            other => other.to_string(),
                                        });
                                        let category =
                                            clone_ops::classify_clone_error(&detail);
                                        let error_code = (category
                                            != intent_core::CloneErrorCategory::Other)
                                            .then_some(category);
                                        // Reporter-armed creates defer the
                                        // terminal done to the wrapper (which
                                        // sees this same CloneFailed error).
                                        if progress.is_none() {
                                            clone_ops::publish(
                                                &bus_ref,
                                                &id,
                                                clone_ops::done_event(
                                                    &id,
                                                    &request_id,
                                                    false,
                                                    Some(&detail),
                                                    error_code,
                                                    None,
                                                ),
                                            )
                                            .await;
                                        }
                                        return Err(Error::CloneFailed {
                                            category,
                                            detail,
                                        });
                                    }
                                };
                                match progress.as_deref() {
                                    Some(reporter) => {
                                        reporter
                                            .milestone(
                                                "cache",
                                                create_progress::CLONE_SEGMENT_END,
                                                "Repository cache ready",
                                            )
                                            .await;
                                    }
                                    None => {
                                        clone_ops::publish(
                                            &bus_ref,
                                            &id,
                                            clone_ops::progress_event(
                                                &id,
                                                &request_id,
                                                "checkout",
                                                90,
                                                "Repository cache ready",
                                                None,
                                            ),
                                        )
                                        .await;
                                        clone_ops::publish(
                                            &bus_ref,
                                            &id,
                                            clone_ops::done_event(
                                                &id,
                                                &request_id,
                                                true,
                                                None,
                                                None,
                                                None,
                                            ),
                                        )
                                        .await;
                                    }
                                }
                                if input.repository_owner.is_none() {
                                    input.repository_owner = Some(owner);
                                }
                                if input.repository_name.is_none() {
                                    input.repository_name = Some(name.clone());
                                }
                                // The workspace checkout IS the repository
                                // (self-contained; the cache can be deleted
                                // safely). It lives at the same
                                // `<root>/<wsId>/<repo-slug>` the worktree
                                // path would use.
                                let repo_slug_name = input
                                    .repository_name
                                    .clone()
                                    .filter(|n| !n.is_empty())
                                    .unwrap_or(name);
                                let checkout_dir = workspaces_root
                                    .join(&id.0)
                                    .join(worktree_folder_slug(&repo_slug_name));
                                input.repository_path =
                                    Some(checkout_dir.to_string_lossy().to_string());
                                cache_hydration = Some((cache_path, url.to_string()));
                            } else {
                            let target = match input.clone_path.as_deref() {
                                Some(p) if !p.trim().is_empty() => PathBuf::from(p),
                                _ => workspaces_root
                                    .join("clones")
                                    .join(clone_ops::derive_default_target(url)),
                            };
                            if target.as_os_str().is_empty()
                                || target
                                    .file_name()
                                    .map(|n| n.is_empty())
                                    .unwrap_or(true)
                            {
                                return Err(Error::CloneFailed {
                                    category: intent_core::CloneErrorCategory::PathInvalid,
                                    detail: "clonePath must resolve to a non-empty target"
                                        .to_string(),
                                });
                            }
                            if clone_ops::target_exists_non_empty(&target) {
                                return Err(Error::CloneFailed {
                                    category:
                                        intent_core::CloneErrorCategory::DestinationExistsNonEmpty,
                                    detail: format!(
                                        "clone target already exists and is not empty: {}",
                                        target.display()
                                    ),
                                });
                            }
                            let request_id = uuid::Uuid::new_v4().to_string();
                            // Resolve a GitHub token for private HTTPS
                            // github.com clones (monorepo#825). SSH and
                            // non-GitHub URLs skip resolution entirely; the
                            // value travels to the child via the environment
                            // only and is never logged.
                            let token = github_git_token_for_url(
                                services.settings_registry.as_deref(),
                                url,
                            )
                            .await;
                            // Clone failures surface as a typed error carrying
                            // the sanitized stderr tail so clients can show the
                            // underlying cause (monorepo#826). The category was
                            // decided once inside `run_clone` — shared with the
                            // streamed `git:clone:done.errorCode` — with `None`
                            // (spawn/wait failures) mapping to the `clone-failed`
                            // catch-all (PROTOCOL §9.1).
                            clone_ops::perform_clone(clone_ops::CloneJob {
                                request_id,
                                workspace_id: Some(id.clone()),
                                url: url.to_string(),
                                target_path: target.clone(),
                                token,
                                bus: bus_ref,
                                progress: progress.clone(),
                                // Workspace checkouts should land with
                                // populated submodules, like the cache
                                // hydration path (decision 2026-08-10).
                                recurse_submodules: true,
                            })
                            .await
                            .map_err(|failure| Error::CloneFailed {
                                category: failure
                                    .category
                                    .unwrap_or(intent_core::CloneErrorCategory::Other),
                                detail: failure.detail,
                            })?;
                            input.repository_path =
                                Some(target.to_string_lossy().to_string());
                            if let Some((owner, name)) = clone_ops::parse_owner_repo(url) {
                                if input.repository_owner.is_none() {
                                    input.repository_owner = Some(owner);
                                }
                                if input.repository_name.is_none() {
                                    input.repository_name = Some(name);
                                }
                            }
                            }
                        } else if input.is_new_repo.unwrap_or(false) {
                            // New-project flow (intent-hq/monorepo#962): the FE
                            // marks non-git / not-yet-existing folders with
                            // `isNewRepo: true` expecting the daemon to
                            // initialize them. Reuse the
                            // `workspace.initializeRepository` blocking body
                            // *before* branch naming so the downstream worktree
                            // provisioning sees a real checkout; a failure
                            // fails the whole create pre-insert (no row
                            // persisted, no `workspace:created`), matching the
                            // clone-failure rule (PROTOCOL §5.1). Skipped when
                            // a `githubUrl` clone is in play (above). A
                            // missing/empty `repositoryPath` is a client bug —
                            // reject with `-32602` rather than fall through to
                            // the silent row-only path #962 eliminates.
                            let repo_path = input
                                .repository_path
                                .as_deref()
                                .filter(|p| !p.is_empty())
                                .map(PathBuf::from)
                                .ok_or_else(|| {
                                    Error::InvalidParams(
                                        "repositoryPath is required when isNewRepo is true"
                                            .to_string(),
                                    )
                                })?;
                            initialize_repository_for_create(repo_path).await?;
                            new_repo_direct = true;
                        }
                    } else if input.is_new_repo.unwrap_or(false)
                        && input
                            .github_url
                            .as_deref()
                            .map(str::trim)
                            .filter(|s| !s.is_empty())
                            .is_none()
                    {
                        // Half-initialized recovery (#962 review): a mid-init
                        // failure can leave `.git` without a resolvable HEAD,
                        // which the bare `.git`-existence gate above counts as
                        // an existing repo — a retried create would then skip
                        // init and fail downstream provisioning on the base
                        // ref. Re-run the init for `isNewRepo` creates: it
                        // no-ops when HEAD already resolves, so healthy repos
                        // are untouched, and the clone arm plus legacy
                        // (non-`isNewRepo`) behavior stay unchanged.
                        if let Some(repo_path) = existing_repo.clone() {
                            initialize_repository_for_create(repo_path).await?;
                        }
                        new_repo_direct = true;
                    }
                    // Repository owner/name derivation from origin remote (STAB-64):
                    // when `repositoryPath` is a local git repo and the caller left
                    // `repositoryOwner` and/or `repositoryName` blank, best-effort
                    // derive them from the `origin` remote URL (local inspection
                    // only, no network). Only GitHub remotes are parsed; non-github
                    // or missing remotes leave owner unset. Caller-supplied values
                    // always win; basename fallback for `repositoryName` stays as
                    // the last resort.
                    let origin_derived = if let Some(repo_path) = input
                        .repository_path
                        .as_deref()
                        .filter(|p| !p.is_empty())
                        .map(PathBuf::from)
                        .filter(|p| p.join(".git").exists())
                    {
                        intent_git::remote::origin_url(&repo_path)
                            .ok()
                            .flatten()
                            .and_then(|url| Self::parse_github_owner_repo(&url))
                    } else {
                        None
                    };
                    // Apply derived owner when caller left it blank.
                    if input
                        .repository_owner
                        .as_deref().is_none_or(|o| o.is_empty())
                    {
                        if let Some((owner, _)) = origin_derived.as_ref() {
                            input.repository_owner = Some(owner.clone());
                        }
                    }
                    // Apply derived name when caller left it blank; fall back to
                    // basename when origin remote is missing/unparseable.
                    if input
                        .repository_name
                        .as_deref().is_none_or(|n| n.is_empty())
                    {
                        if let Some((_, name)) = origin_derived {
                            input.repository_name = Some(name);
                        } else if let Some(name) = input
                            .repository_path
                            .as_deref()
                            .filter(|p| !p.is_empty())
                            .and_then(derive_repo_name_from_path)
                        {
                            input.repository_name = Some(name);
                        }
                    }
                    // Branch naming (TS parity): an explicit `branch` wins
                    // untouched; otherwise the branch is a friendly slug —
                    // extracted from `initialAgent.prompt` when possible
                    // (`generateLocalSlug`), else a random adjective-animal
                    // pair (`generateWorkspaceSlug`) — under the optional
                    // `workspace.branchPrefix` setting, uniquified against
                    // existing local/remote branches with a `-N` suffix.
                    let branch_auto_generated =
                        input.branch.as_deref().is_none_or(|b| b.is_empty());
                    let branch = match input.branch.clone().filter(|b| !b.is_empty()) {
                        Some(explicit) => explicit,
                        None => {
                            let slug = input
                                .initial_agent
                                .as_ref()
                                .and_then(|a| a.prompt.as_deref())
                                .and_then(intent_core::slug::extract_local_slug)
                                .unwrap_or_else(intent_core::slug::generate_workspace_slug);
                            // Branch prefix fallback: repo config > global setting
                            // (FE parity: workspace.service.ts L1215-1219).
                            let prefix = if let Some(repo_path) = input
                                .repository_path
                                .as_deref()
                                .filter(|p| !p.is_empty())
                                .map(PathBuf::from)
                            {
                                let repo_config = crate::repo_config::read_repo_config(&repo_path).await;
                                match repo_config.branch_prefix.filter(|p| !p.is_empty()) {
                                    Some(p) => p,
                                    None => settings_branch_prefix,
                                }
                            } else {
                                settings_branch_prefix
                            };
                            let desired = format!("{prefix}{slug}");
                            let git_repo = input
                                .repository_path
                                .as_deref()
                                .filter(|p| !p.is_empty())
                                .map(PathBuf::from)
                                .filter(|p| p.join(".git").exists());
                            match git_repo {
                                Some(repo) => {
                                    let want = desired;
                                    tokio::task::spawn_blocking(move || {
                                        intent_git::branches::ensure_unique_branch_name(
                                            &repo, &want,
                                        )
                                    })
                                    .await
                                    .map_err(|e| {
                                        Error::Internal(format!(
                                            "branch uniquification task failed: {e}"
                                        ))
                                    })??
                                }
                                None => desired,
                            }
                        }
                    };
                    // Normalise the caller-supplied title: trim surrounding
                    // whitespace so whitespace-only titles collapse to `""`,
                    // and default to `""` when the caller omits the field
                    // entirely. Matches the reference `workspace.service`
                    // shape (`title: request.title || ''`), with the added
                    // trim to keep persistence consistent with the rest of
                    // the daemon's title-emptiness guards. The FE renders
                    // `""` as "Untitled" until the initial agent's first-turn
                    // naming instruction calls `workspace.setTitle`. The
                    // `hasTitle` binding keeps its `title != id` guard as
                    // belt-and-braces for legacy rows the data heal has not
                    // yet touched.
                    let title = input
                        .title
                        .map(|t| t.trim().to_string())
                        .unwrap_or_default();
                    // Setup script param is execute-only (§5.1): an explicit
                    // non-empty `setupScript` executes as supplied for this create
                    // (taking precedence over the committed repo-config script) but
                    // is never persisted — no repo-config merge-write, no DB
                    // `setup_script` write. Explicit persistence stays with
                    // `workspace.saveSetupScript` / `repoConfig.*`. The workspace
                    // DB row's `setup_script` column stays NULL (wire compat) and
                    // the read path (§5.25) routes through the repo config with a
                    // legacy fallback. Stash the explicit script for the execution
                    // spawn AFTER worktree provisioning.
                    let explicit_setup_script = input.setup_script.clone().filter(|s| !s.is_empty());
                    let mut ws = Workspace {
                        id,
                        title,
                        branch,
                        // Canonicalise the wire `baseRef` on write so the
                        // persisted value is the plain branch name — a PR's
                        // `sourceBranch` (never remote-qualified) compares
                        // raw-equal without FE-side stripping (§7.6).
                        base_ref: input.base_ref.map(|r| canonicalise_base_ref(&r)),
                        base_commit_sha: input.base_commit_sha,
                        status: WorkspaceStatus::Active,
                        status_message: input.status_message,
                        status_image_asset_id: None,
                        // Derived, read-only; never persisted (§9.9).
                        activity: WorkspaceActivity::Idle,
                        attention: WorkspaceAttention::None,
                        created_at: now.clone(),
                        updated_at: now.clone(),
                        // Stamp `lastActivity` at create so it is always
                        // populated — the emit path (§9.1) still enriches
                        // with the max of notes / agents / updatedAt.
                        last_activity: Some(now),
                        tags: input.tags.unwrap_or_default(),
                        path: input.path,
                        repository_path: input.repository_path,
                        repository_owner: input.repository_owner,
                        repository_name: input.repository_name,
                        worktree_path: input.worktree_path,
                        scope: input.scope,
                        skip_worktree: input.skip_isolation.unwrap_or(false),
                        setup_script: None,
                        is_remote: input.is_remote.unwrap_or(false),
                        default_model: input.default_model,
                        pr_number: None,
                        pr_url: None,
                        pr_status: None,
                        active_pull_request: None,
                        pull_requests: None,
                        archived: false,
                        archived_at: None,
                        // Card aggregates are computed on the list/get emit path only.
                        task_stats: None,
                        agent_summary: None,
                        diff_summary: None,
                        token_usage: None,
                        cow_supported: None,
                        display_status: None,
                        waiting: false,
                        checkout_mode: None,
                        disk_usage: None,
                        pending_delete_at: None,
                    };
                    // Provision the workspace checkout (TS `createGitWorktree`
                    // parity): a local workspace created off a local git repo
                    // gets a checkout at `<root>/<workspaceId>/<repo-slug>` on
                    // its branch, so agents spawn inside a real checkout instead
                    // of falling back to a temp dir. When `workspace.cowIsolation`
                    // is on, the checkout is a standalone CoW clone of the repo
                    // dir (deps/build artifacts carried over) instead of a
                    // linked worktree — and an Unsupported/failed probe falls
                    // back to the linked-worktree path (the setting is a
                    // preference, not a guarantee).
                    // Skipped for remote/`skipWorktree` workspaces, callers
                    // supplying their own `worktreePath`, and repository paths
                    // that are not a local git repo (registry-only rows keep
                    // the prior behavior).
                    let has_worktree = ws
                        .worktree_path
                        .as_deref()
                        .is_some_and(|p| !p.is_empty());
                    let repo_dir = ws
                        .repository_path
                        .as_deref()
                        .filter(|p| !p.is_empty())
                        .map(PathBuf::from);
                    let workspaces_root_pathbuf = workspaces_root.clone();
                    if let Some((cache_path, hydration_url)) = cache_hydration {
                        // Cache hydration (PROTOCOL §5.1): provision a
                        // **standalone** checkout from the repo cache at the
                        // `repositoryPath` chosen in the clone arm above
                        // (`<root>/<wsId>/<repo-slug>`). Never a linked
                        // worktree against the cache — a cache refresh
                        // hard-resets/re-clones the cache dir, which would
                        // corrupt linked worktrees. CoW clone when the
                        // filesystem supports it (mode `cow`, parity with
                        // cowIsolation checkouts), else a plain local clone
                        // from the cache (mode `direct`). Provisioning runs
                        // under the per-repo cache lock so a concurrent
                        // create's cache refresh cannot mutate the cache
                        // mid-copy.
                        // The clone arm only arms hydration when a checkout
                        // will be provisioned here (its `provisions_checkout`
                        // gate mirrors this guard). If the two ever diverge,
                        // `repositoryPath` would dangle at a directory that
                        // was never created — fail loudly instead of
                        // persisting a broken row.
                        if ws.is_remote || ws.skip_worktree || has_worktree {
                            return Err(Error::Internal(
                                "workspace.create: cache hydration armed but checkout provisioning is skipped (guard divergence)"
                                    .to_string(),
                            ));
                        }
                        {
                            let checkout_path = repo_dir.clone().ok_or_else(|| {
                                Error::Internal(
                                    "workspace.create: cache hydration lost its checkout path"
                                        .to_string(),
                                )
                            })?;
                            let ws_dir = workspaces_root_pathbuf.join(&ws.id.0);
                            std::fs::create_dir_all(&ws_dir).map_err(|e| {
                                Error::Internal(format!(
                                    "cannot create workspace dir for cache hydration: {e}"
                                ))
                            })?;
                            let probe_cache = cache_path.clone();
                            let probe_dst = ws_dir.clone();
                            let support = tokio::task::spawn_blocking(move || {
                                intent_git::cow_probe(&probe_cache, &probe_dst)
                            })
                            .await
                            .map_err(|e| {
                                Error::Internal(format!("CoW probe task failed: {e}"))
                            })?;
                            let mut mode = match support {
                                Ok(intent_git::CowSupport::Supported) => {
                                    intent_core::CheckoutMode::Cow
                                }
                                Ok(intent_git::CowSupport::Unsupported) => {
                                    intent_core::CheckoutMode::Direct
                                }
                                Err(e) => {
                                    tracing::warn!(
                                        cache = %cache_path.display(),
                                        error = %e,
                                        "workspace.create: CoW probe failed; hydrating via local clone (direct)"
                                    );
                                    intent_core::CheckoutMode::Direct
                                }
                            };
                            // Provisioning milestone on the unified scale
                            // (85–100 segment): the copy/checkout is the
                            // slow local step between the cache ensure and
                            // the row insert.
                            if let Some(reporter) = progress.as_deref() {
                                match mode {
                                    intent_core::CheckoutMode::Cow => {
                                        reporter
                                            .milestone("cow-copy", 88, "Copying repository...")
                                            .await
                                    }
                                    _ => {
                                        reporter
                                            .milestone(
                                                "checkout",
                                                88,
                                                "Checking out repository...",
                                            )
                                            .await
                                    }
                                }
                            }
                            let branch = ws.branch.clone();
                            let base_ref = ws.base_ref.clone();
                            let provision_progress = progress.clone();
                            let provision = |mode: intent_core::CheckoutMode| {
                                let cache = cache_path.clone();
                                let checkout = checkout_path.clone();
                                let branch = branch.clone();
                                let base_ref = base_ref.clone();
                                let url = hydration_url.clone();
                                let progress = provision_progress.clone();
                                async move {
                                    let lock_cache = cache.clone();
                                    // Direct hydration streams its submodule
                                    // population through the reporter (the
                                    // update's `--progress` output, mapped
                                    // into the provisioning tail); the pump
                                    // is awaited after the blocking work so
                                    // buffered frames flush in order.
                                    let (sub_chunk, sub_pump) = match (
                                        mode,
                                        progress,
                                    ) {
                                        (
                                            intent_core::CheckoutMode::Direct,
                                            Some(reporter),
                                        ) => {
                                            let (cb, pump) =
                                                create_progress::submodule_hydration_reporter(
                                                    reporter,
                                                );
                                            (Some(cb), Some(pump))
                                        }
                                        _ => (None, None),
                                    };
                                    let result = intent_git::repo_cache::with_cache_lock_blocking(
                                        &lock_cache,
                                        move || match mode {
                                            intent_core::CheckoutMode::Cow => {
                                                // No cowCloneExclude here (unlike
                                                // the cowIsolation arm below):
                                                // the source is the pristine
                                                // cache clone — tracked files
                                                // only, no deps/build artifacts
                                                // for excludes to skip.
                                                let sha =
                                                    intent_git::cow_checkout::provision_cow_checkout(
                                                        &cache,
                                                        &checkout,
                                                        &branch,
                                                        base_ref.as_deref(),
                                                        "origin",
                                                        &[],
                                                    )?;
                                                // The CoW clone inherits the
                                                // cache's `origin` (already the
                                                // GitHub URL); retarget
                                                // explicitly so the checkout
                                                // never references the cache
                                                // even if the cache was seeded
                                                // differently.
                                                intent_git::remote::set_remote_url(
                                                    &checkout, "origin", &url,
                                                )?;
                                                Ok(sha)
                                            }
                                            intent_core::CheckoutMode::Direct => {
                                                intent_git::repo_cache::provision_direct_checkout_with_progress(
                                                    &cache,
                                                    &checkout,
                                                    &url,
                                                    &branch,
                                                    base_ref.as_deref(),
                                                    sub_chunk,
                                                )
                                            }
                                            intent_core::CheckoutMode::Worktree => {
                                                Err(Error::Internal(
                                                    "cache hydration never provisions a linked worktree"
                                                        .to_string(),
                                                ))
                                            }
                                        },
                                    )
                                    .await;
                                    if let Some(pump) = sub_pump {
                                        // Bounded for the same reason as the
                                        // ensure pump: a lingering grandchild
                                        // can hold the callback open.
                                        let _ = tokio::time::timeout(
                                            std::time::Duration::from_secs(5),
                                            pump,
                                        )
                                        .await;
                                    }
                                    result
                                }
                            };
                            let sha = match provision(mode).await {
                                Ok(sha) => sha,
                                Err(Error::Unsupported(reason))
                                    if mode == intent_core::CheckoutMode::Cow =>
                                {
                                    // Safety net: the probe passed but the
                                    // clone itself was still unsupported.
                                    // Fall back to the plain local clone.
                                    tracing::warn!(
                                        cache = %cache_path.display(),
                                        reason = %reason,
                                        "workspace.create: CoW hydration unsupported despite a passing probe; retrying as a local clone (direct)"
                                    );
                                    remove_workspace_dir_if_empty(&ws_dir);
                                    mode = intent_core::CheckoutMode::Direct;
                                    match provision(mode).await {
                                        Ok(sha) => sha,
                                        Err(e) => {
                                            remove_workspace_dir_if_empty(&ws_dir);
                                            return Err(e);
                                        }
                                    }
                                }
                                Err(e) => {
                                    // The provisioning helpers already removed
                                    // the failed checkout; drop the
                                    // `<root>/<wsId>` parent if left empty so a
                                    // failed create leaves the workspaces root
                                    // clean (#774).
                                    remove_workspace_dir_if_empty(&ws_dir);
                                    return Err(e);
                                }
                            };
                            ws.worktree_path =
                                Some(checkout_path.to_string_lossy().to_string());
                            ws.checkout_mode = Some(mode);
                            if ws.base_commit_sha.is_none() {
                                ws.base_commit_sha = Some(sha);
                            }
                        }
                    } else if new_repo_direct {
                        // `isNewRepo` creates work directly in the initialized
                        // repository folder: a standalone repo, no worktree
                        // provisioned (checkoutMode `direct`). Create + check
                        // out the workspace branch there so agents land on
                        // `ws.branch` as with every other checkout mode.
                        if let Some(repo_dir) = repo_dir {
                            if !ws.is_remote
                                && !ws.skip_worktree
                                && !has_worktree
                                && repo_dir.join(".git").exists()
                            {
                                // Direct-mode milestone (unified scale): the
                                // branch checkout is the only provisioning
                                // step on this fast path.
                                if let Some(reporter) = progress.as_deref() {
                                    reporter
                                        .milestone(
                                            "checkout",
                                            50,
                                            "Checking out workspace branch...",
                                        )
                                        .await;
                                }
                                let branch = ws.branch.clone();
                                let base_ref = ws.base_ref.clone();
                                let repo = repo_dir.clone();
                                let sha = worktree_locks
                                    .with_lock(&repo_dir, move || async move {
                                        tokio::task::spawn_blocking(move || {
                                            // Reuse an existing branch of the
                                            // same name (retried create), else
                                            // create it — at the caller's
                                            // `baseRef` when supplied
                                            // (provision_worktree parity),
                                            // else from HEAD; then check it
                                            // out and report HEAD's SHA.
                                            if intent_git::branches::checkout_branch(
                                                &repo, &branch,
                                            )
                                            .is_err()
                                            {
                                                match base_ref
                                                    .as_deref()
                                                    .filter(|r| !r.is_empty())
                                                {
                                                    Some(base) => {
                                                        intent_git::branches::create_branch_at(
                                                            &repo, &branch, base,
                                                        )?
                                                    }
                                                    None => {
                                                        intent_git::branches::create_branch(
                                                            &repo, &branch, true,
                                                        )?
                                                    }
                                                }
                                            }
                                            intent_git::refs::rev_parse(&repo, "HEAD")
                                        })
                                        .await
                                        .map_err(|e| {
                                            Error::Internal(format!(
                                                "branch checkout task failed: {e}"
                                            ))
                                        })?
                                    })
                                    .await?;
                                ws.checkout_mode = Some(intent_core::CheckoutMode::Direct);
                                // The repository folder IS the checkout:
                                // persist it as `worktreePath` (standalone-row
                                // parity with cache hydration) so agent spawn
                                // cwd resolution and the workspace file
                                // watcher see the checkout
                                // (intent-hq/monorepo#2611). The delete
                                // cleanup never trashes it — its standalone
                                // arm is gated on the daemon-owned
                                // `<parent>/<wsId>/<slug>` layout, which a
                                // user-chosen folder never matches.
                                ws.worktree_path =
                                    Some(repo_dir.to_string_lossy().into_owned());
                                if ws.base_commit_sha.is_none() {
                                    ws.base_commit_sha = Some(sha);
                                }
                            }
                        }
                    } else if let Some(repo_dir) = repo_dir {
                        if !ws.is_remote && !ws.skip_worktree && !has_worktree {
                            if repo_dir.join(".git").exists() {
                                let repo_name = known_repo_name(
                                    ws.repository_name.as_deref(),
                                    &repo_dir.to_string_lossy(),
                                );
                                let ws_dir = workspaces_root_pathbuf.join(&ws.id.0);
                                let wt_path =
                                    ws_dir.join(worktree_folder_slug(&repo_name));
                                let name = ws.id.0.clone();
                                let branch = ws.branch.clone();
                                let base_ref = ws.base_ref.clone();
                                let remote =
                                    input.remote.unwrap_or_else(|| "origin".to_string());
                                let mut mode = if cow_isolation
                                    && repo_dir.join(".git").is_file()
                                {
                                    // A linked worktree's `.git` is a gitfile
                                    // pointing into the original repository's
                                    // `.git/worktrees/<name>`: CoW-cloning it
                                    // would give the clone a `.git` that still
                                    // points at the ORIGINAL repo, so the
                                    // branch switch + hard reset would rewrite
                                    // the user's source checkout. Provision a
                                    // linked worktree instead.
                                    tracing::warn!(
                                        repository_path = %repo_dir.display(),
                                        "workspace.create: repositoryPath has a gitfile .git (linked worktree or submodule checkout); CoW-cloning it would corrupt the source checkout — provisioning a linked worktree instead"
                                    );
                                    intent_core::CheckoutMode::Worktree
                                } else if cow_isolation {
                                    // CoW probe: repo dir → `<root>/<wsId>` (the
                                    // clone's parent). The repository can live on
                                    // any filesystem and reflinks cannot cross
                                    // volumes, so Unsupported (or a probe error)
                                    // falls back to a linked worktree instead of
                                    // failing the create — `workspace.cowIsolation`
                                    // is a preference, not a guarantee.
                                    std::fs::create_dir_all(&ws_dir).map_err(|e| {
                                        Error::Internal(format!(
                                            "cannot create workspace dir for CoW probe: {e}"
                                        ))
                                    })?;
                                    let probe_repo = repo_dir.clone();
                                    let probe_dst = ws_dir.clone();
                                    let support = tokio::task::spawn_blocking(move || {
                                        intent_git::cow_probe(&probe_repo, &probe_dst)
                                    })
                                    .await
                                    .map_err(|e| {
                                        Error::Internal(format!(
                                            "CoW probe task failed: {e}"
                                        ))
                                    })?;
                                    match support {
                                        Ok(intent_git::CowSupport::Supported) => {
                                            intent_core::CheckoutMode::Cow
                                        }
                                        Ok(intent_git::CowSupport::Unsupported) => {
                                            tracing::warn!(
                                                repository_path = %repo_dir.display(),
                                                workspaces_root = %workspaces_root_pathbuf.display(),
                                                "workspace.create: CoW isolation is enabled but the repository's filesystem cannot CoW-clone into the workspaces root; falling back to a linked worktree"
                                            );
                                            intent_core::CheckoutMode::Worktree
                                        }
                                        Err(e) => {
                                            tracing::warn!(
                                                repository_path = %repo_dir.display(),
                                                error = %e,
                                                "workspace.create: CoW probe failed; falling back to a linked worktree"
                                            );
                                            intent_core::CheckoutMode::Worktree
                                        }
                                    }
                                } else {
                                    intent_core::CheckoutMode::Worktree
                                };
                                // Local-repo provisioning milestone (unified
                                // scale): the CoW copy / worktree add is the
                                // dominant step of a local create, so it sits
                                // mid-scale (no clone segment ran before it;
                                // after a network clone the monotonic clamp
                                // lifts it to the 85+ tail automatically).
                                if let Some(reporter) = progress.as_deref() {
                                    match mode {
                                        intent_core::CheckoutMode::Cow => {
                                            reporter
                                                .milestone(
                                                    "cow-copy",
                                                    30,
                                                    "Copying repository (CoW)...",
                                                )
                                                .await
                                        }
                                        _ => {
                                            reporter
                                                .milestone(
                                                    "worktree",
                                                    30,
                                                    "Creating linked worktree...",
                                                )
                                                .await
                                        }
                                    }
                                }
                                let provision = |mode: intent_core::CheckoutMode| {
                                    let name = name.clone();
                                    let branch = branch.clone();
                                    let base_ref = base_ref.clone();
                                    let remote = remote.clone();
                                    let repo = repo_dir.clone();
                                    let wt = wt_path.clone();
                                    let locks = worktree_locks.clone();
                                    let lock_key = repo_dir.clone();
                                    async move {
                                        // `cowCloneExclude` comes from the
                                        // source repo's config; only the CoW
                                        // clone path consumes it.
                                        let clone_excludes =
                                            if mode == intent_core::CheckoutMode::Cow {
                                                repo_config::read_repo_config(&repo)
                                                    .await
                                                    .cow_clone_exclude
                                                    .unwrap_or_default()
                                            } else {
                                                Vec::new()
                                            };
                                        let lock_requested = std::time::Instant::now();
                                        locks
                                            .with_lock(&lock_key, move || async move {
                                                let lock_wait = lock_requested.elapsed();
                                                let provision_started =
                                                    std::time::Instant::now();
                                                let repo_for_log = repo.clone();
                                                let result = match tokio::task::spawn_blocking(
                                                    move || match mode {
                                                        intent_core::CheckoutMode::Cow => {
                                                            intent_git::cow_checkout::provision_cow_checkout(
                                                                &repo,
                                                                &wt,
                                                                &branch,
                                                                base_ref.as_deref(),
                                                                &remote,
                                                                &clone_excludes,
                                                            )
                                                        }
                                                        intent_core::CheckoutMode::Worktree => {
                                                            intent_git::worktree::provision_worktree(
                                                                &repo,
                                                                &name,
                                                                &wt,
                                                                &branch,
                                                                base_ref.as_deref(),
                                                                &remote,
                                                            )
                                                        }
                                                        // Local-repo creates never
                                                        // select `direct` (cache
                                                        // hydration has its own
                                                        // provisioning arm above).
                                                        intent_core::CheckoutMode::Direct => {
                                                            Err(Error::Internal(
                                                                "direct checkout mode is not provisioned from a local repository"
                                                                    .to_string(),
                                                            ))
                                                        }
                                                    },
                                                )
                                                .await
                                                {
                                                    Ok(r) => r,
                                                    Err(e) => Err(Error::Internal(format!(
                                                        "checkout provisioning task failed: {e}"
                                                    ))),
                                                };
                                                tracing::info!(
                                                    repository_path = %repo_for_log.display(),
                                                    mode = ?mode,
                                                    lock_wait_ms = lock_wait.as_millis() as u64,
                                                    provision_ms = provision_started.elapsed().as_millis() as u64,
                                                    ok = result.is_ok(),
                                                    "workspace.create: checkout provisioning lock wait + duration"
                                                );
                                                result
                                            })
                                            .await
                                    }
                                };
                                let sha = match provision(mode).await {
                                    Ok(sha) => sha,
                                    Err(Error::Unsupported(reason))
                                        if mode == intent_core::CheckoutMode::Cow =>
                                    {
                                        // Safety net: the pre-provisioning
                                        // probe passed but the clone itself
                                        // was still unsupported. Retry as a
                                        // linked worktree instead of failing
                                        // the create; the #774 empty-dir
                                        // cleanup runs between attempts.
                                        tracing::warn!(
                                            repository_path = %repo_dir.display(),
                                            reason = %reason,
                                            "workspace.create: CoW checkout provisioning unsupported despite a passing probe; retrying as a linked worktree"
                                        );
                                        remove_workspace_dir_if_empty(&ws_dir);
                                        mode = intent_core::CheckoutMode::Worktree;
                                        match provision(mode).await {
                                            Ok(sha) => sha,
                                            Err(e) => {
                                                // `provision_worktree` creates
                                                // the branch before `git
                                                // worktree add`; on partial
                                                // failure the branch may exist
                                                // in the SOURCE repo with no
                                                // workspace row to clean it up
                                                // later. Best-effort delete it.
                                                let cleanup_repo = repo_dir.clone();
                                                let cleanup_branch = branch.clone();
                                                let cleanup = worktree_locks
                                                    .with_lock(&repo_dir, move || async move {
                                                        tokio::task::spawn_blocking(move || {
                                                            intent_git::branches::delete_local_branch(
                                                                &cleanup_repo,
                                                                &cleanup_branch,
                                                            )
                                                        })
                                                        .await
                                                    })
                                                    .await;
                                                if let Ok(Err(cleanup_err)) = cleanup {
                                                    tracing::debug!(
                                                        branch = %branch,
                                                        error = %cleanup_err,
                                                        "workspace.create: best-effort branch cleanup did not delete branch (may not have been created)"
                                                    );
                                                }
                                                remove_workspace_dir_if_empty(&ws_dir);
                                                return Err(e);
                                            }
                                        }
                                    }
                                    Err(e) => {
                                        // `provision_cow_checkout` already
                                        // removed the failed clone; also drop
                                        // the `<root>/<wsId>` parent the probe
                                        // created (CoW mode, or a worktree
                                        // fallback after a CoW request) if it
                                        // is left empty, so a failed create
                                        // leaves the workspaces root clean
                                        // (#774).
                                        if cow_isolation {
                                            remove_workspace_dir_if_empty(&ws_dir);
                                        }
                                        return Err(e);
                                    }
                                };
                                ws.worktree_path =
                                    Some(wt_path.to_string_lossy().to_string());
                                ws.checkout_mode = Some(mode);
                                if ws.base_commit_sha.is_none() {
                                    ws.base_commit_sha = Some(sha);
                                }
                            } else {
                                tracing::warn!(
                                    repository_path = %repo_dir.display(),
                                    "workspace.create: repositoryPath is not a local git repo; skipping worktree provisioning"
                                );
                            }
                        }
                    }
                    // Provisioning is done in every mode; the remaining work
                    // (row insert, spec seed, initial agent) is fast local
                    // bookkeeping — the unified scale's last milestone before
                    // the wrapper's terminal `complete 100` + done.
                    if let Some(reporter) = progress.as_deref() {
                        reporter
                            .milestone("finalizing", 95, "Finalizing workspace...")
                            .await;
                    }
                    // Mirror-at-creation (spec Diagnosis §3b): persist the
                    // global `git.autoCommit` as the workspace's own override
                    // in the same INSERT so later global changes don't
                    // retroactively flip existing workspaces — atomic, so the
                    // row can never exist without its seed.
                    store
                        .insert_workspace_with_auto_commit(&ws, Some(global_auto_commit))
                        .await?;
                    // Write the legacy `<root>/<id>/.workspace/workspace.json`
                    // file so renderer paths (FE `FileSystemWorkspaceRepository`)
                    // find their per-workspace metadata without ENOENT spam.
                    // Best-effort — a failure warns and continues.
                    if let Err(e) =
                        write_workspace_metadata_file(&workspaces_root_pathbuf, &ws)
                    {
                        tracing::warn!(
                            workspace = %ws.id.as_str(),
                            error = %e,
                            "workspace.create: failed to write .workspace/workspace.json"
                        );
                    }
                    // Record branch provenance for the delete-cleanup guard:
                    // only an auto-generated branch is ever deleted alongside
                    // the worktree (TS `removeGitWorktree` parity, where the
                    // guard is `branchName === workspaceId`). Best-effort — a
                    // failure leaves the conservative default (never delete).
                    if branch_auto_generated {
                        if let Err(e) = store
                            .set_workspace_branch_auto_generated(&ws.id, true)
                            .await
                        {
                            tracing::warn!(error = %e, "failed to record branch provenance");
                        }
                    }
                    // Register the repo in the persistent registry so it survives
                    // workspace deletion and appears in `repo.list` without a restart
                    // (TS `workspace.service` `addRepo` hook). Workspace-owned
                    // checkouts (standalone clone / cache hydration, or any path
                    // under the workspaces root — including the `ws.path`
                    // fallback) are not user repos and stay out of the registry
                    // (intent-hq/monorepo#2227). Best-effort: a registry
                    // failure must not fail workspace creation.
                    // Same two-root set as the `repo.list` sweep: the resolved
                    // create-time parent plus the boot root, so a stale
                    // checkout under the other root never registers either.
                    let mut registry_roots = vec![workspaces_root_pathbuf.clone()];
                    if !registry_roots.contains(&boot_root) {
                        registry_roots.push(boot_root.clone());
                    }
                    let repo_path = ws
                        .repository_path
                        .as_deref()
                        .filter(|p| !p.is_empty())
                        .or(ws.path.as_deref())
                        .filter(|p| !p.is_empty())
                        .filter(|p| {
                            !is_workspace_owned_checkout(
                                &ws.id,
                                p,
                                ws.worktree_path.as_deref(),
                                &registry_roots,
                            )
                        });
                    if let Some(repo_path) = repo_path {
                        let name = known_repo_name(ws.repository_name.as_deref(), repo_path);
                        if let Err(e) = store
                            .upsert_known_repo(repo_path, &name, ws.repository_owner.as_deref())
                            .await
                        {
                            tracing::warn!(error = %e, "failed to register repo in registry");
                        }
                    }
                    // Inside the idempotency scope: a replayed create returns
                    // the stored result without re-running the op, so the
                    // event fires at most once per logical create (§6.5).
                    publish_event(&bus, workspace_created_event(&ws)).await;
                    // Seed the well-known `spec` note (reference parity with
                    // `notes.service.ts ensureSpecExists`). Idempotent under
                    // the replay guard: on retry the stored result comes back
                    // and this branch never re-runs.
                    ensure_spec_note(&store, &bus, &ws.id).await?;
                    // Daemon-owned initial-agent orchestration (§5.1): when the
                    // request carries an `initialAgent`, always create the agent
                    // row (reference parity: `workspace.service.ts` persists the
                    // session whenever `initialAgent` is present — the turn only
                    // starts when a prompt exists). The agent is parentless,
                    // non-background (delegate parity: `agent_create_op`). When
                    // the prompt is non-empty it is stored as
                    // `metadata.initialMessage` and delivered exactly once — all
                    // inside the idempotency scope, so a client retry replays
                    // the stored result instead of re-sending. An empty/missing
                    // prompt persists the row without a message; the FE first
                    // send starts the turn.
                    let mut initial_agent = None;
                    if let Some(agent) = input.initial_agent {
                        let prompt = agent
                            .prompt
                            .as_deref()
                            .map(str::trim)
                            .filter(|s| !s.is_empty())
                            .map(str::to_string);
                        // Persist the prompt (when present) as
                        // `metadata.initialMessage` (delegate parity: a wake-up
                        // can resume from it) and stamp the reference-parity
                        // `isInitialAgent`/`isFirstWorkspaceAgent` flags the
                        // FE surface (`agent-backend-handler.service.ts`,
                        // `instruction-service.ts` prompt-cache `':initial'`
                        // suffix, `agent-persistence.ts`) uses to classify the
                        // workspace's coordinator. Both flags are persisted on
                        // the raw `AgentSession.metadata` JSON; the strict
                        // `AgentLite.metadata` projection surfaces
                        // `isInitialAgent` (presence-detected, `true`-only —
                        // PROTOCOL §5.5). The caller's metadata object is
                        // forwarded as-is; like agent.create, only the
                        // harvested gap fields persist today (P2-12a) —
                        // `behaviorPrompt` has no session column and the
                        // behavior derives from the persisted `specialist`.
                        let mut metadata = match agent.metadata {
                            Some(serde_json::Value::Object(m)) => m,
                            _ => serde_json::Map::new(),
                        };
                        metadata.insert("isInitialAgent".to_string(), serde_json::json!(true));
                        metadata.insert(
                            "isFirstWorkspaceAgent".to_string(),
                            serde_json::json!(true),
                        );
                        // Own the `metadata.initialMessage` invariant: when
                        // the daemon has a non-empty prompt, stamp it (delegate
                        // parity — a wake-up can resume from it); otherwise
                        // drop any caller-supplied `initialMessage` so
                        // `agent_create_op`'s metadata harvest cannot persist
                        // a stale prompt for a no-prompt workspace.
                        if let Some(ref p) = prompt {
                            metadata.insert(
                                "initialMessage".to_string(),
                                serde_json::json!(p.clone()),
                            );
                        } else {
                            metadata.remove("initialMessage");
                        }
                        // The effective session-level image blocks, mirroring
                        // the `agent_create_op` harvest (top-level param wins
                        // over the `metadata.imageBlocks` fallback). Captured
                        // here because the created `AgentLite` no longer
                        // serves `imageBlocks` (list-projection cost contract)
                        // and the first-turn threading below still needs them.
                        let image_blocks = agent
                            .image_blocks
                            .or_else(|| metadata.get("imageBlocks").cloned())
                            .filter(|v| !v.is_null());
                        let extra = intent_core::AgentCreateExtra {
                            provider: nonempty_owned(agent.provider),
                            agent_type: nonempty_owned(agent.agent_type),
                            metadata: Some(serde_json::Value::Object(metadata)),
                            context_references: agent
                                .context_references
                                .filter(|v| !v.is_null()),
                            image_blocks: image_blocks.clone(),
                            file_blocks: agent.file_blocks.filter(|v| !v.is_null()),
                            // The initial agent is the workspace's
                            // foreground agent (top-level wins over any
                            // metadata.isBackground copy).
                            is_background: Some(false),
                            ..Default::default()
                        };
                        // Harness-owned commits: same derivation as
                        // `agent.create` — the initial agent opts out of the
                        // idle subscriber when the workspace's effective
                        // auto-commit (just seeded above) is off.
                        let skip_auto_commit =
                            !services.effective_auto_commit(&ws.id).await;
                        let created = services
                            .agent_create_op(
                                ws.id.clone(),
                                nonempty_owned(agent.name),
                                nonempty_owned(agent.model),
                                nonempty_owned(agent.specialist),
                                None,
                                None,
                                skip_auto_commit,
                                extra,
                            )
                            .await?;
                        let child = AgentId::from(
                            created["agent"]["id"].as_str().unwrap_or_default(),
                        );
                        // Extract file_blocks and context_references from the created
                        // agent (STAB-69: thread them into the first turn so attachments
                        // on the initial prompt reach the ACP). Image blocks come from
                        // the harvested input above — the `AgentLite` create result no
                        // longer carries `imageBlocks`.
                        let created_image_blocks = image_blocks;
                        let created_file_blocks = created
                            .get("agent")
                            .and_then(|a| a.get("fileBlocks"))
                            .filter(|v| !v.is_null())
                            .cloned();
                        let created_context_refs = created
                            .get("agent")
                            .and_then(|a| a.get("contextReferences"))
                            .filter(|v| !v.is_null())
                            .cloned();
                        // Deliver the prompt and start the first turn when a prompt OR
                        // attachment blocks are supplied (STAB-69: image-only first
                        // messages should start a turn, consistent with
                        // agent.sendMessage semantics). The runtime `AgentManager` when
                        // attached, else the store-only persist. Best-effort like the
                        // delegate path — the agent holds `metadata.initialMessage` for
                        // resume.
                        let has_content = prompt.is_some()
                            || created_image_blocks.is_some()
                            || created_file_blocks.is_some();
                        if has_content {
                            let prompt_text = prompt.unwrap_or_default();
                            let options = crate::agent_manager::TurnOptions {
                                image_blocks: created_image_blocks.clone(),
                                file_blocks: created_file_blocks.clone(),
                                context_references: created_context_refs,
                                ..crate::agent_manager::TurnOptions::default()
                            };
                            let send = match services.agent_manager() {
                                Some(manager) => {
                                    manager
                                        .send_message(child, ws.id.clone(), prompt_text, None, options)
                                        .await
                                }
                                None => {
                                    services
                                        .agent_send_message_op(
                                            child,
                                            prompt_text,
                                            None,
                                            created_image_blocks,
                                            created_file_blocks,
                                            None,
                                        )
                                        .await
                                }
                            };
                            if let Err(e) = send {
                                tracing::warn!(
                                    workspace = %ws.id.as_str(),
                                    error = %e,
                                    "workspace.create: failed to start initial agent turn"
                                );
                            }
                        }
                        initial_agent = created.get("agent").cloned();
                    }
                    // Execute the workspace setup script (fire-and-forget): after worktree
                    // provisioning, resolve the effective setup script (explicit request
                    // param > repo config > legacy DB row) and run it in a "Setup" terminal.
                    // The explicit param is execute-only — it is never persisted (§5.1).
                    // Execution is non-blocking (tokio::spawn) and must never fail the create.
                    // Skipped when skipWorktree or no worktree was provisioned.
                    // Lives inside the idempotency closure so a cached response (same idempotencyKey)
                    // returns immediately without re-executing the script.
                    // Setup lifecycle (§6.5): `workspace:setup:started` fires iff an
                    // effective script was resolved and a spawn will be attempted;
                    // exactly one `workspace:setup:completed` fires per logical create
                    // on every terminal path of the setup stage. Idempotent replays
                    // publish nothing (same as `workspace:created`).
                    let pty_for_setup = self.pty.clone();
                    let bus_for_setup = self.event_bus.clone();
                    let setup_worktree = if ws.skip_worktree {
                        None
                    } else {
                        crate::git_ops::worktree_path(&ws)
                    };
                    if let Some(worktree_path_buf) = setup_worktree {
                        // Spawn background task to read + execute setup script (fire-and-forget).
                        // Move config IO into the task so workspace.create doesn't block on it.
                        let workspace_id = ws.id.clone();
                        let worktree_path = worktree_path_buf.to_string_lossy().to_string();
                        let repo_path = ws
                            .repository_path
                            .clone()
                            .unwrap_or_default();
                        let branch_name = ws.branch.clone();
                        let source_branch = ws
                            .base_ref
                            .clone()
                            .unwrap_or_default();
                        let legacy_script = ws.setup_script.clone();
                        let worktree_for_read = worktree_path_buf.clone();
                        tokio::spawn(async move {
                            // Resolve the effective setup script: the explicit param wins
                            // for this create; an omitted param falls back to the
                            // worktree-first repo-config read, then the legacy DB row.
                            let effective_script = match explicit_setup_script {
                                Some(explicit) => Some(explicit),
                                None => crate::repo_config::read_repo_config(&worktree_for_read)
                                    .await
                                    .setup_script
                                    .filter(|s| !s.is_empty())
                                    .or_else(|| {
                                        legacy_script.as_ref().and_then(|ss| {
                                            let script = ss.script.trim();
                                            if script.is_empty() {
                                                None
                                            } else {
                                                Some(script.to_string())
                                            }
                                        })
                                    }),
                            };
                            let script = match effective_script {
                                Some(s) => s,
                                None => {
                                    // No script to execute: the setup stage is done.
                                    publish_event(
                                        &bus_for_setup,
                                        workspace_setup_completed_event(&workspace_id, false, None),
                                    )
                                    .await;
                                    return;
                                }
                            };
                            tracing::info!(
                                workspace = %workspace_id.as_str(),
                                script_length = script.len(),
                                worktree = %worktree_path,
                                "executing setup script in background"
                            );
                            // A script was resolved and a spawn will be attempted.
                            publish_event(
                                &bus_for_setup,
                                workspace_setup_started_event(&workspace_id),
                            )
                            .await;
                            // Every terminal path below funnels into exactly one
                            // `workspace:setup:completed` publish after this block.
                            let (ran_script, exit_code): (bool, Option<u32>) = 'setup: {
                            // Write script to a private file under worktree .intent/ directory
                            // (mode 0600 on Unix, safe from other users, isolated from /tmp races).
                            let script_id = uuid::Uuid::new_v4();
                            let intent_dir = worktree_for_read.join(".intent");
                            // Security: refuse if .intent exists as a symlink (prevents writing
                            // script outside the worktree via a repo-committed symlink attack).
                            if let Ok(meta) = tokio::fs::symlink_metadata(&intent_dir).await {
                                if !meta.is_dir() {
                                    tracing::warn!(
                                        workspace = %workspace_id.as_str(),
                                        "setup script execution skipped: .intent is not a real directory (symlink or file)"
                                    );
                                    break 'setup (false, None);
                                }
                            } else {
                                // .intent doesn't exist, create it with restrictive permissions
                                if let Err(e) = tokio::fs::create_dir_all(&intent_dir).await {
                                    tracing::warn!(
                                        workspace = %workspace_id.as_str(),
                                        error = %e,
                                        "failed to create .intent directory for setup script"
                                    );
                                    break 'setup (false, None);
                                }
                                #[cfg(unix)]
                                {
                                    use std::os::unix::fs::PermissionsExt;
                                    if let Err(e) = tokio::fs::set_permissions(
                                        &intent_dir,
                                        std::fs::Permissions::from_mode(0o700),
                                    )
                                    .await
                                    {
                                        tracing::warn!(
                                            workspace = %workspace_id.as_str(),
                                            error = %e,
                                            "failed to set .intent directory permissions"
                                        );
                                    }
                                }
                            }
                            // Select the platform runner: POSIX always spawns
                            // absolute /bin/sh + the inline timing wrapper
                            // (byte-identical to the historic spawn); Windows
                            // prefers a discovered Git-for-Windows sh.exe
                            // running the same wrapper (so bash setup scripts
                            // keep working), else falls back to a cmd.exe
                            // `.cmd` wrapper with the same summary format.
                            let runner = setup_runner::select(
                                cfg!(windows),
                                if cfg!(windows) {
                                    setup_runner::find_windows_sh()
                                } else {
                                    None
                                },
                            );
                            let script_path = intent_dir.join(format!(
                                "setup-{}.{}",
                                script_id.simple(),
                                runner.script_extension()
                            ));
                            if let Err(e) = write_private_script(&script_path, &script).await {
                                tracing::warn!(
                                    workspace = %workspace_id.as_str(),
                                    error = %e,
                                    "failed to write setup script to private file"
                                );
                                break 'setup (false, None);
                            }
                            // cmd.exe fallback only: the timing wrapper is a
                            // sibling .cmd file rather than an inline `-c`
                            // string (cmd has no equivalent of `sh -c`).
                            let wrapper_path = if runner.needs_cmd_wrapper_file() {
                                let p = intent_dir
                                    .join(format!("setup-wrapper-{}.cmd", script_id.simple()));
                                if let Err(e) =
                                    write_private_script(&p, setup_runner::SETUP_SCRIPT_WRAPPER_CMD)
                                        .await
                                {
                                    tracing::warn!(
                                        workspace = %workspace_id.as_str(),
                                        error = %e,
                                        "failed to write setup script cmd wrapper"
                                    );
                                    let _ = tokio::fs::remove_file(&script_path).await;
                                    break 'setup (false, None);
                                }
                                Some(p)
                            } else {
                                None
                            };
                            // Spawn through the timing wrapper so the scrollback
                            // ends with a completion summary and the script's
                            // exit code is preserved. `extra_env` carries the
                            // cmd.exe fallback's script path (see
                            // `SetupScriptRunner::command`); empty otherwise.
                            let (program, args, extra_env) =
                                runner.command(&script_path, wrapper_path.as_deref());
                            let mut spec =
                                intent_pty::SpawnSpec::new(workspace_id.as_str(), program);
                            spec.args = args;
                            spec.size = intent_pty::PtySize { rows: 24, cols: 80 };
                            spec.name = Some(SETUP_TERMINAL_NAME.to_string());
                            spec.cwd = Some(worktree_for_read.clone());
                            spec.env = vec![
                                ("MAIN_CHECKOUT".to_string(), repo_path),
                                ("WORKTREE_PATH".to_string(), worktree_path.clone()),
                                ("BRANCH_NAME".to_string(), branch_name),
                                ("SOURCE_BRANCH".to_string(), source_branch),
                            ];
                            spec.env.extend(extra_env);
                            match pty_for_setup.spawn(spec) {
                                Ok(pty_id) => {
                                    let terminal_id = pty_id.to_string();
                                    tracing::info!(
                                        workspace = %workspace_id.as_str(),
                                        terminal_id = %terminal_id,
                                        "setup script terminal spawned"
                                    );
                                    // Spawn output stream to fan setup script output to event bus
                                    crate::terminal_ops::spawn_output_stream(
                                        pty_for_setup.clone(),
                                        bus_for_setup.clone(),
                                        workspace_id.clone(),
                                        pty_id,
                                        terminal_id,
                                    );
                                    // Wait for the script to actually complete before cleanup
                                    let exit = pty_for_setup.wait(pty_id).await;
                                    // Best-effort cleanup of the script + wrapper files (after exit)
                                    let _ = tokio::fs::remove_file(&script_path).await;
                                    if let Some(w) = &wrapper_path {
                                        let _ = tokio::fs::remove_file(w).await;
                                    }
                                    (true, exit.ok().map(|e| e.exit_code))
                                }
                                Err(e) => {
                                    tracing::warn!(
                                        workspace = %workspace_id.as_str(),
                                        error = %e,
                                        "failed to spawn setup script terminal"
                                    );
                                    // Cleanup on spawn failure
                                    let _ = tokio::fs::remove_file(&script_path).await;
                                    if let Some(w) = &wrapper_path {
                                        let _ = tokio::fs::remove_file(w).await;
                                    }
                                    (false, None)
                                }
                            }
                            };
                            publish_event(
                                &bus_for_setup,
                                workspace_setup_completed_event(
                                    &workspace_id,
                                    ran_script,
                                    exit_code,
                                ),
                            )
                            .await;
                        });
                    } else {
                        // skipWorktree / no worktree provisioned: the setup stage
                        // never runs, but the lifecycle still completes.
                        publish_event(
                            &bus_for_setup,
                            workspace_setup_completed_event(&ws.id, false, None),
                        )
                        .await;
                    }
                    Ok(WorkspaceCreateResult {
                        workspace: ws,
                        initial_agent,
                    })
                },
            )
            .await;

            // Terminal frame ownership (PROTOCOL §5.1): when the create armed
            // a progress reporter, exactly one `git:clone:done` is emitted
            // here — `ok:true` after any successful create, `ok:false`
            // carrying the sanitized detail (+ machine-readable category for
            // classified clone failures) on any error, in every checkout
            // mode. The slot stays empty on idempotent replays (the closure
            // never runs; nothing is emitted — the cached success result is
            // the answer) and on `progressId`-less requests. A FAILURE that
            // never armed the slot (idempotency-store read/decode error, or
            // an early config error such as an invalid
            // `workspace.worktreesLocation`) synthesizes a sentinel-scoped
            // reporter so a `progressId` create's error path always closes
            // the stream with its `ok:false` done.
            let mut reporter = progress_slot.lock().unwrap().take();
            if reporter.is_none() && result.is_err() {
                if let (Some(pid), Some(b)) = (&wrapper_progress_id, &wrapper_bus) {
                    reporter = Some(std::sync::Arc::new(create_progress::CreateProgress::new(
                        b.clone(),
                        WorkspaceId::from_string(String::new()),
                        pid.clone(),
                    )));
                }
            }
            if let Some(reporter) = reporter {
                match &result {
                    Ok(_) => reporter.done_ok().await,
                    Err(Error::CloneFailed { category, detail }) => {
                        let error_code = (*category != intent_core::CloneErrorCategory::Other)
                            .then_some(*category);
                        reporter.done_err(detail, error_code).await;
                    }
                    Err(e) => {
                        reporter
                            .done_err(&clone_ops::redact_credentials(&e.to_string()), None)
                            .await;
                    }
                }
            }

            // Log workspace.create failures at WARN so they are diagnosable
            // (STAB-68: iOS saw -32603 with no daemon-side log evidence).
            if let Err(ref e) = result {
                tracing::warn!(
                    method = "workspace.create",
                    error = %e,
                    repository_path = ?log_repo_path,
                    branch = ?log_branch,
                    "workspace.create failed"
                );
            }
            result
        })
    }

    fn update_workspace(
        &self,
        id: WorkspaceId,
        update: WorkspaceUpdate,
    ) -> BoxFuture<'_, Result<Workspace>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let this = self.clone();
        // Normalise write-time-canonicalised fields on the delta snapshot so
        // `workspace:updated { changes }` (§6.5) matches the returned/persisted
        // `Workspace`: raw `baseRef: "origin/main"` collapses to canonical
        // `"main"`, and whitespace-only `statusMessage` folds to `""` (the
        // clear-signal wire value, preserved through `skip_serializing_if` so
        // subscribers can distinguish "clear" from "no change"). Lets
        // subscribers mirror the delta without a follow-up read.
        let mut normalised = update.clone();
        if let Some(raw) = normalised.base_ref.as_deref() {
            normalised.base_ref = Some(canonicalise_base_ref(raw));
        }
        if let Some(raw) = normalised.status_message.as_deref() {
            if raw.trim().is_empty() {
                normalised.status_message = Some(String::new());
            }
        }
        // A whitespace/empty `statusImageAssetId` persists as a clear (the
        // apply path below folds it to `None`), so the delta must carry the
        // `null` clear signal — not the raw whitespace — for §6.5 mirroring.
        if let Some(Some(raw)) = normalised.status_image_asset_id.as_ref() {
            if raw.trim().is_empty() {
                normalised.status_image_asset_id = Some(None);
            }
        }
        let changes = serde_json::to_value(&normalised).unwrap_or(serde_json::Value::Null);
        Box::pin(async move {
            // Captured before the `if let` arms below move the fields out.
            let pr_fields_changed = update.pr_number.is_some()
                || update.pr_url.is_some()
                || update.pr_status.is_some()
                || update.active_pull_request.is_some()
                || update.pull_requests.is_some();
            let attention_changed = update.attention.is_some();
            let mut ws = if id.is_chief() {
                chief_workspace()
            } else {
                store.get_workspace(&id).await?
            };
            if let Some(v) = update.title {
                ws.title = v;
            }
            if let Some(v) = update.status_message {
                // Reference `setStatusMessage` contract (§5 / ws-misc-api.ts): empty
                // or whitespace-only strings clear the message. Normalize on write so
                // `ws.workspace.details()` and every downstream reader see `None`
                // instead of `Some("")` for a cleared value.
                ws.status_message = if v.trim().is_empty() { None } else { Some(v) };
            }
            // Clearable status-screenshot asset id (intent-hq/monorepo#997):
            // wire `null` (`Some(None)`) clears, `Some(Some(id))` sets,
            // missing leaves untouched — same double-option contract as the
            // PR fields below.
            if let Some(v) = update.status_image_asset_id {
                ws.status_image_asset_id = v.filter(|s| !s.trim().is_empty());
            }
            if let Some(v) = update.branch {
                ws.branch = v;
            }
            if let Some(v) = update.base_ref {
                // Canonicalise the wire `baseRef` on write so the persisted
                // value stays the plain branch name (§7.6, matches create).
                ws.base_ref = Some(canonicalise_base_ref(&v));
            }
            if let Some(v) = update.base_commit_sha {
                ws.base_commit_sha = Some(v);
            }
            if let Some(v) = update.status {
                ws.status = v;
            }
            if let Some(v) = update.tags {
                ws.tags = v;
            }
            if let Some(v) = update.path {
                ws.path = Some(v);
            }
            if let Some(v) = update.repository_path {
                ws.repository_path = Some(v);
            }
            if let Some(v) = update.repository_owner {
                ws.repository_owner = Some(v);
            }
            if let Some(v) = update.repository_name {
                ws.repository_name = Some(v);
            }
            if let Some(v) = update.worktree_path {
                ws.worktree_path = Some(v);
            }
            if let Some(v) = update.scope {
                ws.scope = Some(v);
            }
            if let Some(v) = update.skip_isolation {
                ws.skip_worktree = v;
            }
            if let Some(v) = update.setup_script {
                ws.setup_script = Some(setup_scripts::user_script(v));
            }
            if let Some(v) = update.is_remote {
                ws.is_remote = v;
            }
            if let Some(v) = update.default_model {
                ws.default_model = Some(v);
            }
            // Clearable PR fields (§5.1): `Some(None)` deserialized from a
            // wire `null` clears the stored value; `Some(Some(v))` sets it;
            // bare `None` leaves it untouched (missing on the wire).
            if let Some(v) = update.pr_number {
                ws.pr_number = v;
            }
            if let Some(v) = update.pr_url {
                ws.pr_url = v;
            }
            if let Some(v) = update.pr_status {
                ws.pr_status = v;
            }
            if let Some(v) = update.active_pull_request {
                ws.active_pull_request = v;
            }
            if let Some(v) = update.pull_requests {
                ws.pull_requests = v;
            }
            if let Some(v) = update.last_activity {
                ws.last_activity = Some(v);
            }
            if let Some(v) = update.attention {
                ws.attention = v;
            }
            if let Some(v) = update.archived {
                ws.archived = v;
            }
            ws.updated_at = now_iso();
            // Chief is virtual: the seeded row is never mutated (TS
            // `saveWorkspaceUpdates` parity — return the applied delta layered
            // over the synthesized shape without persisting). Still emit
            // `workspace:updated` so subscribers see the delta.
            if ws.id.is_chief() {
                // Chief's canonical shape pins createdAt/updatedAt/lastActivity
                // (`CHIEF_WORKSPACE_TIMESTAMP` in `chief_workspace()`). Restore
                // the invariants so the update response matches the shape
                // `workspace.get` returns — a caller-supplied `lastActivity` or
                // the auto-touched `updatedAt` above must not leak through and
                // diverge Chief's timestamps from `chief_workspace()`.
                let pinned = chief_workspace();
                ws.created_at = pinned.created_at;
                ws.updated_at = pinned.updated_at;
                ws.last_activity = pinned.last_activity;
                // Derive `activity` from live agent state (§9.9) so the mutation
                // response carries `agent_running` when agents are in-flight,
                // not the stale default `idle` from the synthesized row.
                ws.activity = this.workspace_activity(&ws.id);
            } else {
                store.update_workspace(&ws).await?;
                // Derive `lastActivity` (§9.1) on the returned record so
                // `workspace.update` callers get the authoritative wire shape
                // without a follow-up `workspace.get`, and persist it through
                // the scoped monotonic write (monorepo#1585). Chief is
                // skipped: its timestamps are pinned above.
                this.derive_and_persist_last_activity(&mut ws, "workspace.update")
                    .await;
                // Derive `activity` from live agent state (§9.9) so the mutation
                // response carries `agent_running` when agents are in-flight,
                // not the stale default `idle` from the persisted row.
                ws.activity = this.workspace_activity(&ws.id);
            }
            // Self-sufficient `workspace:updated` payload (§6.5) so every
            // client mirrors the delta without a follow-up read.
            publish_event(&bus, workspace_updated_event(&ws.id, changes)).await;
            // PR link/status changes feed the derived displayStatus (the
            // `pr_*` rungs sit between activity and taskStats), and so does
            // the attention flag (`unread` / `review_required` axes):
            // recompute-and-compare after the persist so the transition
            // emits (§6.5). Chief is skipped — virtual, never listed,
            // nothing derives.
            if !ws.id.is_chief() && (pr_fields_changed || attention_changed) {
                this.maybe_emit_display_status_changed(&ws.id).await;
            }
            Ok(ws)
        })
    }

    fn delete_workspace(&self, id: WorkspaceId) -> BoxFuture<'_, Result<()>> {
        let store = self.store.clone();
        let worktree_locks = self.worktree_locks.clone();
        let bus = self.event_bus.clone();
        let workspaces_root = self
            .workspaces_root
            .clone()
            .unwrap_or_else(default_workspaces_root);
        // Custom `workspace.worktreesLocation` sweep target: the workspace's
        // actual parent is derived from its persisted worktree path below,
        // but worktree-less rows created under a custom location need the
        // currently configured location as a candidate too.
        let worktrees_location = self.configured_worktrees_location();
        // Live-state teardown handles: cloned so the boxed future owns them
        // across the store cascade below. `agent_manager()` upgrades the weak
        // reference; read-only/test wiring with no manager attached simply
        // skips the runtime stop and still sweeps the in-memory registries.
        let manager = self.agent_manager();
        let agent_queues = self.agent_queues.clone();
        let live_turns = self.live_turns.clone();
        let last_turn_silent_tails = self.last_turn_silent_tails.clone();
        let truncation_redrives = self.truncation_redrives.clone();
        let pending_truncation_redrive = self.pending_truncation_redrive.clone();
        let agent_subscriptions = self.agent_subscriptions.clone();
        // Full handle for the direct completion delivery below (Services is
        // Clone — the same capture pattern the spawn helpers use).
        let services = self.clone();
        Box::pin(async move {
            // Chief is virtual and never appears in `workspace.list`; delete is
            // a no-op success (TS `workspace.repository.delete` / virtual-guard
            // parity — the seeded row is not torn down and no cascade fires).
            if id.is_chief() {
                return Ok(());
            }
            // Immediate-delete-while-pending (§5.1): an immediate delete
            // supersedes a running grace window — drop the pending entry and
            // abort its timer, then commit now. The timer-fired commit path
            // has already claimed (removed) its entry before calling here,
            // so this is a no-op for it.
            services.pending_workspace_deletes.cancel(id.as_str());
            // Terminate live agent sessions BEFORE the store cascade drops
            // their rows. A same-slug recreate hitting `agent.list` after the
            // delete would otherwise surface ghost sessions whose workers are
            // still draining, their live-turn slots + pending message queues
            // still populated, and their completion watches still firing. The
            // order mirrors `agent_delete_op`: capture the workspace-scoped
            // sessions, drop each session's runtime state, then emit
            // `agent:deleted` per session so subscribers see the tear-down
            // before the terminal `workspace:deleted`.
            // Fail fast on a transient `list_agent_sessions` error: skipping
            // the sweep here but still deleting the workspace row leaves ghost
            // workers, live-turn slots, queued messages, and completion
            // watches with no owning workspace — a client can retry the
            // delete, but silent partial success cannot recover.
            let sessions = store.list_agent_sessions(&id).await?;
            // Cascade interaction (§5.5): the workspace delete — immediate
            // or committed-from-pending — supersedes any pending agent
            // deletions inside it. Abort their timers without per-agent
            // cancel events; each session is deleted just below, emitting
            // `agent:deleted` per session.
            services.abort_pending_agent_deletes(&sessions);
            // Batch stop: aborts each worker, drops each handle, clears
            // busy + agent_ws, and deregisters each process — the
            // `agent.stop` semantics per agent — then kills all detached
            // ACP children's process groups under ONE shared grace
            // window (`kill_child_trees`), so the delete ack pays ~one
            // grace period total instead of one per live agent.
            // The returned fence keeps the swept agents blocked from the
            // lazy-spawn paths until this future completes (it drops at the
            // end of this scope, after the store cascade below deletes the
            // session rows): a concurrent `agent.sendMessage` that passed
            // its store check before the sweep would otherwise respawn a
            // replacement child during the shared grace wait and leave it
            // running as a ghost process after the rows are gone.
            let _teardown_fence = match manager.as_ref() {
                Some(manager) => {
                    let ids: Vec<AgentId> = sessions.iter().map(|s| s.id.clone()).collect();
                    Some(manager.stop_many(&ids).await)
                }
                None => None,
            };
            for session in &sessions {
                // Live-turn slot + pending message queue live in `Services`'
                // maps (not touched by `manager.stop_many`); drop them so a
                // same-slug recreate observes no ghost state. Recover through
                // a poisoned lock via `into_inner` — the delete path is the
                // last chance to unlink this state, so best-effort teardown
                // outweighs propagating a mutex-poison panic.
                live_turns
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&session.id);
                last_turn_silent_tails
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&session.id);
                truncation_redrives
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&session.id);
                pending_truncation_redrive
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&session.id);
                agent_queues
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .remove(&session.id);
            }
            // Sweep the deleted workspace out of the daemon-global
            // subscription registry: drop watches whose PARENT lives here
            // (their wake destination is gone) and groups anchored here.
            // Watches whose parent lives elsewhere (a chief watching a child
            // in this workspace) are kept — the `agent:deleted` events
            // published just below still wake the cross-workspace parent.
            // Poison recovery mirrors the per-session sweep above.
            {
                let mut registry = agent_subscriptions
                    .lock()
                    .unwrap_or_else(|e| e.into_inner());
                registry
                    .subscriptions
                    .retain(|s| s.parent_workspace_id != id);
                registry.delegation_groups.retain(|g| g.workspace_id != id);
            }
            // Emit `agent:deleted` per swept session before the worktree /
            // store cleanup so subscribers see the terminal event for each
            // agent ahead of `workspace:deleted`. Best-effort: emits when the
            // bus is wired; a `None` bus (read-only wiring) is a quiet no-op.
            for session in &sessions {
                publish_event(
                    &bus,
                    NewEvent {
                        workspace_id: id.clone(),
                        timestamp: now_iso(),
                        event_type: AGENT_DELETED.to_string(),
                        actor: system_actor(),
                        session_id: Some(session.id.0.clone()),
                        correlation_id: None,
                        parent_event_id: None,
                        metadata: None,
                        data: serde_json::json!({
                            "agentId": session.id.0,
                            "agentName": session.name,
                        }),
                    },
                )
                .await;
            }
            // Deterministic cross-workspace consumption (monorepo#463): the
            // publishes above are best-effort (`None` bus, logged-and-skipped
            // delivery failures), so a chief parent's watch on a child here
            // could otherwise leak forever (watches have no timed cleanup)
            // and a chief-anchored after_all group would stay
            // incomplete until restart. Deliver the same synthetic
            // `agent:deleted` directly, BEFORE the store cascade drops the
            // session rows (grouped delivery still resolves the child's
            // completion report). The remove-before-deliver guard in
            // `deliver_completion_to_watches` makes the bus loop's later
            // processing of the published event a no-op — no duplicate wake —
            // and `record_group_child_completion` is idempotent.
            for session in &sessions {
                let event = Event {
                    id: uuid::Uuid::new_v4().to_string(),
                    workspace_id: id.clone(),
                    timestamp: now_iso(),
                    event_type: AGENT_DELETED.to_string(),
                    actor: system_actor(),
                    session_id: Some(session.id.0.clone()),
                    correlation_id: None,
                    parent_event_id: None,
                    metadata: None,
                    data: serde_json::json!({
                        "agentId": session.id.0,
                        "agentName": session.name,
                    }),
                };
                services
                    .deliver_completion_to_watches(&session.id, &event)
                    .await;
            }
            // Backstop sweep: grouped watches survive delivery (group
            // settlement owns their lifecycle) and a racing registration can
            // land behind the loop above — after this point no watch may
            // reference the deleted workspace as its child side. In-memory
            // retain + best-effort delete of the persisted rows. Each
            // affected parent then gets a refreshed
            // `agent:subscriptions-changed` so clients converge on the
            // shrunken watch set without polling (PROTOCOL §6.5).
            let leaked: Vec<(String, WorkspaceId, AgentId)> = {
                let mut registry = agent_subscriptions
                    .lock()
                    .unwrap_or_else(|e| e.into_inner());
                let mut leaked = Vec::new();
                registry.subscriptions.retain(|s| {
                    if s.child_workspace_id == id {
                        leaked.push((
                            s.id.clone(),
                            s.parent_workspace_id.clone(),
                            s.parent_agent_id.clone(),
                        ));
                        false
                    } else {
                        true
                    }
                });
                leaked
            };
            for (watch_id, _, _) in &leaked {
                if let Err(e) = store.delete_completion_watch(watch_id).await {
                    tracing::warn!("completion_watch delete failed {watch_id}: {e}");
                }
            }
            let mut notified: Vec<(&WorkspaceId, &AgentId)> = Vec::new();
            for (_, parent_ws, parent_id) in &leaked {
                if !notified.contains(&(parent_ws, parent_id)) {
                    notified.push((parent_ws, parent_id));
                    services
                        .publish_subscriptions_changed(parent_ws, parent_id)
                        .await;
                }
            }
            // Drop the workspace's event subscriptions (monorepo#947): their
            // filter is workspace-scoped, so once the workspace is gone they
            // can never match again — without this sweep their delivery
            // tasks and persisted rows leak and rehydrate forever. Aborts
            // the tasks and deletes the rows (chief-anchored subscriptions
            // scoped to OTHER workspaces are untouched — this removes only
            // subscriptions whose events came from the deleted workspace).
            // Residual race: an `agent.subscribe` landing between this sweep
            // and the store cascade below can still register (the agent row
            // is not yet gone) — its task idles harmlessly (the workspace
            // emits no further events) and the row is pruned by the next
            // startup heal's workspace-existence check.
            services.remove_event_subscriptions_for_workspace(&id).await;
            // Eagerly abort the workspace's live hook scheduler tasks BEFORE
            // the store cascade drops their rows — otherwise each task would
            // linger until its next tick before noticing the row is gone.
            services.abort_workspace_hook_tasks(&id).await;
            // Capture workspace state for the async cleanup below (before the
            // row delete). Best-effort: when the workspace is already gone or
            // the read fails, the background task simply skips the worktree
            // step — the orphaned directory sweep can still unlink
            // `<workspaces_root>/<id>/` on a retry, per the idempotent delete.
            let ws_for_cleanup = store.get_workspace(&id).await.ok();
            let branch_auto_generated = store
                .workspace_branch_auto_generated(&id)
                .await
                .unwrap_or(false);
            // Idempotent DB delete: swallow `NotFound` so retries and
            // orphan-dir-only cleanups don't surface as `"Failed to delete
            // space"` on the FE. Any other error still propagates. Publish
            // `workspace:deleted` only when we actually removed a row —
            // subscribers dedup by id but a spurious event confuses UIs
            // that treat it as a state transition.
            match store.delete_workspace(&id).await {
                Ok(()) => {
                    publish_event(&bus, workspace_deleted_event(&id)).await;
                }
                Err(Error::NotFound(_)) => {
                    tracing::debug!(
                        workspace = %id.as_str(),
                        "workspace.delete: row already gone; treating as idempotent success"
                    );
                }
                Err(e) => return Err(e),
            }
            // Evict the deleted workspace's last-observed displayStatus
            // baseline so the in-memory map does not leak for the daemon's
            // lifetime (and a same-id recreate seeds fresh).
            services.evict_display_status_baseline(&id);
            // Same for the cached git status: a dirty repo's `files` vec is
            // unbounded, so the deleted worktree's last scan must not be
            // retained for the daemon's lifetime (monorepo#1648).
            if let Some(worktree) = ws_for_cleanup.as_ref().and_then(git_ops::worktree_path) {
                services.git_status_cache.evict(&worktree);
            }
            // Fast-ack: the client receives `{ success: true }` here while the
            // worktree and workspace-directory cleanup proceeds asynchronously
            // in the background. Bounded latency regardless of checkout size
            // (no multi-GB `remove_dir_all` blocking the response).
            //
            // Same-slug-recreate race guard: the `create` path already takes
            // the per-repo worktree lock before provisioning, so a recreate
            // cannot run its `add_worktree` while this cleanup's locked phase
            // (registration prune + rename to a trash path) is still in
            // progress for the same repo.
            // Residual risk: if a recreate runs *before* the background task
            // fires (row is deleted, event is sent, response is ACKed, but the
            // spawn hasn't yet grabbed the worktree lock), the recreate could
            // complete and then this cleanup might delete its brand-new
            // worktree. Mitigation: we re-check the workspace row inside the
            // background task and skip cleanup if it exists again. This is
            // best-effort; the cleanup is naturally idempotent, and
            // `workspace.delete` of the recreated workspace will clean up any
            // mismatched leftovers.
            let workspaces_root_bg = workspaces_root.clone();
            let worktrees_location_bg = worktrees_location.clone();
            let id_bg = id.clone();
            let store_bg = store.clone();
            let worktree_locks_bg = worktree_locks.clone();
            let branch_auto_generated_bg = branch_auto_generated;
            tokio::spawn(async move {
                // Re-check that the workspace is actually deleted. If it
                // exists now (same-slug recreate landed before this task ran),
                // skip the worktree cleanup entirely — the new workspace owns
                // the branch and directory now. Still sweep the
                // `<workspaces_root>/<id>/` directory if it doesn't match the
                // recreated workspace's path, for orphan-cleanup parity.
                let recreated = store_bg.get_workspace(&id_bg).await.ok();
                let deleted_worktree_path = ws_for_cleanup
                    .as_ref()
                    .and_then(|w| w.worktree_path.clone());
                // Root-anchored ownership: the persisted checkout counts as
                // daemon-provisioned only when its parent directory is named
                // after the workspace id AND it lives under a root the daemon
                // provisions into (the boot workspaces root or the currently
                // configured `workspace.worktreesLocation`). The parent
                // basename alone is spoofable — the workspace id derives from
                // the initial prompt, so an `isNewRepo` caller could place
                // their repository at `<anywhere>/<wsId>/<repo>` and a
                // basename-only gate would route the user's folder into the
                // delete paths below. Trade-off: a checkout provisioned under
                // a since-changed custom location is no longer matched and its
                // `<oldLocation>/<wsId>/` directory leaks instead of being
                // swept — leaking is the safe direction (never delete what we
                // cannot prove we created).
                let checkout_owned = deleted_worktree_path.as_deref().is_some_and(|wt| {
                    checkout_parent_is_workspace_dir(wt, &id_bg)
                        && (Path::new(wt).starts_with(&workspaces_root_bg)
                            || worktrees_location_bg
                                .as_deref()
                                .is_some_and(|loc| Path::new(wt).starts_with(loc)))
                });
                // A standalone row's checkout path is caller-influenced
                // (`repository_path == worktree_path`), so unless ownership is
                // proven above it must not seed the final
                // `workspace_dir_candidates` sweep either — that sweep
                // recursively removes the checkout's parent directory.
                // Worktree-mode rows keep their persisted path: the daemon
                // derived it at provision time (covers a since-changed custom
                // location).
                let is_standalone_row = ws_for_cleanup.as_ref().is_some_and(|w| {
                    matches!(
                        w.checkout_mode,
                        Some(intent_core::CheckoutMode::Cow)
                            | Some(intent_core::CheckoutMode::Direct)
                    )
                });
                let sweep_worktree_path = deleted_worktree_path
                    .as_deref()
                    .filter(|_| !is_standalone_row || checkout_owned);
                if let Some(ws_cleanup) = ws_for_cleanup {
                    // Only run the worktree cleanup if the workspace is still
                    // deleted (no recreate) or the recreate has a different
                    // worktree path (the old worktree is now orphaned).
                    let skip_worktree = recreated
                        .as_ref()
                        .map(|r| r.worktree_path == ws_cleanup.worktree_path)
                        .unwrap_or(false);
                    if !skip_worktree {
                        let repo_dir = ws_cleanup
                            .repository_path
                            .as_deref()
                            .filter(|p| !p.is_empty())
                            .map(PathBuf::from);
                        let wt = ws_cleanup
                            .worktree_path
                            .as_deref()
                            .filter(|p| !p.is_empty())
                            .map(PathBuf::from);
                        if let (Some(repo_dir), Some(wt)) = (repo_dir, wt) {
                            if !ws_cleanup.skip_worktree && !ws_cleanup.is_remote {
                                let branch = ws_cleanup.branch.clone();
                                let repo = repo_dir.clone();
                                let branch_flag = branch_auto_generated_bg;
                                let wt_locked = wt.clone();
                                // A CoW or direct checkout is a standalone
                                // clone: no registration to prune in the
                                // source repo, and its workspace branch lives
                                // only inside the clone — so the source-repo
                                // branch-delete guard must not run (a
                                // same-named source branch was never this
                                // workspace's).
                                let is_standalone = matches!(
                                    ws_cleanup.checkout_mode,
                                    Some(intent_core::CheckoutMode::Cow)
                                        | Some(intent_core::CheckoutMode::Direct)
                                );
                                // Standalone-checkout removal is gated on the
                                // root-anchored `checkout_owned` proof above
                                // (`<root>/<wsId>/<slug>` under a daemon
                                // root). An `isNewRepo` direct row's checkout
                                // IS the user's repository folder
                                // (`worktree_path == repository_path`,
                                // intent-hq/monorepo#2611): never provisioned
                                // by the daemon, never deleted with the
                                // workspace.
                                if is_standalone && !checkout_owned {
                                    tracing::debug!(
                                        workspace = %ws_cleanup.id.as_str(),
                                        checkout = %wt_locked.display(),
                                        "workspace.delete: standalone checkout is the user's repository folder; keeping it"
                                    );
                                } else {
                                    // Under the per-repo lock: git-metadata work
                                    // only (registration prune, rename of the
                                    // checkout to a trash path, branch-delete
                                    // guard; for CoW just the rename + metadata
                                    // dir removal). On the rename-success path
                                    // the multi-GB recursive removal runs below,
                                    // after the lock is released, so concurrent
                                    // `workspace.create` provisioning on the same
                                    // repo is not starved by bulk deletes; only
                                    // the rare rename-failure fallback removes
                                    // in place under the lock.
                                    let trash = worktree_locks_bg
                                        .with_lock(&repo_dir, move || async move {
                                            let task = tokio::task::spawn_blocking(move || {
                                                if is_standalone {
                                                    cleanup_workspace_cow_checkout_locked(
                                                        &wt_locked,
                                                    )
                                                } else {
                                                    cleanup_workspace_worktree_locked(
                                                        &repo,
                                                        &wt_locked,
                                                        &branch,
                                                        branch_flag,
                                                    )
                                                }
                                            })
                                            .await;
                                            match task {
                                                Ok(trash) => trash,
                                                Err(e) => {
                                                    tracing::warn!(
                                                        error = %e,
                                                        "background worktree cleanup task failed"
                                                    );
                                                    None
                                                }
                                            }
                                        })
                                        .await;
                                    if let Some(trash) = trash {
                                        let removal = tokio::task::spawn_blocking(move || {
                                            cleanup_detached_worktree(&trash)
                                        })
                                        .await;
                                        if let Err(e) = removal {
                                            tracing::warn!(
                                                error = %e,
                                                "background detached-worktree removal task failed"
                                            );
                                        }
                                        // Retry the empty-only parent `remove_dir`
                                        // the trash sibling blocked — back under
                                        // the per-repo lock, so it can't race a
                                        // same-slug recreate's freshly created
                                        // parent between its `create_dir_all` and
                                        // `git worktree add`. O(1) while held.
                                        if let Some(parent) = wt.parent().map(Path::to_path_buf) {
                                            worktree_locks_bg
                                                .with_lock(&repo_dir, move || async move {
                                                    let _ = std::fs::remove_dir(&parent);
                                                })
                                                .await;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                // Final sweep of the daemon-owned workspace directory
                // (`<parent>/<id>/`). The worktree cleanup's best-effort
                // `remove_dir` (empty-only) leaves any residual content
                // behind, and legacy pre-daemon workspaces have a directory
                // but no worktree path at all. Recursive best-effort removal
                // keeps the FE `FileSystemWorkspaceRepository.findAll` scan
                // from re-surfacing the deleted id (ENOENT WARN spam) and
                // makes the delete idempotent for orphaned directories.
                //
                // Candidates cover every parent this workspace may live under
                // (persisted worktree's parent — the location in force at
                // create time — plus the boot root and the currently
                // configured `workspace.worktreesLocation`), so deleting a
                // workspace created under a custom location does not leak
                // `<location>/<id>/`.
                //
                // If a same-slug recreate happened and uses the same
                // `<parent>/<id>/` directory, skip that candidate so we don't
                // destroy the recreated workspace's directory tree.
                let recreated_parent = recreated
                    .as_ref()
                    .and_then(|r| r.worktree_path.as_deref())
                    .filter(|p| !p.is_empty())
                    .and_then(|wt_path| Path::new(wt_path).parent())
                    .map(Path::to_path_buf);
                for dir in workspace_dir_candidates(
                    &id_bg,
                    sweep_worktree_path,
                    &workspaces_root_bg,
                    worktrees_location_bg.as_deref(),
                ) {
                    if recreated_parent.as_deref() == Some(dir.as_path()) {
                        continue;
                    }
                    // Shared parallel removal helper; `NotFound` is already
                    // folded into `Ok` there.
                    let cleanup = tokio::task::spawn_blocking(move || {
                        intent_git::fs_remove::remove_dir_all_parallel(&dir)
                    })
                    .await;
                    match cleanup {
                        Ok(Ok(())) => {}
                        Ok(Err(e)) => tracing::warn!(
                            workspace = %id_bg.as_str(),
                            error = %e,
                            "background cleanup: failed to remove workspace directory"
                        ),
                        Err(join_err) => tracing::warn!(
                            workspace = %id_bg.as_str(),
                            error = %join_err,
                            "background cleanup: workspace-dir task failed"
                        ),
                    }
                }
            });
            Ok(())
        })
    }

    fn schedule_workspace_delete(
        &self,
        id: WorkspaceId,
        undo_delay_ms: u64,
    ) -> BoxFuture<'_, Result<String>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            // Chief is virtual: mirror the immediate-delete no-op guard —
            // report a deadline but never arm a timer (the commit would be a
            // no-op anyway, and a pending marker on Chief makes no sense).
            if id.is_chief() {
                return Ok(intent_core::iso_ms_from_now(
                    delete_grace::clamp_undo_delay_ms(undo_delay_ms),
                ));
            }
            // Validate existence up front so scheduling a delete for an
            // unknown workspace is the standard `NotFound` error, not a
            // timer that fails later.
            store.get_workspace(&id).await?;
            let delay_ms = delete_grace::clamp_undo_delay_ms(undo_delay_ms);
            let delete_at = intent_core::iso_ms_from_now(delay_ms);
            let key = id.as_str().to_string();
            let timer_services = services.clone();
            let timer_id = id.clone();
            // Idempotent re-schedule (§5.1): the registry arms the timer only
            // when nothing is pending for this key — the check runs under the
            // registry lock, so concurrent schedules converge on one deadline
            // and only the arming call emits `workspace:delete-scheduled`.
            if let Some(existing) = services.pending_workspace_deletes.schedule(
                key,
                delete_at.clone(),
                move |generation| {
                    tokio::spawn(async move {
                        tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
                        // Claim-or-abstain: only the timer that still owns the
                        // entry commits. A cancel or an immediate delete that
                        // raced ahead removed/superseded the entry — do nothing.
                        if !timer_services
                            .pending_workspace_deletes
                            .claim(timer_id.as_str(), generation)
                        {
                            return;
                        }
                        // Commit via the existing immediate-delete cascade
                        // (same events, fast-ack cleanup). Best-effort: the
                        // caller is long gone, so a failure is logged, not
                        // surfaced.
                        if let Err(e) = timer_services.delete_workspace(timer_id.clone()).await {
                            tracing::warn!(
                                workspace = %timer_id.as_str(),
                                error = %e,
                                "scheduled workspace delete failed at commit"
                            );
                        }
                    })
                },
            ) {
                return Ok(existing);
            }
            publish_event(&bus, workspace_delete_scheduled_event(&id, &delete_at)).await;
            Ok(delete_at)
        })
    }

    fn cancel_workspace_delete(&self, id: WorkspaceId) -> BoxFuture<'_, Result<bool>> {
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            let cancelled = services.pending_workspace_deletes.cancel(id.as_str());
            if cancelled {
                publish_event(&bus, workspace_delete_cancelled_event(&id)).await;
            }
            Ok(cancelled)
        })
    }

    fn archive_workspace(
        &self,
        id: WorkspaceId,
        caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<Workspace>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let this = self.clone();
        // Graceful-interrupt capability: `agent_manager()` upgrades the weak
        // reference; read-only/test wiring with no manager attached simply
        // skips the sweep and still archives.
        let manager = self.agent_manager();
        Box::pin(async move {
            // Chief cannot be archived: it is a fixed virtual workspace, so
            // return the synthesized shape unchanged rather than mutating the
            // seeded row (TS virtual-workspace guard parity).
            if id.is_chief() {
                return Ok(chief_workspace());
            }
            let mut ws = store.get_workspace(&id).await?;
            let now = now_iso();
            ws.status = WorkspaceStatus::Archived;
            ws.archived = true;
            ws.archived_at = Some(now.clone());
            ws.updated_at = now;
            store.update_workspace(&ws).await?;
            // Everything below the persist runs on a DETACHED task
            // (intent-hq/monorepo#1577): the sweeps can cancel this very
            // caller. A background hook whose script calls
            // `ws.workspace.archive()` is itself swept by
            // `cancel_workspace_hooks` below, which aborts the hook's
            // scheduler task — i.e. the task awaiting this future. Inline,
            // that abort dropped the rest of the tail mid-flight and the
            // §6.5 `workspace:updated` delta was never published, leaving
            // clients stale on an archived workspace. Spawning detaches the
            // tail's lifetime from the caller's: aborting the caller only
            // drops the `JoinHandle` (never the task), so the sweeps, the
            // derived fields, and the emit always complete. On the hook path
            // the abort means `archive()` never returns to the script, which
            // stops running for good — the hook is `cancelled` by the sweep
            // like any other hook in the workspace.
            let id_for_log = id.clone();
            let tail = tokio::spawn(async move {
                let mut ws = ws;
                // Gracefully interrupt every in-flight turn in the workspace —
                // the `agent.stop` keep-alive semantics (`AgentManager::interrupt`):
                // turn cancelled over the wire, draining worker aborted, terminal
                // `agent:stream:end` emitted, provider child + ACP session kept
                // alive. Unlike `delete_workspace` nothing is deleted: session
                // rows, transcripts, completion watches, and pending message
                // queues all survive so unarchive can resume work. Runs AFTER the
                // archived row is persisted so any concurrent queue-drain kick
                // observes the archived flag and parks instead of respawning a
                // turn (see the archived gate in `try_drain_queue`).
                //
                // Residual race (deliberate trade-off): a drain that read the
                // workspace row BEFORE the persist above can still claim the
                // in-flight slot after the `list_busy` snapshot below, spawning
                // one stray turn in the freshly archived workspace that this
                // sweep misses. The window is a few statements wide and the
                // failure is benign — that turn runs to completion once and every
                // subsequent drain/wake parks behind the archived gates — so the
                // sweep accepts it rather than adding a post-claim re-check to
                // the hot drain path.
                //
                // The initiating agent (`caller_agent_id`, set on the agent-facing
                // `ws.workspace.archive` host — the MCP front door and the
                // background-hook runtime, which builds the same host for the
                // hook owner; the JSON-RPC front door passes `None`) is excluded.
                // On the MCP path the caller is necessarily mid-turn — blocked
                // awaiting this very tool call — so interrupting it aborts the
                // worker that owns the in-flight MCP dispatch: the tool result
                // never reaches the child, the turn never settles, and the busy
                // slot leaks (workspace activity stays `agent_running`). The
                // caller's turn ends normally once the tool result is delivered.
                // On the hook path the "caller" is the hook owner, which may have
                // an independent in-flight turn that this sweep now skips; that
                // turn runs to completion in the freshly archived workspace and
                // every subsequent drain/wake parks behind the archived gates —
                // the same benign-runaway trade-off as the residual race above.
                if let Some(manager) = manager {
                    for (agent_id, agent_ws) in manager.list_busy() {
                        if agent_ws == id && Some(&agent_id) != caller_agent_id.as_ref() {
                            manager.interrupt(&agent_id).await;
                        }
                    }
                }
                // Cancel every active background hook in the workspace: task
                // aborted, state persisted to `cancelled`, `hook:cancelled`
                // emitted, owner woken with a notice. Unarchive does NOT
                // resurrect cancelled hooks — the notice tells the owner to
                // reschedule if the condition still matters. Runs AFTER the
                // archived row is persisted so the cancel wakes park behind the
                // archived gate in `deliver_wake_message` (queued at most, no
                // turn spawned) — the same reason the interrupt sweep above
                // runs post-persist.
                this.cancel_workspace_hooks(&id).await;
                // Cancel every ACTIVE PR monitor the same way
                // (intent-hq/monorepo#1828): state persisted to `cancelled`,
                // `prMonitor:cancelled` emitted, owner woken with a notice
                // that parks behind the same archived gate. Unarchive does
                // NOT resurrect cancelled monitors. Without this sweep an
                // archived workspace's displayStatus rollup reads
                // `in_progress` indefinitely off the active-monitor signal.
                this.cancel_workspace_pr_monitors(&id).await;
                // Derive `lastActivity` (§9.1) so archive callers get the
                // authoritative wire shape without a follow-up `workspace.get`,
                // and persist it through the scoped monotonic write
                // (monorepo#1585).
                this.derive_and_persist_last_activity(&mut ws, "workspace.archive")
                    .await;
                // Derive `activity` from live agent state (§9.9) so the mutation
                // response carries `agent_running` when agents are in-flight,
                // not the stale default `idle` from the persisted row.
                ws.activity = this.workspace_activity(&ws.id);
                // §6.5 has no `workspace:archived`; mirror the reference emitter and
                // publish `workspace:updated` with the full applied delta
                // (`archived`/`status`/`archivedAt`) so subscribers flip state
                // without a re-read. `archivedAt` is the same timestamp persisted
                // on the row above.
                publish_event(
                    &bus,
                    workspace_updated_event(
                        &ws.id,
                        serde_json::json!({
                            "archived": true,
                            "status": ws.status,
                            "archivedAt": ws.archived_at,
                        }),
                    ),
                )
                .await;
                ws
            });
            // Awaiting the handle keeps the caller-visible contract intact
            // (the archived workspace is returned only after the tail ran);
            // a cancelled caller simply drops this await while the detached
            // tail runs on. A `JoinError` means the tail itself panicked —
            // the row is already archived, so surface it rather than
            // reporting a bogus success shape.
            tail.await.map_err(|e| {
                // The `JoinError` text names no workspace, so log the id —
                // otherwise a panicked tail is undiagnosable from daemon logs.
                tracing::error!(
                    workspace = %id_for_log.as_str(),
                    error = %e,
                    "workspace.archive: post-persist tail task failed; row is archived"
                );
                Error::Internal(format!("archive tail task failed: {e}"))
            })
        })
    }

    fn unarchive_workspace(&self, id: WorkspaceId) -> BoxFuture<'_, Result<Workspace>> {
        let this = self.clone();
        // Manual unarchive (`workspace.unarchive` / `workspace.restore`):
        // no `autoUnarchive` stamp on the emitted delta (absent ≠
        // present-false, PROTOCOL §6.5).
        Box::pin(async move { this.unarchive_workspace_inner(id, None).await })
    }

    fn duplicate_workspace(
        &self,
        id: WorkspaceId,
        new_title: Option<String>,
    ) -> BoxFuture<'_, Result<Workspace>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let worktree_locks = self.worktree_locks.clone();
        let this = self.clone();
        let boot_workspaces_root = self.workspaces_root.clone();
        let cow_isolation = self.effective_settings().workspace.cow_isolation;
        let worktrees_location = settings::worktrees_location(&self.effective_settings());
        // Startup pin (`INTENTD_WORKSPACES_DIR` → pinned `workspaces.root`)
        // keeps precedence over the `workspace.worktreesLocation` setting.
        let workspaces_root_pinned = self
            .settings_registry
            .as_deref()
            .and_then(|r| r.origin("workspaces.root"))
            == Some(SettingOrigin::Flag);
        Box::pin(async move {
            // Chief is virtual and never carries user content; duplication is
            // not meaningful (TS parity: coverflow never exposes a duplicate
            // affordance on the seeded row).
            if id.is_chief() {
                return Err(Error::InvalidParams(
                    "cannot duplicate chief workspace".to_string(),
                ));
            }
            // Same parent-dir precedence as `workspace.create`: startup pin >
            // `workspace.worktreesLocation` > boot root — so a duplicate lands
            // next to where a freshly created workspace would.
            let workspaces_root = resolve_workspaces_parent(
                boot_workspaces_root,
                workspaces_root_pinned,
                &worktrees_location,
            )?;
            let source = store.get_workspace(&id).await?;
            // Fresh id: reuse the random adjective-animal slug generator and
            // uniquify against live rows, tombstones, and stray directories.
            // Retries stay bounded so a wildly saturated slug space fails fast
            // rather than looping forever; if the budget is exhausted without
            // finding an available slug we surface `Internal` rather than
            // silently returning a colliding id.
            let mut new_id = WorkspaceId::from(intent_core::slug::generate_workspace_slug());
            let mut found = false;
            for _ in 0..32 {
                if workspace_id_available(&store, &workspaces_root, &new_id).await {
                    found = true;
                    break;
                }
                new_id = WorkspaceId::from(intent_core::slug::generate_workspace_slug());
            }
            if !found {
                return Err(Error::Internal(
                    "workspace.duplicate: exhausted slug retries without finding an available id"
                        .to_string(),
                ));
            }
            let now = now_iso();
            let title = new_title
                .map(|t| t.trim().to_string())
                .filter(|t| !t.is_empty())
                .unwrap_or_else(|| {
                    if source.title.trim().is_empty() {
                        "Untitled (Copy)".to_string()
                    } else {
                        format!("{} (Copy)", source.title)
                    }
                });
            // Copy the source's configuration verbatim but reset runtime state:
            // fresh id, branch pinned to the new id (TS `duplicateWorkspace`
            // parity), no PR/aggregates/token-usage carried over. Worktree
            // provisioning below mirrors `workspace.create` — set on `ws`
            // *before* the `insert_workspace` call so the row persists with
            // its `worktreePath`/`baseCommitSha` in one write.
            let mut ws = Workspace {
                id: new_id.clone(),
                title,
                branch: new_id.0.clone(),
                base_ref: source.base_ref.clone(),
                base_commit_sha: None,
                status: WorkspaceStatus::Active,
                status_message: None,
                status_image_asset_id: None,
                activity: WorkspaceActivity::Idle,
                attention: WorkspaceAttention::None,
                created_at: now.clone(),
                updated_at: now.clone(),
                // Stamp the wire `lastActivity` at creation time (parity with
                // `workspace.create`) so the returned `Workspace` is never
                // missing it; the post-insert `derive_last_activity` below
                // then folds in any copied notes / activity carried over from
                // the source workspace.
                last_activity: Some(now.clone()),
                tags: source.tags.clone(),
                path: source.path.clone(),
                repository_path: source.repository_path.clone(),
                repository_owner: source.repository_owner.clone(),
                repository_name: source.repository_name.clone(),
                worktree_path: None,
                scope: source.scope.clone(),
                skip_worktree: source.skip_worktree,
                setup_script: None,
                is_remote: source.is_remote,
                default_model: source.default_model.clone(),
                pr_number: None,
                pr_url: None,
                pr_status: None,
                active_pull_request: None,
                pull_requests: None,
                archived: false,
                archived_at: None,
                task_stats: None,
                agent_summary: None,
                diff_summary: None,
                token_usage: None,
                cow_supported: None,
                display_status: None,
                waiting: false,
                checkout_mode: None,
                disk_usage: None,
                pending_delete_at: None,
            };
            // Provision the checkout for the duplicate (TS
            // `duplicateWorkspace` parity, mirroring the `workspace.create`
            // flow): a duplicated local workspace off a local git repo gets a
            // checkout at `<root>/<workspaceId>/<repo-slug>` on a branch named
            // for its id — a linked worktree, or a standalone CoW clone when
            // `workspace.cowIsolation` is on (same decision matrix as create,
            // including the worktree fallback on an Unsupported/failed
            // probe). Skipped for remote/`skipWorktree` sources and for
            // non-repo `repositoryPath`s. Provisioning failures are logged
            // and swallowed — the FE reference continues on worktree failure
            // ("Continue without worktree - user can create it manually").
            //
            // Exception (intent-hq/monorepo#1560): when the SOURCE's checkout
            // is standalone (`cow`/`direct`) the duplicate must never hold a
            // live filesystem reference into the source workspace's directory
            // — a linked worktree rooted there is orphaned when the source is
            // deleted, and deleting the duplicate mutates the source. Such a
            // duplicate is always standalone too (CoW clone, else a plain
            // local clone), `workspace.cowIsolation` is ignored (parity with
            // cache-hydrated create), and the source checkout — not the
            // source's `repositoryPath` — is the clone source.
            let source_standalone = matches!(
                source.checkout_mode,
                Some(intent_core::CheckoutMode::Cow) | Some(intent_core::CheckoutMode::Direct)
            );
            // For a hydrated standalone source the checkout is `worktreePath`;
            // for an `isNewRepo` `direct` source there is none and the
            // repository itself IS the checkout.
            let repo_dir = source_standalone
                .then(|| {
                    source
                        .worktree_path
                        .as_deref()
                        .filter(|p| !p.is_empty())
                        .map(PathBuf::from)
                })
                .flatten()
                .or_else(|| {
                    ws.repository_path
                        .as_deref()
                        .filter(|p| !p.is_empty())
                        .map(PathBuf::from)
                });
            if let Some(repo_dir) = repo_dir {
                if !ws.is_remote && !ws.skip_worktree && repo_dir.join(".git").exists() {
                    let repo_name =
                        known_repo_name(ws.repository_name.as_deref(), &repo_dir.to_string_lossy());
                    let ws_dir = workspaces_root.join(&ws.id.0);
                    let wt_path = ws_dir.join(worktree_folder_slug(&repo_name));
                    let mode = if source_standalone {
                        // Standalone source: probe CoW from the source
                        // checkout and fall back to a plain local clone —
                        // never a linked worktree. A gitfile `.git` skips the
                        // probe (CoW-cloning it would rewrite the source
                        // checkout on the branch switch + hard reset) and goes
                        // straight to the clone, which is safe from any
                        // checkout shape.
                        if repo_dir.join(".git").is_file() {
                            tracing::warn!(
                                source_checkout = %repo_dir.display(),
                                "workspace.duplicate: standalone source checkout has a gitfile .git; provisioning a plain local clone instead of a CoW clone"
                            );
                            intent_core::CheckoutMode::Direct
                        } else {
                            std::fs::create_dir_all(&ws_dir).map_err(|e| {
                                Error::Internal(format!(
                                    "cannot create workspace dir for CoW probe: {e}"
                                ))
                            })?;
                            let probe_repo = repo_dir.clone();
                            let probe_dst = ws_dir.clone();
                            let support = tokio::task::spawn_blocking(move || {
                                intent_git::cow_probe(&probe_repo, &probe_dst)
                            })
                            .await
                            .map_err(|e| Error::Internal(format!("CoW probe task failed: {e}")))?;
                            match support {
                                Ok(intent_git::CowSupport::Supported) => {
                                    intent_core::CheckoutMode::Cow
                                }
                                Ok(intent_git::CowSupport::Unsupported) => {
                                    intent_core::CheckoutMode::Direct
                                }
                                Err(e) => {
                                    tracing::warn!(
                                        source_checkout = %repo_dir.display(),
                                        error = %e,
                                        "workspace.duplicate: CoW probe failed; duplicating the standalone source via a local clone (direct)"
                                    );
                                    intent_core::CheckoutMode::Direct
                                }
                            }
                        }
                    } else if cow_isolation && repo_dir.join(".git").is_file() {
                        // A linked worktree's `.git` is a gitfile pointing
                        // into the original repository's
                        // `.git/worktrees/<name>`: CoW-cloning it would give
                        // the clone a `.git` that still points at the
                        // ORIGINAL repo, so the branch switch + hard reset
                        // would rewrite the user's source checkout. Provision
                        // a linked worktree instead.
                        tracing::warn!(
                            repository_path = %repo_dir.display(),
                            "workspace.duplicate: repositoryPath has a gitfile .git (linked worktree or submodule checkout); CoW-cloning it would corrupt the source checkout — provisioning a linked worktree instead"
                        );
                        intent_core::CheckoutMode::Worktree
                    } else if cow_isolation {
                        // CoW probe: repo dir → `<root>/<wsId>` (the clone's
                        // parent). Same fallback semantics as create: the
                        // repository can live on any filesystem and reflinks
                        // cannot cross volumes, so Unsupported (or a probe
                        // error) falls back to a linked worktree instead of
                        // failing the duplicate.
                        std::fs::create_dir_all(&ws_dir).map_err(|e| {
                            Error::Internal(format!(
                                "cannot create workspace dir for CoW probe: {e}"
                            ))
                        })?;
                        let probe_repo = repo_dir.clone();
                        let probe_dst = ws_dir.clone();
                        let support = tokio::task::spawn_blocking(move || {
                            intent_git::cow_probe(&probe_repo, &probe_dst)
                        })
                        .await
                        .map_err(|e| Error::Internal(format!("CoW probe task failed: {e}")))?;
                        match support {
                            Ok(intent_git::CowSupport::Supported) => intent_core::CheckoutMode::Cow,
                            Ok(intent_git::CowSupport::Unsupported) => {
                                tracing::warn!(
                                    repository_path = %repo_dir.display(),
                                    workspaces_root = %workspaces_root.display(),
                                    "workspace.duplicate: CoW isolation is enabled but the repository's filesystem cannot CoW-clone into the workspaces root; falling back to a linked worktree"
                                );
                                intent_core::CheckoutMode::Worktree
                            }
                            Err(e) => {
                                tracing::warn!(
                                    repository_path = %repo_dir.display(),
                                    error = %e,
                                    "workspace.duplicate: CoW probe failed; falling back to a linked worktree"
                                );
                                intent_core::CheckoutMode::Worktree
                            }
                        }
                    } else {
                        intent_core::CheckoutMode::Worktree
                    };
                    // Uniquify the branch name against the source repo's
                    // local/remote-tracking branches so a `newId` collision
                    // with an existing branch (rare, but possible when the
                    // repo already carries prior workspace branches) does not
                    // fail the worktree provisioning.
                    let branch_repo = repo_dir.clone();
                    let desired = ws.branch.clone();
                    let branch_result = tokio::task::spawn_blocking(move || {
                        intent_git::branches::ensure_unique_branch_name(&branch_repo, &desired)
                    })
                    .await;
                    let branch = match branch_result {
                        Ok(Ok(b)) => b,
                        Ok(Err(e)) => {
                            tracing::warn!(
                                workspace = %ws.id.as_str(),
                                error = %e,
                                "workspace.duplicate: branch uniquification failed; falling back to workspace-id branch name"
                            );
                            ws.branch.clone()
                        }
                        Err(join_err) => {
                            tracing::warn!(
                                workspace = %ws.id.as_str(),
                                error = %join_err,
                                "workspace.duplicate: branch uniquification task failed; falling back to workspace-id branch name"
                            );
                            ws.branch.clone()
                        }
                    };
                    ws.branch = branch.clone();
                    let name = ws.id.0.clone();
                    let base_ref = ws.base_ref.clone();
                    let provision = |mode: intent_core::CheckoutMode| {
                        let name = name.clone();
                        let base_ref = base_ref.clone();
                        let repo = repo_dir.clone();
                        let wt = wt_path.clone();
                        let provision_branch = branch.clone();
                        let locks = worktree_locks.clone();
                        let lock_key = repo_dir.clone();
                        async move {
                            // `cowCloneExclude` comes from the source repo's
                            // config; only the CoW clone path consumes it.
                            let clone_excludes = if mode == intent_core::CheckoutMode::Cow {
                                repo_config::read_repo_config(&repo)
                                    .await
                                    .cow_clone_exclude
                                    .unwrap_or_default()
                            } else {
                                Vec::new()
                            };
                            let lock_requested = std::time::Instant::now();
                            locks
                                .with_lock(&lock_key, move || async move {
                                    let lock_wait = lock_requested.elapsed();
                                    let provision_started = std::time::Instant::now();
                                    let repo_for_log = repo.clone();
                                    let result = tokio::task::spawn_blocking(move || match mode {
                                        intent_core::CheckoutMode::Cow => {
                                            intent_git::cow_checkout::provision_cow_checkout(
                                                &repo,
                                                &wt,
                                                &provision_branch,
                                                base_ref.as_deref(),
                                                "origin",
                                                &clone_excludes,
                                            )
                                        }
                                        intent_core::CheckoutMode::Worktree => {
                                            intent_git::worktree::provision_worktree(
                                                &repo,
                                                &name,
                                                &wt,
                                                &provision_branch,
                                                base_ref.as_deref(),
                                                "origin",
                                            )
                                        }
                                        // Standalone (`cow`/`direct`) sources
                                        // fall back to a self-contained plain
                                        // local clone of the source checkout
                                        // rather than a linked worktree
                                        // rooted in it (monorepo#1560).
                                        intent_core::CheckoutMode::Direct => {
                                            intent_git::cow_checkout::provision_local_clone_checkout(
                                                &repo,
                                                &wt,
                                                &provision_branch,
                                                base_ref.as_deref(),
                                            )
                                        }
                                    })
                                    .await;
                                    tracing::info!(
                                        repository_path = %repo_for_log.display(),
                                        mode = ?mode,
                                        lock_wait_ms = lock_wait.as_millis() as u64,
                                        provision_ms = provision_started.elapsed().as_millis() as u64,
                                        ok = matches!(&result, Ok(Ok(_))),
                                        "workspace.duplicate: checkout provisioning lock wait + duration"
                                    );
                                    result
                                })
                                .await
                        }
                    };
                    let sha_result = provision(mode).await;
                    let (mode, sha_result) = match sha_result {
                        Ok(Err(Error::Unsupported(reason)))
                            if mode == intent_core::CheckoutMode::Cow =>
                        {
                            // Safety net (create parity): the pre-provisioning
                            // probe passed but the clone itself was still
                            // unsupported. Retry — as a plain local clone for
                            // a standalone source (never a worktree rooted in
                            // its checkout), else as a linked worktree; the
                            // #774 empty-dir cleanup runs between attempts.
                            let retry_mode = if source_standalone {
                                intent_core::CheckoutMode::Direct
                            } else {
                                intent_core::CheckoutMode::Worktree
                            };
                            tracing::warn!(
                                repository_path = %repo_dir.display(),
                                reason = %reason,
                                retry_mode = ?retry_mode,
                                "workspace.duplicate: CoW checkout provisioning unsupported despite a passing probe; retrying"
                            );
                            remove_workspace_dir_if_empty(&ws_dir);
                            (retry_mode, provision(retry_mode).await)
                        }
                        other => (mode, other),
                    };
                    // `provision_worktree` creates (or reuses) the branch
                    // before `git worktree add`; on partial failure the branch
                    // may exist without a worktree tracking it, and
                    // `workspace.delete` only cleans the branch when
                    // `worktree_path` is set. Best-effort delete it here to
                    // avoid orphaning a `<workspaceId>` branch in the source
                    // repo. Runs for both the inner-error and JoinError paths
                    // because the blocking task may have created the branch
                    // before panicking. Not needed for CoW: the branch is
                    // created only inside the clone, which
                    // `provision_cow_checkout` already removes on failure —
                    // the source repository is never touched.
                    let ws_id = ws.id.clone();
                    let cleanup_orphan_branch = |reason: &'static str| {
                        // Two owned handles to the same repo path: `lock_key`
                        // is borrowed by `with_lock`, while `repo_for_delete`
                        // is moved into the blocking closure. Splitting them
                        // avoids a borrow/move conflict on a single binding.
                        let lock_key = repo_dir.clone();
                        let repo_for_delete = repo_dir.clone();
                        let cleanup_branch = branch.clone();
                        let cleanup_locks = worktree_locks.clone();
                        let cleanup_ws_id = ws_id.clone();
                        let branch_for_log = branch.clone();
                        async move {
                            let cleanup = cleanup_locks
                                .with_lock(&lock_key, move || async move {
                                    tokio::task::spawn_blocking(move || {
                                        intent_git::branches::delete_local_branch(
                                            &repo_for_delete,
                                            &cleanup_branch,
                                        )
                                    })
                                    .await
                                })
                                .await;
                            match cleanup {
                                Ok(Ok(())) => {}
                                Ok(Err(cleanup_err)) => tracing::debug!(
                                    workspace = %cleanup_ws_id.as_str(),
                                    branch = %branch_for_log,
                                    reason,
                                    error = %cleanup_err,
                                    "workspace.duplicate: best-effort branch cleanup did not delete branch (may not have been created)"
                                ),
                                Err(join_err) => tracing::warn!(
                                    workspace = %cleanup_ws_id.as_str(),
                                    branch = %branch_for_log,
                                    reason,
                                    error = %join_err,
                                    "workspace.duplicate: best-effort branch cleanup task failed"
                                ),
                            }
                        }
                    };
                    match sha_result {
                        Ok(Ok(sha)) => {
                            ws.worktree_path = Some(wt_path.to_string_lossy().to_string());
                            ws.base_commit_sha = Some(sha);
                            ws.checkout_mode = Some(mode);
                            if source_standalone {
                                // Self-contained duplicate (monorepo#1560,
                                // create-hydration parity): the workspace
                                // checkout IS the repository, so
                                // `repositoryPath` must point at it rather
                                // than at the source workspace's directory —
                                // which dangles once the source is deleted
                                // and breaks repo-config reads and
                                // duplicate-of-a-duplicate.
                                ws.repository_path = Some(wt_path.to_string_lossy().to_string());
                            }
                        }
                        Ok(Err(e)) => {
                            tracing::warn!(
                                workspace = %ws.id.as_str(),
                                error = %e,
                                "workspace.duplicate: checkout provisioning failed; continuing without worktree"
                            );
                            if mode == intent_core::CheckoutMode::Worktree {
                                cleanup_orphan_branch("provision_worktree returned Err").await;
                            }
                            clear_standalone_repository_path(&mut ws, source_standalone);
                            if cow_isolation || source_standalone {
                                // The CoW probe pre-created `<root>/<wsId>`
                                // (both for a CoW checkout and for the
                                // worktree/local-clone fallback); drop it if
                                // it is left empty (#774). The metadata write
                                // below recreates the dir with content for the
                                // (worktree-less) duplicate row.
                                remove_workspace_dir_if_empty(&ws_dir);
                            }
                        }
                        Err(join_err) => {
                            tracing::warn!(
                                workspace = %ws.id.as_str(),
                                error = %join_err,
                                "workspace.duplicate: checkout provisioning task failed"
                            );
                            if mode == intent_core::CheckoutMode::Worktree {
                                cleanup_orphan_branch("provision_worktree task JoinError").await;
                            }
                            clear_standalone_repository_path(&mut ws, source_standalone);
                            if cow_isolation || source_standalone {
                                remove_workspace_dir_if_empty(&ws_dir);
                            }
                        }
                    }
                }
            }
            // Seed the duplicate's auto-commit override from the source's
            // effective value (source override → global fallback) in the same
            // INSERT, matching the atomic mirror-at-creation semantics of
            // `workspace.create`.
            let source_auto_commit = this.effective_auto_commit(&id).await;
            store
                .insert_workspace_with_auto_commit(&ws, Some(source_auto_commit))
                .await?;
            // Record branch provenance so `workspace.delete` cleans up the
            // duplicated branch alongside its worktree (same guard as
            // `workspace.create`: only auto-generated branches are deleted).
            if ws.worktree_path.is_some() {
                if let Err(e) = store
                    .set_workspace_branch_auto_generated(&ws.id, true)
                    .await
                {
                    tracing::warn!(error = %e, "failed to record branch provenance");
                }
            }
            if let Err(e) = write_workspace_metadata_file(&workspaces_root, &ws) {
                tracing::warn!(
                    workspace = %ws.id.as_str(),
                    error = %e,
                    "workspace.duplicate: failed to write .workspace/workspace.json"
                );
            }
            publish_event(&bus, workspace_created_event(&ws)).await;
            // `workspace.duplicate` never runs a setup script, but the setup
            // lifecycle (§6.5) still completes so clients waiting on
            // `workspace:setup:completed` converge on every create-shaped flow.
            publish_event(&bus, workspace_setup_completed_event(&ws.id, false, None)).await;
            // Seed the default spec note for the new workspace (mirrors the
            // `workspace.create` flow so `note.list` returns the well-known
            // `spec` id immediately).
            ensure_spec_note(&store, &bus, &ws.id).await?;
            // Copy over every non-`spec` note from the source with a freshly
            // minted id; per-note failures are logged and skipped so a single
            // bad row does not abort the duplication.
            match store.list_notes(&id).await {
                Ok(source_notes) => {
                    for src in source_notes {
                        if src.id.as_str() == "spec" {
                            continue;
                        }
                        let clone = Note {
                            id: NoteId::new(),
                            workspace_id: ws.id.clone(),
                            title: src.title,
                            content: src.content,
                            content_type: src.content_type,
                            tags: src.tags,
                            is_pinned: src.is_pinned,
                            is_archived: src.is_archived,
                            is_default: false,
                            parent_id: None,
                            visibility: src.visibility,
                            metadata: NoteMetadata::default(),
                            created_at: now.clone(),
                            rev: 0,
                            updated_at: now.clone(),
                        };
                        if let Err(e) = store.insert_note(&clone).await {
                            tracing::warn!(
                                workspace = %ws.id.as_str(),
                                error = %e,
                                "workspace.duplicate: failed to copy note"
                            );
                        }
                    }
                }
                Err(e) => tracing::warn!(
                    workspace = %id.as_str(),
                    error = %e,
                    "workspace.duplicate: failed to list source notes"
                ),
            }
            // Fold in copied notes/sessions so the returned `lastActivity`
            // matches what `workspace.list`/`workspace.get` would compute for
            // the new row (§9.1, mutation-path parity).
            this.derive_last_activity(&mut ws).await;
            // Derive `activity` from live agent state (§9.9) for consistency
            // with other mutation paths. For a fresh workspace with no agents,
            // activity naturally remains `idle`.
            ws.activity = this.workspace_activity(&ws.id);
            Ok(ws)
        })
    }

    fn cleanup_workspace(&self, id: WorkspaceId) -> BoxFuture<'_, Result<()>> {
        let store = self.store.clone();
        let workspaces_root = self
            .workspaces_root
            .clone()
            .unwrap_or_else(default_workspaces_root);
        let worktrees_location = self.configured_worktrees_location();
        Box::pin(async move {
            // Chief is virtual: no on-disk cache and no worktree — TS parity's
            // `isVirtualWorkspace` guard.
            if id.is_chief() {
                return Ok(());
            }
            // Confirm the row exists before touching disk so a bogus id
            // surfaces a `NotFound` at the trait layer instead of silently
            // sweeping a random directory.
            let ws = store.get_workspace(&id).await?;
            // Best-effort recursive delete of the daemon-owned cache directory
            // (`<parent>/<id>/cache`). The parent candidates cover the
            // persisted worktree's parent (the location in force at create
            // time) plus the boot root and the current
            // `workspace.worktreesLocation`, so caches under a custom
            // location are cleaned too. Missing / non-existent is a success;
            // other errors are logged and swallowed.
            for dir in workspace_dir_candidates(
                &id,
                ws.worktree_path.as_deref(),
                &workspaces_root,
                worktrees_location.as_deref(),
            ) {
                let cache_dir = dir.join("cache");
                let cache_task =
                    tokio::task::spawn_blocking(move || {
                        match std::fs::remove_dir_all(&cache_dir) {
                            Ok(()) => Ok(()),
                            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
                            Err(e) => Err(e),
                        }
                    })
                    .await;
                match cache_task {
                    Ok(Ok(())) => {}
                    Ok(Err(e)) => tracing::warn!(
                        workspace = %id.as_str(),
                        error = %e,
                        "workspace.cleanup: failed to remove cache directory"
                    ),
                    Err(join_err) => tracing::warn!(
                        workspace = %id.as_str(),
                        error = %join_err,
                        "workspace.cleanup: cache cleanup task failed"
                    ),
                }
            }
            // Run `git gc` against the worktree when there is one — reclaims
            // loose objects and packs (TS `cleanupWorkspace` parity).
            // Failures do not fail the RPC.
            if let Some(wt) = ws
                .worktree_path
                .as_deref()
                .filter(|p| !p.is_empty())
                .map(PathBuf::from)
            {
                if wt.exists() {
                    let gc = tokio::task::spawn_blocking(move || {
                        std::process::Command::new("git")
                            .arg("gc")
                            .arg("--auto")
                            .current_dir(&wt)
                            .output()
                    })
                    .await;
                    match gc {
                        Ok(Ok(out)) if !out.status.success() => {
                            tracing::warn!(
                                workspace = %id.as_str(),
                                stderr = %String::from_utf8_lossy(&out.stderr),
                                "workspace.cleanup: git gc reported non-zero exit"
                            );
                        }
                        Ok(Err(e)) => tracing::warn!(
                            workspace = %id.as_str(),
                            error = %e,
                            "workspace.cleanup: git gc failed"
                        ),
                        Err(join_err) => tracing::warn!(
                            workspace = %id.as_str(),
                            error = %join_err,
                            "workspace.cleanup: git gc task failed"
                        ),
                        _ => {}
                    }
                }
            }
            Ok(())
        })
    }

    fn find_repositories(&self, directory: String) -> BoxFuture<'_, Result<Vec<String>>> {
        Box::pin(async move {
            let requested = PathBuf::from(&directory);
            // Normalize a relative `directory` to an absolute base against the
            // daemon's cwd before scanning so the response matches the
            // protocol contract (absolute paths). `canonicalize` is preferred
            // because it resolves symlinks and `..`, but fall back to a plain
            // `cwd.join(requested)` when the path does not exist yet so the
            // scan can still surface an empty result rather than an error.
            let root = if requested.is_absolute() {
                requested
            } else {
                match std::fs::canonicalize(&requested) {
                    Ok(p) => p,
                    Err(_) => match std::env::current_dir() {
                        Ok(cwd) => cwd.join(&requested),
                        Err(_) => requested,
                    },
                }
            };
            let scan = tokio::task::spawn_blocking(move || {
                let mut out = Vec::new();
                scan_for_repositories(&root, 0, &mut out);
                out
            })
            .await
            .map_err(|e| Error::Internal(format!("find_repositories task failed: {e}")))?;
            Ok(scan)
        })
    }

    fn initialize_repository(&self, path: String) -> BoxFuture<'_, Result<()>> {
        Box::pin(async move {
            let repo_path = PathBuf::from(&path);
            tokio::task::spawn_blocking(move || initialize_repository_blocking(&repo_path))
                .await
                .map_err(|e| Error::Internal(format!("initialize_repository task failed: {e}")))?
        })
    }

    fn dismiss_attention(&self, id: WorkspaceId) -> BoxFuture<'_, Result<Workspace>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let this = self.clone();
        Box::pin(async move {
            // Chief has no attention state to dismiss (synthesized as `None`).
            if id.is_chief() {
                return Ok(chief_workspace());
            }
            this.park_attention_write().await;
            // Dismissing attention merely acknowledges it — not "activity" —
            // so never touch `updated_at` (which feeds the derived
            // `lastActivity`) (intent-hq/monorepo#1466). Scoped, conditional
            // write (monorepo#1481): one guarded UPDATE touching only the
            // attention column — a concurrent mutation of any other column is
            // never clobbered — whose row count decides "changed", so the
            // no-op skip and the emit decision are atomic rather than
            // read-based.
            let changed = store
                .set_workspace_attention(&id, WorkspaceAttention::None, None, None)
                .await?;
            if changed {
                // Self-sufficient `workspace:attention-changed` so every client
                // clears the blue dot together (PROTOCOL §6.5); emit only on an
                // actual change.
                publish_event(&bus, attention_changed_event(&id, WorkspaceAttention::None)).await;
                // The cleared flag feeds the derived displayStatus
                // (`review_required` axis, §6.5): recompute-and-compare.
                this.maybe_emit_display_status_changed(&id).await;
            }
            let mut ws = store.get_workspace(&id).await?;
            // Derive `activity` from live agent state (§9.9) so the mutation
            // response carries `agent_running` when agents are in-flight,
            // not the stale default `idle` from the persisted row.
            ws.activity = this.workspace_activity(&ws.id);
            Ok(ws)
        })
    }

    fn mark_seen(&self, id: WorkspaceId) -> BoxFuture<'_, Result<Workspace>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let this = self.clone();
        Box::pin(async move {
            if id.is_chief() {
                return Ok(chief_workspace());
            }
            this.park_attention_write().await;
            // "Seen" clears the unread flag; review-required attention persists.
            // Merely looking at a workspace is not "activity", so `updated_at`
            // (which feeds the derived `lastActivity`) stays untouched
            // (intent-hq/monorepo#1466). Scoped, conditional write
            // (monorepo#1481): one UPDATE guarded on `attention = unread`
            // touching only the attention column — a concurrent mutation of
            // any other column is never clobbered — whose row count decides
            // "changed", so the clear-only-when-unread rule and the emit
            // decision are atomic rather than read-based.
            let changed = store
                .set_workspace_attention(
                    &id,
                    WorkspaceAttention::None,
                    None,
                    Some(WorkspaceAttention::Unread),
                )
                .await?;
            if changed {
                // The unread flag is not a displayStatus axis (§6.5), so
                // clearing it never moves the derived rollup — no recompute.
                publish_event(&bus, attention_changed_event(&id, WorkspaceAttention::None)).await;
            }
            let mut ws = store.get_workspace(&id).await?;
            // Derive `activity` from live agent state (§9.9) so the mutation
            // response carries `agent_running` when agents are in-flight,
            // not the stale default `idle` from the persisted row.
            ws.activity = this.workspace_activity(&ws.id);
            Ok(ws)
        })
    }

    fn publish_event(&self, event: intent_core::PublishEvent) -> BoxFuture<'_, Result<()>> {
        use intent_core::now_iso;
        use intent_store::NewEvent;

        let bus = self.event_bus.clone();
        Box::pin(async move {
            let new_event = NewEvent {
                workspace_id: event.workspace_id,
                timestamp: now_iso(),
                event_type: event.event_type,
                actor: system_actor(),
                session_id: None,
                correlation_id: None,
                parent_event_id: None,
                metadata: None,
                data: event.data,
            };
            publish_event(&bus, new_event).await;
            Ok(())
        })
    }

    fn get_token_usage(&self, id: WorkspaceId) -> BoxFuture<'_, Result<TokenUsage>> {
        let store = self.store.clone();
        Box::pin(async move {
            // The scan job is daemon-internal; this is the wire read. Surface a
            // default (empty, `lastScanAt: null`) snapshot before the first scan;
            // `NotFound` propagates so the router maps it to `-32602` (§5.23).
            let ws = store.get_workspace(&id).await?;
            Ok(ws.token_usage.unwrap_or_default())
        })
    }

    fn get_workspace_auto_commit(
        &self,
        id: WorkspaceId,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let this = self.clone();
        Box::pin(async move {
            // Chief's seeded row is excluded from reads and never commits, so
            // force `source: "global"` regardless of the row's column — without
            // this guard a stray write to the seeded row would flip the source
            // to "workspace". Real workspaces surface `NotFound` from the store
            // so the router maps it to `-32602`.
            if id.is_chief() {
                return Ok(serde_json::json!({
                    "enabled": this.effective_settings().git.auto_commit,
                    "source": "global",
                }));
            }
            let (enabled, source) = match store.workspace_auto_commit(&id).await? {
                Some(v) => (v, "workspace"),
                None => (this.effective_settings().git.auto_commit, "global"),
            };
            Ok(serde_json::json!({ "enabled": enabled, "source": source }))
        })
    }

    fn set_workspace_auto_commit(
        &self,
        id: WorkspaceId,
        enabled: bool,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        Box::pin(async move {
            // Chief is virtual: nothing to persist and the toggle is not
            // meaningful for a workspace that never commits.
            if id.is_chief() {
                return Err(Error::InvalidParams(
                    "cannot set autoCommit on chief workspace".to_string(),
                ));
            }
            store.set_workspace_auto_commit(&id, enabled).await?;
            // Self-sufficient `workspace:updated` delta (§6.5) so live
            // clients mirror the toggle without a follow-up read.
            publish_event(
                &bus,
                workspace_updated_event(&id, serde_json::json!({ "autoCommitEnabled": enabled })),
            )
            .await;
            Ok(serde_json::json!({ "enabled": enabled, "source": "workspace" }))
        })
    }

    fn get_setup_script(&self, id: WorkspaceId) -> BoxFuture<'_, Result<SetupScript>> {
        let store = self.store.clone();
        Box::pin(async move {
            let ws = store.get_workspace(&id).await?;
            // Read from repo config (§5.25 sole source of truth); synthesize the
            // SetupScript record from the string. Legacy fallback: if repo config
            // is empty but the workspace DB row still has a setupScript (pre-change
            // data), return it read-only — never write it back to the DB.
            // Use git_ops::worktree_path (worktreePath first, repositoryPath fallback)
            // to match workspace.create and saveSetupScript (§5.25 + §5.33 consistency).
            if let Some(repo_path) = git_ops::worktree_path(&ws) {
                let repo_config = crate::repo_config::read_repo_config(&repo_path).await;
                if let Some(script_str) = repo_config.setup_script.filter(|s| !s.is_empty()) {
                    // Repo config has a script — derive updatedAt from file mtime (epoch ms).
                    let config_path = crate::repo_config::get_config_file_path(&repo_path);
                    let updated_at = tokio::fs::metadata(&config_path)
                        .await
                        .ok()
                        .and_then(|m| m.modified().ok())
                        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                        .map(|d| d.as_millis() as u64)
                        .unwrap_or(0);
                    return Ok(SetupScript {
                        script: script_str,
                        project_type: None,
                        updated_at,
                        generated_by: Some(intent_core::SetupScriptGeneratedBy::User),
                    });
                }
            }
            // Legacy fallback: return the DB value if present, else the default.
            Ok(ws.setup_script.unwrap_or_else(|| SetupScript {
                script: String::new(),
                project_type: None,
                updated_at: 0,
                generated_by: None,
            }))
        })
    }

    fn save_setup_script(
        &self,
        id: WorkspaceId,
        script: String,
    ) -> BoxFuture<'_, Result<SetupScript>> {
        let store = self.store.clone();
        Box::pin(async move {
            // Write to repo config instead of the DB row (§5.25 sole source of truth).
            let ws = store.get_workspace(&id).await?;
            // Use git_ops::worktree_path (worktreePath first, repositoryPath fallback)
            // to match workspace.create and getSetupScript (§5.25 + §5.33 consistency).
            let repo_path_buf = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::InvalidParams(
                    "workspace has no worktreePath or repositoryPath; cannot persist setup script"
                        .to_string(),
                )
            })?;
            let mut repo_config = crate::repo_config::read_repo_config(&repo_path_buf).await;
            repo_config.setup_script = if script.is_empty() {
                None
            } else {
                Some(script)
            };
            let written_script = repo_config
                .setup_script
                .as_deref()
                .unwrap_or("")
                .to_string();
            crate::repo_config::write_repo_config(&repo_path_buf, repo_config).await?;
            // Return the §5.25 SetupScript wire shape (synthesized from the written string).
            Ok(setup_scripts::user_script(written_script))
        })
    }

    fn detect_project_type(&self, id: WorkspaceId) -> BoxFuture<'_, Result<Option<ProjectType>>> {
        let store = self.store.clone();
        Box::pin(async move {
            let ws = store.get_workspace(&id).await?;
            Ok(git_ops::worktree_path(&ws).and_then(|p| setup_scripts::detect(&p)))
        })
    }

    fn generate_setup_script(&self, id: WorkspaceId) -> BoxFuture<'_, Result<SetupScript>> {
        let store = self.store.clone();
        Box::pin(async move {
            // AI-assisted draft: the provider/agent path is not wired into this
            // service, so generation falls back to the deterministic per-project
            // template generator. Returned (not persisted) with `generatedBy:
            // "agent"`; the client persists via `saveSetupScript` (§5.25).
            let ws = store.get_workspace(&id).await?;
            let project_type = git_ops::worktree_path(&ws).and_then(|p| setup_scripts::detect(&p));
            Ok(setup_scripts::generate(project_type))
        })
    }

