    fn set_note_content(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        content: String,
        confirm_replacement: bool,
        expected_version: Option<i64>,
        caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<NoteSetContentResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let old_content = note.content.clone();
            let previous_title = note.title.clone();
            if !old_content.is_empty() {
                let old_len = old_content.chars().count() as f64;
                let new_len = content.chars().count() as f64;
                let reduction = (old_len - new_len) / old_len * 100.0;
                if reduction > 50.0 && !confirm_replacement {
                    return Err(Error::Internal(format!(
                        "⚠️ CONTENT REDUCTION DETECTED: Your new content ({} chars) is {}% shorter than the existing content ({} chars).\n\nThis will REPLACE the entire note. If you intended to:\n- ADD content: Use note.add instead\n- EDIT a section: Use note.edit instead\n- PROCEED with replacement: Call note.setContent again with confirmReplacement=true",
                        content.chars().count(),
                        reduction.round() as i64,
                        old_content.chars().count()
                    )));
                }
            }
            // Route the full-content write through the CRDT merge engine
            // (`CRDTNotesService.applyContentUpdate`): the yrs `Doc` is seeded
            // from `old_content` on first touch and subsequent writes diff
            // against the doc's current text, so concurrent full-content
            // writes converge instead of last-write-wins. The merged text is
            // what we then clean + persist through the normal mutation flow,
            // so the line-attribution recompute still fires downstream.
            let merged = services.crdt_notes.apply_full_content(
                &workspace_id,
                &note_id,
                &old_content,
                &content,
            );
            let clean = note_ops::clean_set_content(&merged)?;
            let mut plan = reanchor_note_comments(&store, &workspace_id, &note_id, clean).await?;
            let clean = std::mem::take(&mut plan.content);
            note.content = clean.clone();
            let now = now_iso();
            note.updated_at = now.clone();
            store.update_note_versioned(&note, expected_version).await?;
            plan.apply_orphaned(&store, &workspace_id).await?;
            let author = resolve_note_version_author(&store, caller_agent_id.as_ref()).await;
            capture_note_version(&store, &note, &author).await?;
            services
                .schedule_line_attribution_recompute(note.workspace_id.clone(), note.id.clone());
            let outcome = services
                .auto_convert_task_blocks_after_write(
                    &note.workspace_id,
                    &note.id,
                    &clean,
                    caller_agent_id.as_ref(),
                )
                .await;
            let (final_content, final_updated_at) = match outcome.refetched_note {
                Some(n) => (n.content, n.updated_at),
                None => (clean, now),
            };
            publish_event(
                &bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            // A spec-body write can move taskStats (link-gated rollup);
            // non-spec notes skip the probe (§6.5).
            services
                .maybe_emit_display_status_for_spec_write(&note.workspace_id, &note.id)
                .await;
            Ok(NoteSetContentResult {
                ok: true,
                title: note.title,
                note_id: note.id,
                previous_title: Some(previous_title),
                updated_at: final_updated_at,
                old_content: Some(old_content),
                new_content: final_content,
                converted_count: outcome.converted_count,
                created_task_note_ids: outcome.created_note_ids,
                created_tasks: outcome.created_tasks,
                warnings: outcome.warnings,
            })
        })
    }

    fn update_note_metadata(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        title: Option<String>,
        tags: Option<Vec<String>>,
        expected_version: Option<i64>,
        // Metadata-only writes do not push a note-version snapshot (parity
        // with `notes.service.ts`), so the caller-agent hint is unused here.
        // Accepted for trait uniformity and future-proofing.
        _caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<NoteUpdateMetadataResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        Box::pin(async move {
            if title.is_none() && tags.is_none() {
                return Err(Error::Internal(
                    "At least one of title or tags must be provided".to_string(),
                ));
            }
            let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let is_spec = note_id.as_str() == "spec";
            let mut changed = false;
            // Spec title cannot be modified (matches the TS peer).
            if let Some(t) = title {
                if !is_spec {
                    note.title = t;
                    changed = true;
                }
            }
            if let Some(t) = tags {
                note.tags = t;
                changed = true;
            }
            if !changed {
                return Ok(NoteUpdateMetadataResult {
                    ok: true,
                    note_id,
                    title: None,
                    tags: None,
                    updated_at: None,
                    skipped: Some(true),
                    reason: Some("spec title cannot be modified".to_string()),
                });
            }
            let now = now_iso();
            note.updated_at = now.clone();
            store.update_note_versioned(&note, expected_version).await?;
            publish_event(
                &bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            Ok(NoteUpdateMetadataResult {
                ok: true,
                note_id: note.id,
                title: Some(note.title),
                tags: Some(note.tags),
                updated_at: Some(now),
                skipped: None,
                reason: None,
            })
        })
    }

    fn delete_note(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        expected_version: Option<i64>,
    ) -> BoxFuture<'_, Result<NoteDeleteResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            // Scope-check first so a foreign/absent note yields the peer message.
            let note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            // Snapshot the pre-delete note list for the ready-set comparison
            // below: the `note_parent_set_null_on_delete` trigger clears each
            // child's `parent_id` on delete, so the pre-delete tree cannot be
            // reconstructed from the post-delete rows.
            let before = if note.metadata.task.is_some() {
                Some(store.list_notes(&workspace_id).await?)
            } else {
                None
            };
            store
                .delete_note_versioned(&workspace_id, &note_id, expected_version)
                .await?;
            services.crdt_notes.remove(&workspace_id, &note_id);
            publish_event(
                &bus,
                note_change_event(&workspace_id, &note_id, &note.title, NOTE_DELETED, "delete"),
            )
            .await;
            if let Some(task) = &note.metadata.task {
                let remaining = store.list_notes(&workspace_id).await?;
                // Deleting a task note can move the readiness predicate three
                // ways: a dangling `dependsOn` edge counts as unmet, so
                // deleting a previously-`complete` dep flips its dependents
                // out of the ready set (monorepo#1981); deleting a task that
                // is itself in the ready set silently removes its id; and
                // deleting the last incomplete task child satisfies the tree
                // rule, so the parent ENTERS the set (both monorepo#2006).
                // Recompute + broadcast with the `reason: "note-deleted"`
                // trigger variant, before the dependent re-announce below
                // (same ordering as the status-transition path). Dependent
                // deletes keep the #1981 always-emit contract; otherwise the
                // pre-delete ready set (computed from the snapshot taken
                // before the store delete — see above) is compared with the
                // post-delete set, and a delete that provably cannot move the
                // set (e.g. a terminal task nobody depends on) still emits no
                // recompute. `compute_ready_task_ids` orders by
                // peerOrder/createdAt, so Vec equality is set equality.
                let depended_on = remaining.iter().any(|n| {
                    n.metadata
                        .task
                        .as_ref()
                        .is_some_and(|t| t.depends_on.iter().any(|d| d == &note_id))
                });
                let ready_task_ids = compute_ready_task_ids(&remaining);
                let ready_set_moved = depended_on
                    || before
                        .as_deref()
                        .is_none_or(|b| compute_ready_task_ids(b) != ready_task_ids);
                if ready_set_moved {
                    publish_event(
                        &bus,
                        ready_tasks_changed_reason_event(
                            &workspace_id,
                            ready_task_ids,
                            &note_id,
                            "note-deleted",
                            &now_iso(),
                        ),
                    )
                    .await;
                }
                // Deleting a *complete* task flips its dependents' computed
                // unmetDependsOn from met to unmet (missing = unmet), so
                // re-announce them for subscriber refetch (monorepo#1979).
                // Other statuses were already unmet — no projection change.
                if task.status == TaskStatus::Complete {
                    publish_dependent_note_updates(&bus, &workspace_id, &note_id, &remaining).await;
                }
                // Deleting a task note can move the derived displayStatus
                // rollup (§6.5), e.g. removing the last open spec-child task.
                services
                    .maybe_emit_display_status_changed(&workspace_id)
                    .await;
            }
            Ok(NoteDeleteResult {
                ok: true,
                note_id,
                deleted: true,
            })
        })
    }

    fn list_note_tasks(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
    ) -> BoxFuture<'_, Result<Vec<NoteTaskRow>>> {
        let store = self.store.clone();
        Box::pin(async move {
            let note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let mut rows = note_ops::parse_tasks(&note.content);
            // Mirror linked task notes' relations onto their rows. One
            // task-notes-only fetch (`task_json IS NOT NULL`), only when some
            // row is actually linked.
            if rows.iter().any(|r| r.task_note_id.is_some()) {
                let all = store.list_tasks(&workspace_id).await?;
                let status_by_id = task_status_by_id(&all);
                for row in &mut rows {
                    let Some(linked_id) = &row.task_note_id else {
                        continue;
                    };
                    let Some(task) = all
                        .iter()
                        .find(|n| n.id.as_str() == linked_id)
                        .and_then(|n| n.metadata.task.as_ref())
                    else {
                        continue;
                    };
                    row.depends_on = task.depends_on.clone();
                    row.conflicts_with = task.conflicts_with.clone();
                    row.unmet_depends_on = unmet_depends_on_ids(&task.depends_on, &status_by_id);
                }
            }
            Ok(rows)
        })
    }

    fn read_asset(
        &self,
        workspace_id: WorkspaceId,
        asset: String,
    ) -> BoxFuture<'_, Result<ReadAssetResult>> {
        let assets_root = self.assets_root.clone();
        Box::pin(async move {
            let asset_id = note_ops::parse_asset_id(&asset)?;
            let root = assets_root
                .ok_or_else(|| Error::Internal("asset storage is not configured".to_string()))?;
            let path = root.join(&workspace_id.0).join(&asset_id);
            let bytes = std::fs::read(&path)
                .map_err(|e| Error::Internal(format!("Failed to read asset: {e}")))?;
            let data = base64::engine::general_purpose::STANDARD.encode(&bytes);
            let size_kb = ((data.len() as f64) / 1024.0).round() as i64;
            let mime_type = note_ops::mime_from_extension(&asset_id);
            Ok(ReadAssetResult {
                asset_id,
                mime_type,
                data,
                size_kb,
            })
        })
    }

    fn save_asset(
        &self,
        workspace_id: WorkspaceId,
        data: String,
        mime_type: String,
        original_name: Option<String>,
    ) -> BoxFuture<'_, Result<SaveAssetResult>> {
        let assets_root = self.assets_root.clone();
        Box::pin(async move {
            let root = assets_root
                .ok_or_else(|| Error::Internal("asset storage is not configured".to_string()))?;
            let base64_data = note_ops::strip_data_url_prefix(&data);
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(base64_data.as_bytes())
                .map_err(|e| Error::Internal(format!("Failed to save asset: {e}")))?;
            let asset_id = note_ops::new_asset_id(base64_data, &mime_type);

            let dir = root.join(&workspace_id.0);
            std::fs::create_dir_all(&dir)
                .map_err(|e| Error::Internal(format!("Failed to save asset: {e}")))?;
            let path = dir.join(&asset_id);
            std::fs::write(&path, &bytes)
                .map_err(|e| Error::Internal(format!("Failed to save asset: {e}")))?;

            // Metadata sidecar, TS-peer parity (`<assetId>.meta.json`).
            let metadata = serde_json::json!({
                "id": asset_id,
                "originalName": original_name.unwrap_or_else(|| asset_id.clone()),
                "mimeType": mime_type,
                "size": bytes.len(),
                "createdAt": now_iso(),
            });
            let meta_path = dir.join(format!("{asset_id}.meta.json"));
            std::fs::write(
                &meta_path,
                serde_json::to_string_pretty(&metadata).unwrap_or_default(),
            )
            .map_err(|e| Error::Internal(format!("Failed to save asset metadata: {e}")))?;

            Ok(SaveAssetResult {
                url: format!("workspace-asset://{}/{}", workspace_id.0, asset_id),
                path: path.to_string_lossy().into_owned(),
                asset_id,
            })
        })
    }

