    fn task_update_status(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        task_text: String,
        status: String,
    ) -> BoxFuture<'_, Result<TaskUpdateStatusResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            if task_text.is_empty() {
                return Err(Error::Internal(
                    "Task text is required to identify the task".to_string(),
                ));
            }
            let checkbox = note_ops::checkbox_for(&status).ok_or_else(|| {
                Error::Internal("Status must be 'done', 'todo', or 'in-progress'".to_string())
            })?;
            let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let normalized = task_text.trim().to_string();
            let updated = note_ops::apply_task_status(&note.content, &normalized, checkbox)?;
            note.content = updated;
            note.updated_at = now_iso();
            store.update_note(&note).await?;
            services.invalidate_crdt_note(&note.workspace_id, &note.id);
            services
                .schedule_line_attribution_recompute(note.workspace_id.clone(), note.id.clone());
            publish_event(
                &bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            Ok(TaskUpdateStatusResult {
                ok: true,
                note_id: note.id,
                task_text: normalized,
                status,
            })
        })
    }

    fn task_update_note_status(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        status: String,
        expected_version: Option<i64>,
        caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<TaskUpdateNoteStatusResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            let new_status = parse_task_status_strict(&status)?;
            let mut note = fetch_note(&store, &workspace_id, &note_id).await?;
            let mut task = match note.metadata.task.clone() {
                Some(t) => t,
                None => {
                    return Err(Error::Internal(
                        "Note is not a task. Use markAsTask() first.".to_string(),
                    ))
                }
            };
            let previous_status = task.status;
            let now = now_iso();
            apply_status_transition(&mut task, new_status, &now);
            note.metadata.task = Some(task);
            note.updated_at = now.clone();
            store.update_note_versioned(&note, expected_version).await?;
            // Mirror `notes.service.ts`: emit only when the status actually changed.
            if previous_status != new_status {
                // A complete-boundary crossing records/removes the caller's
                // flipped-completion pair (later stamped as a wake trigger).
                track_flipped_completion_boundary(
                    &store,
                    caller_agent_id.as_ref(),
                    &note.workspace_id,
                    &note.id,
                    previous_status == TaskStatus::Complete,
                    new_status == TaskStatus::Complete,
                    &now,
                )
                .await;
                // LC-1: agent-attributed changes carry provenance — resolve the
                // caller's display name best-effort for the agent actor.
                let agent = match &caller_agent_id {
                    Some(agent_id) => Some((
                        agent_id.0.clone(),
                        store.get_agent_session(agent_id).await.ok().map(|s| s.name),
                    )),
                    None => None,
                };
                publish_event(
                    &bus,
                    task_status_changed_event(
                        &note.workspace_id,
                        &note.id,
                        &note.title,
                        previous_status,
                        new_status,
                        &now,
                        agent,
                    ),
                )
                .await;
                // Then recompute + broadcast the ready-task set, mirroring the
                // `emitReadyTasksChanged` call that follows `task:status-changed`.
                let all = store.list_notes(&note.workspace_id).await?;
                let ready_task_ids = compute_ready_task_ids(&all);
                publish_event(
                    &bus,
                    ready_tasks_changed_event(
                        &note.workspace_id,
                        ready_task_ids,
                        &note.id,
                        previous_status,
                        new_status,
                        &now_iso(),
                    ),
                )
                .await;
                // Re-announce dependents only when the transition crosses the
                // complete boundary — that is the only move that changes their
                // computed `unmetDependsOn` (monorepo#1979).
                if (previous_status == TaskStatus::Complete) != (new_status == TaskStatus::Complete)
                {
                    publish_dependent_note_updates(&bus, &note.workspace_id, &note.id, &all).await;
                }
                // A task-status transition can move the derived displayStatus
                // rollup (§6.5): recompute-and-compare, emitting only on an
                // actual transition.
                services
                    .maybe_emit_display_status_changed(&note.workspace_id)
                    .await;
            }
            Ok(TaskUpdateNoteStatusResult {
                ok: true,
                note_id: note.id.clone(),
                status: new_status,
                note,
            })
        })
    }

    fn task_update(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        line: i64,
        text: Option<String>,
        status: Option<String>,
        expected: Option<String>,
    ) -> BoxFuture<'_, Result<TaskUpdateResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            if text.is_none() && status.is_none() {
                return Err(Error::Internal(
                    "Either text or status (or both) must be provided".to_string(),
                ));
            }
            if line < 1 {
                return Err(Error::Internal(
                    "Line number must be a positive integer".to_string(),
                ));
            }
            if let Some(s) = status.as_deref() {
                if note_ops::checkbox_for(s).is_none() {
                    return Err(Error::Internal(
                        "Status must be 'todo', 'in-progress', or 'done'".to_string(),
                    ));
                }
            }
            let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let update = note_ops::apply_task_line_update(
                &note.content,
                line,
                text.as_deref(),
                status.as_deref(),
                expected.as_deref(),
            )?;
            note.content = update.content;
            note.updated_at = now_iso();
            store.update_note(&note).await?;
            services.invalidate_crdt_note(&note.workspace_id, &note.id);
            services
                .schedule_line_attribution_recompute(note.workspace_id.clone(), note.id.clone());
            publish_event(
                &bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            // A spec checkbox-line rewrite can add/remove task links and
            // move taskStats; non-spec notes skip the probe (§6.5).
            services
                .maybe_emit_display_status_for_spec_write(&note.workspace_id, &note.id)
                .await;
            Ok(TaskUpdateResult {
                ok: true,
                note_id: note.id,
                line_number: line,
                previous_text: update.previous_text,
                new_text: update.new_text,
                status: update.status_word,
            })
        })
    }

    fn task_list(
        &self,
        workspace_id: WorkspaceId,
        status: Option<String>,
    ) -> BoxFuture<'_, Result<TaskListResult>> {
        let store = self.store.clone();
        Box::pin(async move {
            let filter = match status.as_deref() {
                Some(s) => Some(parse_task_status_strict(s)?),
                None => None,
            };
            let notes = store.list_notes(&workspace_id).await?;
            // `tasks` membership is workspace-wide (every task note, flagged
            // with `specLinked`); `stats` stays the rollup over the full
            // spec-linked set (mirrors the FE `computeTaskStats`). The
            // optional `status` filter narrows `tasks` only.
            let stats = compute_task_stats(&notes);
            let mut tasks = workspace_task_list(&notes);
            if let Some(f) = filter {
                tasks.retain(|t| t.status == f);
            }
            Ok(TaskListResult { tasks, stats })
        })
    }

    fn task_get(
        &self,
        workspace_id: WorkspaceId,
        task_note_id: NoteId,
    ) -> BoxFuture<'_, Result<WorkspaceTask>> {
        let store = self.store.clone();
        Box::pin(async move {
            let note = match store.get_note(&workspace_id, &task_note_id).await {
                Ok(n) => n,
                Err(Error::NotFound(_)) => {
                    return Err(Error::NotFound(format!("task note {task_note_id}")))
                }
                Err(e) => return Err(e),
            };
            // `specLinked` needs the spec body; only fetch the full workspace
            // note set when there are `dependsOn` edges to project into
            // `unmetDependsOn` (the spec rides along in that read), otherwise
            // a single spec-note read suffices.
            let (status_by_id, linked) = match &note.metadata.task {
                Some(t) if !t.depends_on.is_empty() => {
                    let notes = store.list_notes(&workspace_id).await?;
                    let linked = notes
                        .iter()
                        .find(|n| n.id.as_str() == "spec")
                        .map(|n| extract_spec_task_ids(&n.content))
                        .unwrap_or_default();
                    (task_status_by_id(&notes), linked)
                }
                _ => {
                    let linked = match store.get_note(&workspace_id, &NoteId::from("spec")).await {
                        Ok(spec) => extract_spec_task_ids(&spec.content),
                        Err(Error::NotFound(_)) => HashSet::new(),
                        Err(e) => return Err(e),
                    };
                    (HashMap::new(), linked)
                }
            };
            let spec_linked = linked.contains(note.id.as_str());
            note_to_workspace_task(&note, &status_by_id, spec_linked)
        })
    }

    fn get_my_task(
        &self,
        workspace_id: WorkspaceId,
        task_note_id: NoteId,
    ) -> BoxFuture<'_, Result<TaskGetMyTaskResult>> {
        let store = self.store.clone();
        Box::pin(async move {
            let note = match store.get_note(&workspace_id, &task_note_id).await {
                Ok(n) => n,
                Err(Error::NotFound(_)) => {
                    return Err(Error::Internal("Task note not found".to_string()))
                }
                Err(e) => return Err(e),
            };
            let task = match note.metadata.task.clone() {
                Some(t) => t,
                None => return Err(Error::Internal("Note is not a task".to_string())),
            };
            let all = store.list_notes(&workspace_id).await?;
            let subtasks = all
                .iter()
                .filter(|n| n.parent_id.as_ref() == Some(&note.id) && n.metadata.task.is_some())
                .map(|n| TaskSubtask {
                    id: n.id.clone(),
                    title: n.title.clone(),
                    status: n
                        .metadata
                        .task
                        .as_ref()
                        .map(|t| status_word(t.status))
                        .unwrap_or("unknown")
                        .to_string(),
                })
                .collect();
            let unmet_depends_on = unmet_depends_on_ids(&task.depends_on, &task_status_by_id(&all));
            Ok(TaskGetMyTaskResult {
                note_id: note.id.clone(),
                title: note.title.clone(),
                content: note.content.clone(),
                status: task.status,
                parent_id: note.parent_id.clone(),
                assigned_agents: task.assigned_agent_ids.clone(),
                subtasks,
                task_metadata: task,
                rev: note.rev,
                unmet_depends_on,
            })
        })
    }

    fn mark_as_task(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        status: String,
        acceptance_criteria: Vec<String>,
        effort: Option<String>,
        depends_on: Option<Vec<NoteId>>,
        conflicts_with: Option<Vec<NoteId>>,
        caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<TaskMarkAsTaskResult>> {
        let store = self.store.clone();
        let services = self.clone();
        Box::pin(async move {
            let new_status =
                serde_json::from_value::<TaskStatus>(serde_json::Value::String(status.clone()))
                    .map_err(|_| Error::Internal(format!("Invalid status: {status}")))?;
            let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            // Relation writes are validated + cycle/tree-checked against the
            // workspace note set, exactly like `task.setRelations` (ALL notes,
            // not just tasks — the tree-relative check walks `parent_id`
            // chains that may cross non-task notes). The fetch only happens
            // when relations were supplied.
            let depends_on = depends_on.map(normalize_relation_ids);
            let conflicts_with = conflicts_with.map(normalize_relation_ids);
            if depends_on.is_some() || conflicts_with.is_some() {
                let all = store.list_notes(&workspace_id).await?;
                if let Some(deps) = &depends_on {
                    validate_relation_ids(&note.id, deps, &all, "dependsOn")?;
                    if let Some(cycle) = find_dependency_cycle(&note.id, deps, &all) {
                        return Err(Error::Internal(format!(
                            "dependsOn would create a cycle: {}",
                            cycle.join(" -> ")
                        )));
                    }
                    ensure_no_tree_relative_dependency(&note.id, deps, &all)?;
                }
                if let Some(conflicts) = &conflicts_with {
                    validate_relation_ids(&note.id, conflicts, &all, "conflictsWith")?;
                }
            }
            let now = now_iso();
            let previous_status = note.metadata.task.as_ref().map(|t| t.status);
            // A re-mark that replaces an existing task's `dependsOn` moves the
            // readiness predicate exactly like `task.setRelations`; capture
            // whether it actually changed so the same-status arm below can
            // recompute (monorepo#1981).
            let depends_on_changed = match (&note.metadata.task, &depends_on) {
                (Some(existing), Some(deps)) => existing.depends_on != *deps,
                _ => false,
            };
            match note.metadata.task.clone() {
                // Already a task with a changing status → preserve other fields.
                Some(mut existing) if existing.status != new_status => {
                    apply_status_transition(&mut existing, new_status, &now);
                    if let Some(deps) = depends_on {
                        existing.depends_on = deps;
                    }
                    if let Some(conflicts) = conflicts_with {
                        existing.conflicts_with = conflicts;
                    }
                    note.metadata.task = Some(existing);
                }
                // Fresh task (or same status) → set the markAsTask metadata.
                // Omitted relation params keep an existing task's relations
                // (same contract as the changing-status arm above).
                existing => {
                    let mut task = TaskMetadata {
                        status: new_status,
                        acceptance_criteria,
                        estimated_effort: effort,
                        depends_on: depends_on.unwrap_or_else(|| {
                            existing
                                .as_ref()
                                .map(|t| t.depends_on.clone())
                                .unwrap_or_default()
                        }),
                        conflicts_with: conflicts_with.unwrap_or_else(|| {
                            existing
                                .as_ref()
                                .map(|t| t.conflicts_with.clone())
                                .unwrap_or_default()
                        }),
                        ..Default::default()
                    };
                    apply_status_transition(&mut task, new_status, &now);
                    note.metadata.task = Some(task);
                }
            }
            note.updated_at = now.clone();
            store.update_note(&note).await?;
            // A markAsTask that crosses the complete boundary records/removes
            // the caller's flipped-completion pair, exactly like
            // `task.updateNoteStatus` (a same-status re-mark is a no-op here).
            track_flipped_completion_boundary(
                &store,
                caller_agent_id.as_ref(),
                &note.workspace_id,
                &note.id,
                previous_status == Some(TaskStatus::Complete),
                new_status == TaskStatus::Complete,
                &now,
            )
            .await;
            let agent = resolve_event_agent(&store, caller_agent_id.as_ref()).await;
            // The note's metadata changed, so subscribers need to refetch it
            // (§6.5) — without this a task-ness flip is invisible until the
            // next unrelated note write.
            publish_event(
                &services.event_bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            match previous_status {
                // Only a note that was not already a task is "created" as one.
                None => {
                    publish_event(
                        &services.event_bus,
                        task_created_event(
                            &note.workspace_id,
                            &note.id,
                            &note.title,
                            new_status,
                            &note.updated_at,
                            agent,
                        ),
                    )
                    .await;
                }
                // Re-marking an existing task is a status move, so it takes the
                // same `task:status-changed` + ready-set recompute pair
                // `task.updateNoteStatus` publishes.
                Some(previous) if previous != new_status => {
                    publish_event(
                        &services.event_bus,
                        task_status_changed_event(
                            &note.workspace_id,
                            &note.id,
                            &note.title,
                            previous,
                            new_status,
                            &now,
                            agent,
                        ),
                    )
                    .await;
                    let all = store.list_notes(&note.workspace_id).await?;
                    let ready_task_ids = compute_ready_task_ids(&all);
                    publish_event(
                        &services.event_bus,
                        ready_tasks_changed_event(
                            &note.workspace_id,
                            ready_task_ids,
                            &note.id,
                            previous,
                            new_status,
                            &now_iso(),
                        ),
                    )
                    .await;
                    // Re-announce dependents only when the re-mark crosses the
                    // complete boundary — the only move that changes their
                    // computed `unmetDependsOn` (monorepo#1979).
                    if (previous == TaskStatus::Complete) != (new_status == TaskStatus::Complete) {
                        publish_dependent_note_updates(
                            &services.event_bus,
                            &note.workspace_id,
                            &note.id,
                            &all,
                        )
                        .await;
                    }
                }
                // Same-status re-mark: no status-shaped emission ran, so a
                // `dependsOn` replace would otherwise leave ready-set
                // subscribers stale. Same recompute + `relations-changed`
                // trigger as `task.setRelations` (monorepo#1981).
                Some(_) => {
                    if depends_on_changed {
                        let all = store.list_notes(&note.workspace_id).await?;
                        let ready_task_ids = compute_ready_task_ids(&all);
                        publish_event(
                            &services.event_bus,
                            ready_tasks_changed_reason_event(
                                &note.workspace_id,
                                ready_task_ids,
                                &note.id,
                                "relations-changed",
                                &now_iso(),
                            ),
                        )
                        .await;
                    }
                }
            }
            // Marking a note as a task (or moving its status) can move the
            // derived displayStatus rollup (§6.5).
            services
                .maybe_emit_display_status_changed(&note.workspace_id)
                .await;
            Ok(TaskMarkAsTaskResult {
                ok: true,
                note_id: note.id,
                status: new_status,
            })
        })
    }

    fn task_set_relations(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        depends_on: Option<Vec<NoteId>>,
        conflicts_with: Option<Vec<NoteId>>,
    ) -> BoxFuture<'_, Result<TaskSetRelationsResult>> {
        let store = self.store.clone();
        let services = self.clone();
        Box::pin(async move {
            let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let mut task = match note.metadata.task.clone() {
                Some(t) => t,
                None => return Err(Error::Internal("Note is not a task".to_string())),
            };
            let depends_on = depends_on.map(normalize_relation_ids);
            let conflicts_with = conflicts_with.map(normalize_relation_ids);
            // Validation + cycle/tree checks read the same workspace snapshot
            // the write is based on (ALL notes, not just tasks — the
            // tree-relative check walks `parent_id` chains that may cross
            // non-task notes). Like every other task-metadata write this is
            // last-writer-wins (no versioned CAS): concurrent relation writes
            // are coordinator-driven and rare, and a racing write that slips a
            // stale cycle past the check degrades readiness for the tasks
            // involved, not data integrity.
            let all = store.list_notes(&workspace_id).await?;
            if let Some(deps) = &depends_on {
                validate_relation_ids(&note.id, deps, &all, "dependsOn")?;
                if let Some(cycle) = find_dependency_cycle(&note.id, deps, &all) {
                    return Err(Error::Internal(format!(
                        "dependsOn would create a cycle: {}",
                        cycle.join(" -> ")
                    )));
                }
                ensure_no_tree_relative_dependency(&note.id, deps, &all)?;
            }
            if let Some(conflicts) = &conflicts_with {
                validate_relation_ids(&note.id, conflicts, &all, "conflictsWith")?;
            }
            let mut changed = false;
            let mut depends_on_changed = false;
            if let Some(deps) = depends_on {
                depends_on_changed = task.depends_on != deps;
                changed |= depends_on_changed;
                task.depends_on = deps;
            }
            if let Some(conflicts) = conflicts_with {
                changed |= task.conflicts_with != conflicts;
                task.conflicts_with = conflicts;
            }
            let result = TaskSetRelationsResult {
                ok: true,
                note_id: note.id.clone(),
                depends_on: task.depends_on.clone(),
                conflicts_with: task.conflicts_with.clone(),
            };
            // No-op write (same lists after normalization) → skip the store
            // write and the `note:updated` emission entirely.
            if !changed {
                return Ok(result);
            }
            note.metadata.task = Some(task);
            note.updated_at = now_iso();
            store.update_note(&note).await?;
            // Metadata changed → subscribers refetch the note (§6.5), same as
            // every other task-metadata write.
            publish_event(
                &services.event_bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            // A changed `dependsOn` list moves the readiness predicate (adding
            // an edge can un-ready a task, clearing one can ready it), so
            // recompute + broadcast the ready set (monorepo#1981). The
            // `triggeredBy` variant carries `reason: "relations-changed"`
            // instead of status fields.
            if depends_on_changed {
                let all = store.list_notes(&note.workspace_id).await?;
                let ready_task_ids = compute_ready_task_ids(&all);
                publish_event(
                    &services.event_bus,
                    ready_tasks_changed_reason_event(
                        &note.workspace_id,
                        ready_task_ids,
                        &note.id,
                        "relations-changed",
                        &now_iso(),
                    ),
                )
                .await;
            }
            Ok(result)
        })
    }

    fn convert_task_blocks(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<TaskConvertBlocksResult>> {
        // Thin trait wrapper; `convert_task_blocks_op` owns the logic so the
        // auto-convert hook after every mutation can reuse it while carrying
        // the outer write's caller-agent context.
        let services = self.clone();
        Box::pin(async move {
            services
                .convert_task_blocks_op(workspace_id, note_id, caller_agent_id.as_ref())
                .await
        })
    }

    fn create_prerequisite(
        &self,
        workspace_id: WorkspaceId,
        dependent_note_id: NoteId,
        title: String,
        content: Option<String>,
        status: Option<String>,
        caller_agent_id: Option<AgentId>,
    ) -> BoxFuture<'_, Result<TaskCreatePrerequisiteResult>> {
        let services = self.clone();
        Box::pin(async move {
            let store = &services.store;
            // Verify the dependent note exists in this workspace.
            match store.get_note(&workspace_id, &dependent_note_id).await {
                Ok(_) => {}
                Err(Error::NotFound(_)) => {
                    return Err(Error::Internal(format!(
                        "Dependent note not found: {dependent_note_id}"
                    )))
                }
                Err(e) => return Err(e),
            }
            let status_word = status.as_deref().unwrap_or("not_started");
            let task_status = parse_task_status_strict(status_word)?;
            let child = services
                .create_child_task_note(
                    &workspace_id,
                    &dependent_note_id,
                    &title,
                    content.unwrap_or_default(),
                    task_status,
                    None,
                    None,
                    caller_agent_id.as_ref(),
                )
                .await?;
            // A fresh spec-child task can move the derived rollup (§6.5),
            // e.g. a completed workspace gaining a new open task. Non-spec
            // dependents never count into taskStats — skip the probe.
            if dependent_note_id.as_str() == "spec" {
                services
                    .maybe_emit_display_status_changed(&workspace_id)
                    .await;
            }
            Ok(TaskCreatePrerequisiteResult {
                ok: true,
                prerequisite_note_id: child.id,
                dependent_note_id,
                title: child.title,
            })
        })
    }

    fn assign_agent(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        agent_id: String,
        force: Option<bool>,
    ) -> BoxFuture<'_, Result<TaskAssignAgentResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            if !is_valid_agent_id(&agent_id) {
                return Err(Error::Internal(format!(
                    "Invalid agentId format: \"{agent_id}\". Agent IDs must be in format \"agent-{{uuid}}\" (e.g., \"agent-b0a8044a-5eac-4b52-8456-15d3b784decb\"). To create a new agent and assign it to this task, use create_agent with taskNoteId=\"{note_id}\" instead."
                )));
            }
            let mut note = match store.get_note(&workspace_id, &note_id).await {
                Ok(n) => n,
                Err(Error::NotFound(_)) => {
                    return Err(Error::Internal(format!("Note not found: {note_id}")))
                }
                Err(e) => return Err(e),
            };
            let mut task = match note.metadata.task.clone() {
                Some(t) => t,
                None => return Err(Error::Internal(format!("Note {note_id} is not a task"))),
            };
            let agent = AgentId::from(agent_id.as_str());
            let already_assigned = task.assigned_agent_ids.contains(&agent);
            let should_update_status = task.status == TaskStatus::NotStarted;
            if already_assigned && !should_update_status {
                return Ok(TaskAssignAgentResult {
                    ok: true,
                    note_id,
                    agent_id: agent,
                });
            }
            // Occupancy guard: assigning a NEW agent to a task that already
            // has a live assigned agent needs `force: true`; re-assigning an
            // already-assigned id stays idempotent-ok (handled above). Same
            // predicate as `agent_delegate_op`'s pre-gate: newest live
            // (loadable, not Deleted, not poisoned) assignee while the task
            // is still workable (status not complete/cancelled).
            if !already_assigned
                && force != Some(true)
                && !matches!(task.status, TaskStatus::Complete | TaskStatus::Cancelled)
            {
                if let Some(existing) = services
                    .scan_assigned_agents(&task.assigned_agent_ids)
                    .await?
                    .live_session
                {
                    return Err(Error::InvalidParams(format!(
                        "Task is already being worked by agent {} (\"{}\"). \
                         Use agent.sendToTask or agent.wakeOrCreate to reach the existing agent, \
                         or pass force: true to intentionally assign a second agent.",
                        existing.id, existing.name
                    )));
                }
            }
            let now = now_iso();
            let previous_status = task.status;
            if !already_assigned {
                task.assigned_agent_ids.push(agent.clone());
            }
            if should_update_status {
                apply_status_transition(&mut task, TaskStatus::InProgress, &now);
            }
            note.metadata.task = Some(task);
            note.updated_at = now.clone();
            store.update_note(&note).await?;
            // TS parity (`assignAgentToTask`): the assignment write routes
            // through `updateNote` (→ `note:updated`) and the not_started →
            // in_progress transition through `updateTaskStatus`
            // (→ `task:status-changed` + ready-tasks recompute), so
            // subscribers see the delegation live.
            publish_event(
                &bus,
                note_change_event(
                    &note.workspace_id,
                    &note.id,
                    &note.title,
                    NOTE_UPDATED,
                    "update",
                ),
            )
            .await;
            if should_update_status {
                publish_event(
                    &bus,
                    task_status_changed_event(
                        &note.workspace_id,
                        &note.id,
                        &note.title,
                        previous_status,
                        TaskStatus::InProgress,
                        &now,
                        None,
                    ),
                )
                .await;
                let all = store.list_notes(&note.workspace_id).await?;
                let ready_task_ids = compute_ready_task_ids(&all);
                publish_event(
                    &bus,
                    ready_tasks_changed_event(
                        &note.workspace_id,
                        ready_task_ids,
                        &note.id,
                        previous_status,
                        TaskStatus::InProgress,
                        &now,
                    ),
                )
                .await;
                // No dependent re-announce here: the not_started → in_progress
                // move never crosses the complete boundary, so dependents'
                // computed `unmetDependsOn` is unchanged (monorepo#1979).
                // The not_started → in_progress transition can move the
                // derived displayStatus rollup (§6.5).
                services
                    .maybe_emit_display_status_changed(&note.workspace_id)
                    .await;
            }
            Ok(TaskAssignAgentResult {
                ok: true,
                note_id,
                agent_id: agent,
            })
        })
    }

    fn remove_agent_from_all_tasks(
        &self,
        workspace_id: WorkspaceId,
        agent_id: AgentId,
    ) -> BoxFuture<'_, Result<TaskRemoveAgentFromAllTasksResult>> {
        let store = self.store.clone();
        Box::pin(async move {
            let notes = store.list_notes(&workspace_id).await?;
            let now = now_iso();
            let mut updated_count: u32 = 0;
            for mut note in notes {
                let Some(mut task) = note.metadata.task.clone() else {
                    continue;
                };
                if !task.assigned_agent_ids.contains(&agent_id) {
                    continue;
                }
                task.assigned_agent_ids.retain(|id| id != &agent_id);
                note.metadata.task = Some(task);
                note.updated_at = now.clone();
                store.update_note(&note).await?;
                updated_count += 1;
            }
            Ok(TaskRemoveAgentFromAllTasksResult {
                ok: true,
                updated_count,
            })
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn comment_add(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        search_context: String,
        comment_target: String,
        comment: String,
        kind: Option<String>,
        author: Option<String>,
        author_type: Option<String>,
        idempotency_key: Option<String>,
        comment_id: Option<String>,
    ) -> BoxFuture<'_, Result<CommentAddResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let services = self.clone();
        Box::pin(async move {
            let ws_scope = workspace_id.0.clone();
            let op_store = store.clone();
            let warn_note_id = note_id.clone();
            // Bounded diagnostics captured BEFORE the params move into the
            // idempotency closure: lengths + head/tail snippets (never the
            // full text) so a failed add is reconstructable from the log.
            let diag_ctx = bounded_needle_snippet(&search_context);
            let diag_tgt = bounded_needle_snippet(&comment_target);
            let diag_ctx_len = search_context.chars().count();
            let diag_tgt_len = comment_target.chars().count();
            // Emission lives inside the idempotency scope so a replayed add
            // (same idempotencyKey) returns the cached result without a second
            // `comment:added` (design note TB-0 §5).
            let result = with_idempotency(
                &store,
                &ws_scope,
                idempotency_key,
                "comment.add",
                move || async move {
                    let store = op_store;
                    if comment.trim().is_empty() {
                        return Err(Error::InvalidParams(
                            "Comment text is required and must be non-empty".to_string(),
                        ));
                    }
                    if search_context.trim().is_empty() {
                        return Err(Error::InvalidParams(
                            "searchContext is required and must be non-empty".to_string(),
                        ));
                    }
                    if comment_target.trim().is_empty() {
                        return Err(Error::InvalidParams(
                            "commentTarget is required and must be non-empty".to_string(),
                        ));
                    }
                    // Default `agent` keeps backward compatibility with
                    // agent/MCP callers that predate the param.
                    let author_type = match author_type.as_deref() {
                        None | Some("agent") => AuthorType::Agent,
                        Some("user") => AuthorType::User,
                        Some(other) => {
                            return Err(Error::InvalidParams(format!(
                                "Invalid 'authorType': {other}. Must be 'user' or 'agent'."
                            )))
                        }
                    };
                    // Client-supplied `commentId` (monorepo Round 14 root cause
                    // A): the FE inserts optimistic anchors under its own id, so
                    // honoring that id lets the daemon rewrite converge with the
                    // client instead of minting a second, never-reconciled id.
                    // Validated inside the idempotency scope so a replayed key
                    // still returns the cached result before these checks fire.
                    let client_supplied_id = comment_id.is_some();
                    // Canonical hyphenated form required (not just any
                    // `Uuid::parse_str`-accepted spelling): the phantom scrub
                    // in `note_ops` only recognizes canonical ids inside
                    // markers, so a looser form here would mint markers the
                    // reanchor pass can never classify or clean up.
                    let comment_id = match comment_id {
                        Some(supplied) => {
                            if !note_ops::is_canonical_uuid(&supplied) {
                                return Err(Error::InvalidParams(format!(
                                    "Invalid 'commentId': {supplied}. Must be a canonical hyphenated UUID."
                                )));
                            }
                            supplied
                        }
                        None => uuid::Uuid::new_v4().to_string(),
                    };
                    let mut note = fetch_note_peer(&store, &workspace_id, &note_id).await?;
                    // Self-heal phantom debris (Round 15): scrub UUID-format
                    // markers whose id has no live comment row before
                    // matching. The cleaned content persists only as part of
                    // the add's atomic note rewrite below — a failed add
                    // changes nothing (no separate rev bump).
                    let peers = store
                        .list_comments_in_workspace(&workspace_id, &note_id)
                        .await?;
                    note.content = note_ops::scrub_phantom_anchor_markers(
                        &note.content,
                        &live_comment_ids(&peers),
                    );
                    let (from, to, line) = note_ops::find_and_anchor_text(
                        &note.content,
                        &search_context,
                        &comment_target,
                    )?;
                    // The span may overlap other comments' ranges and thus
                    // contain their markers: the RAW span (markers intact, in
                    // place) is embedded back between the new pair, while the
                    // STORED text fields are stripped of all `<!--anchor:…-->`
                    // substrings so raw marker text never leaks into the row.
                    let anchored_span = note.content[from..to].to_string();
                    let anchored_text = note_ops::strip_anchor_marker_text(&anchored_span);
                    // Capture the surrounding context BEFORE inserting the
                    // anchor markers so the stored context reflects the
                    // original text (parity with `extractAnchoredText` in
                    // `markdown-anchor-recovery.ts`). This is Audit D M1: the
                    // saved context lets a later note edit re-anchor a
                    // partial-marker survivor without needing note versions.
                    // Markers are stripped from the FULL prefix/suffix before
                    // the window is taken: a marker adjacent to `from`/`to`
                    // would otherwise be clipped by the 50-char window and
                    // its raw fragment survive the strip (PR #541 review).
                    let clean_prefix = note_ops::strip_anchor_marker_text(&note.content[..from]);
                    let ctx_before = note_ops::context_before(&clean_prefix, clean_prefix.len());
                    let clean_suffix = note_ops::strip_anchor_marker_text(&note.content[to..]);
                    let ctx_after = note_ops::context_after(&clean_suffix, 0);
                    note.content = format!(
                        "{}<!--anchor:{id}:start-->{anchored}<!--anchor:{id}:end-->{}",
                        &note.content[..from],
                        &note.content[to..],
                        id = comment_id,
                        anchored = anchored_span,
                    );
                    note.updated_at = now_iso();
                    let now = now_iso();
                    let new_comment = Comment {
                        id: comment_id.clone(),
                        thread_id: comment_id.clone(),
                        note_id: Some(note_id.clone()),
                        kind: parse_comment_type(kind.as_deref()),
                        content: comment,
                        author: author.unwrap_or_else(|| {
                            match author_type {
                                AuthorType::User => "User",
                                AuthorType::Agent => "Agent",
                            }
                            .to_string()
                        }),
                        author_type,
                        status: CommentStatus::Open,
                        parent_id: None,
                        anchor: Some(CommentAnchor {
                            kind: CommentAnchorType::Range,
                            start_id: Some(comment_id.clone()),
                            end_id: Some(comment_id.clone()),
                            point_id: None,
                        }),
                        anchor_text: Some(anchored_text.clone()),
                        anchor_before: if ctx_before.is_empty() {
                            None
                        } else {
                            Some(ctx_before)
                        },
                        anchor_after: if ctx_after.is_empty() {
                            None
                        } else {
                            Some(ctx_after)
                        },
                        suggestion_original: None,
                        suggestion_proposed: None,
                        agent_id: None,
                        is_orphaned: None,
                        created_at: now.clone(),
                        updated_at: now,
                    };
                    // The anchor-marker note rewrite + comment INSERT commit
                    // atomically: a failure can never leave markers embedded
                    // with no comment row (monorepo#638). The returned rev is
                    // the authoritative post-rewrite value echoed to clients.
                    // Duplicate-id detection rides the INSERT's PK constraint
                    // inside that same transaction (no TOCTOU pre-check), so a
                    // colliding client-supplied `commentId` is InvalidParams
                    // even when two adds race.
                    let note_rev = match store.update_note_with_comment(&note, &new_comment).await {
                        Ok(rev) => rev,
                        Err(Error::InvalidInput(_)) if client_supplied_id => {
                            return Err(Error::InvalidParams(format!(
                                "Invalid 'commentId': {comment_id}. A comment with this id already exists."
                            )))
                        }
                        Err(e) => return Err(e),
                    };
                    services.invalidate_crdt_note(&note.workspace_id, &note.id);
                    services.schedule_line_attribution_recompute(
                        note.workspace_id.clone(),
                        note.id.clone(),
                    );
                    // `note:updated` fires because the add rewrote the note
                    // markdown; without it clients hold a stale rev and hit
                    // spurious conflicts on their next versioned write.
                    publish_event(
                        &bus,
                        note_change_event(
                            &workspace_id,
                            &note_id,
                            &note.title,
                            NOTE_UPDATED,
                            "update",
                        ),
                    )
                    .await;
                    publish_event(
                        &bus,
                        comment_added_event(&workspace_id, &note_id, &comment_id),
                    )
                    .await;
                    Ok(CommentAddResult {
                        success: true,
                        message: format!("Comment successfully anchored to \"{anchored_text}\""),
                        comment_id,
                        anchored: true,
                        note_rev,
                        location: CommentLocation {
                            line,
                            anchored_text,
                        },
                    })
                },
            )
            .await;
            if let Err(e) = &result {
                // `workspace_id` is essential: note ids are per-workspace (every
                // workspace has a `spec` note), so a context-not-found here can
                // mean the caller targeted the wrong workspace's same-id note
                // (the round-5 dogfood failure was exactly that).
                tracing::warn!(
                    workspace_id = %ws_scope,
                    note_id = %warn_note_id.as_str(),
                    error = %e,
                    search_context_len = diag_ctx_len,
                    search_context = %diag_ctx,
                    comment_target_len = diag_tgt_len,
                    comment_target = %diag_tgt,
                    "comment.add failed"
                );
            }
            result
        })
    }

    fn comment_list(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        since: Option<String>,
        author_type: Option<String>,
        status: Option<String>,
        include_comments: bool,
    ) -> BoxFuture<'_, Result<CommentListResult>> {
        let store = self.store.clone();
        Box::pin(async move {
            let since_dt = match &since {
                Some(s) => match parse_iso(s) {
                    Some(dt) => Some(dt),
                    None => {
                        return Err(Error::InvalidParams(format!(
                            "Invalid 'since' timestamp: {s}. Must be ISO 8601 format."
                        )))
                    }
                },
                None => None,
            };
            if let Some(at) = author_type.as_deref() {
                if at != "user" && at != "agent" {
                    return Err(Error::InvalidParams(format!(
                        "Invalid 'authorType': {at}. Must be 'user' or 'agent'."
                    )));
                }
            }
            if let Some(st) = status.as_deref() {
                if !["open", "resolved", "pending"].contains(&st) {
                    return Err(Error::InvalidParams(format!(
                        "Invalid 'status': {st}. Must be 'open', 'resolved', or 'pending'."
                    )));
                }
            }
            fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let comments = store.list_comments(&note_id).await?;

            // Group by thread id (roots carry thread_id == id).
            let mut order: Vec<String> = Vec::new();
            let mut groups: std::collections::HashMap<String, Vec<Comment>> =
                std::collections::HashMap::new();
            for c in comments {
                let tid = c.thread_id.clone();
                if !groups.contains_key(&tid) {
                    order.push(tid.clone());
                }
                groups.entry(tid).or_default().push(c);
            }

            let mut threads: Vec<CommentThreadSummary> = Vec::new();
            for tid in order {
                let mut group = groups.remove(&tid).unwrap_or_default();
                group.sort_by(|a, b| a.created_at.cmp(&b.created_at));
                let root = group
                    .iter()
                    .find(|c| c.parent_id.is_none())
                    .cloned()
                    .unwrap_or_else(|| group[0].clone());
                let latest = group
                    .iter()
                    .max_by(|a, b| a.updated_at.cmp(&b.updated_at))
                    .cloned()
                    .unwrap_or_else(|| group[0].clone());
                let thread_status = if group.iter().any(|c| c.status == CommentStatus::Open) {
                    "open"
                } else if group.iter().all(|c| c.status == CommentStatus::Resolved) {
                    "resolved"
                } else {
                    "pending"
                };
                let last_activity = group
                    .iter()
                    .map(|c| c.updated_at.clone())
                    .max()
                    .unwrap_or_else(|| root.updated_at.clone());
                let comment_wires = if include_comments {
                    Some(group.iter().map(CommentWire::from_comment).collect())
                } else {
                    None
                };
                threads.push(CommentThreadSummary {
                    thread_id: tid,
                    note_id: note_id.clone(),
                    targeted_text: root.anchor_text.clone(),
                    anchor_id: root.anchor.as_ref().and_then(derive_mark_id),
                    status: thread_status.to_string(),
                    created_at: root.created_at.clone(),
                    last_activity,
                    latest_comment_author: latest.author.clone(),
                    latest_comment_author_type: latest.author_type,
                    latest_comment_at: latest.updated_at.clone(),
                    comment_count: group.len(),
                    comments: comment_wires,
                });
            }

            if let Some(dt) = since_dt {
                threads.retain(|t| match parse_iso(&t.last_activity) {
                    Some(la) => la > dt,
                    None => false,
                });
            }
            if let Some(at) = author_type.as_deref() {
                threads.retain(|t| status_word_author(t.latest_comment_author_type) == at);
            }
            if let Some(st) = status.as_deref() {
                threads.retain(|t| t.status == st);
            }
            threads.sort_by(|a, b| b.last_activity.cmp(&a.last_activity));

            let total_comments = threads.iter().map(|t| t.comment_count).sum();
            Ok(CommentListResult {
                total_threads: threads.len(),
                total_comments,
                threads,
            })
        })
    }

    fn comment_get_thread(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        thread_id: Option<String>,
        comment_id: Option<String>,
    ) -> BoxFuture<'_, Result<CommentGetThreadResult>> {
        let store = self.store.clone();
        Box::pin(async move {
            if thread_id.is_none() && comment_id.is_none() {
                return Err(Error::InvalidParams(
                    "Either threadId or commentId must be provided".to_string(),
                ));
            }
            fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let all = store.list_comments(&note_id).await?;
            let target = match thread_id {
                Some(t) => t,
                None => {
                    let cid = comment_id.unwrap();
                    match all.iter().find(|c| c.id == cid) {
                        Some(c) => c.thread_id.clone(),
                        None => return Err(Error::Internal(format!("Comment not found: {cid}"))),
                    }
                }
            };
            let mut group: Vec<Comment> =
                all.into_iter().filter(|c| c.thread_id == target).collect();
            if group.is_empty() {
                return Err(Error::Internal(format!("Thread not found: {target}")));
            }
            group.sort_by(|a, b| a.created_at.cmp(&b.created_at));
            let root = group
                .iter()
                .find(|c| c.parent_id.is_none())
                .cloned()
                .unwrap_or_else(|| group[0].clone());
            let replies: Vec<CommentWire> = group
                .iter()
                .filter(|c| c.parent_id.is_some())
                .map(CommentWire::from_comment)
                .collect();
            let resolved = group.iter().all(|c| {
                matches!(
                    c.status,
                    CommentStatus::Resolved | CommentStatus::Accepted | CommentStatus::Rejected
                )
            });
            Ok(CommentGetThreadResult {
                thread_id: target,
                note_id,
                root_comment: CommentWire::from_comment(&root),
                replies,
                total_comments: group.len(),
                status: if resolved { "resolved" } else { "open" }.to_string(),
            })
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn comment_respond(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        thread_id: Option<String>,
        comment_id: Option<String>,
        comment: String,
        kind: Option<String>,
        author: Option<String>,
        author_type: Option<String>,
        suggestion_original: Option<String>,
        suggestion_proposed: Option<String>,
    ) -> BoxFuture<'_, Result<CommentRespondResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        Box::pin(async move {
            if thread_id.is_none() && comment_id.is_none() {
                return Err(Error::InvalidParams(
                    "Either threadId or commentId must be provided".to_string(),
                ));
            }
            if comment.trim().is_empty() {
                return Err(Error::InvalidParams(
                    "Comment text is required and must be non-empty".to_string(),
                ));
            }
            // Default `agent` keeps backward compatibility with
            // agent/MCP callers that predate the param (parity with
            // `comment.add`'s authorType validation).
            let author_type = match author_type.as_deref() {
                None | Some("agent") => AuthorType::Agent,
                Some("user") => AuthorType::User,
                Some(other) => {
                    return Err(Error::InvalidParams(format!(
                        "Invalid 'authorType': {other}. Must be 'user' or 'agent'."
                    )))
                }
            };
            let kind_parsed = parse_comment_type(kind.as_deref());
            if kind_parsed == CommentType::Suggestion
                && (suggestion_original.is_none() || suggestion_proposed.is_none())
            {
                return Err(Error::InvalidParams(
                    "For type='suggestion', both suggestionOriginal and suggestionProposed are required"
                        .to_string(),
                ));
            }
            fetch_note_peer(&store, &workspace_id, &note_id).await?;
            // Workspace-scoped so a caller-supplied `commentId` cannot match a
            // comment belonging to a same-`note_id` note in a different
            // workspace (e.g. the well-known `spec` id), which would let the
            // reply's `parent_id` chain into that other workspace.
            let all = store
                .list_comments_in_workspace(&workspace_id, &note_id)
                .await?;
            let (target, parent_from_id) = match thread_id {
                Some(t) => (t, None),
                None => {
                    let cid = comment_id.unwrap();
                    match all.iter().find(|c| c.id == cid).cloned() {
                        Some(c) => (c.thread_id.clone(), Some(c)),
                        None => return Err(Error::Internal(format!("Comment not found: {cid}"))),
                    }
                }
            };
            let mut group: Vec<Comment> = all
                .iter()
                .filter(|c| c.thread_id == target)
                .cloned()
                .collect();
            if group.is_empty() {
                return Err(Error::Internal(format!("Thread not found: {target}")));
            }
            // Newest first; the parent defaults to the most recent comment.
            group.sort_by(|a, b| b.created_at.cmp(&a.created_at));
            let parent = parent_from_id.unwrap_or_else(|| group[0].clone());
            let now = now_iso();
            let reply = Comment {
                id: uuid::Uuid::new_v4().to_string(),
                thread_id: target.clone(),
                note_id: Some(note_id.clone()),
                kind: kind_parsed,
                content: comment,
                author: author.unwrap_or_else(|| {
                    match author_type {
                        AuthorType::User => "User",
                        AuthorType::Agent => "Agent",
                    }
                    .to_string()
                }),
                author_type,
                status: CommentStatus::Open,
                parent_id: Some(parent.id.clone()),
                // Replies never anchor independently — they anchor via their
                // thread/parent (threadId/parentId), so no anchor/anchorText
                // is cloned from the parent (monorepo#729).
                anchor: None,
                anchor_text: None,
                anchor_before: None,
                anchor_after: None,
                suggestion_original: if kind_parsed == CommentType::Suggestion {
                    suggestion_original
                } else {
                    None
                },
                suggestion_proposed: if kind_parsed == CommentType::Suggestion {
                    suggestion_proposed
                } else {
                    None
                },
                agent_id: None,
                is_orphaned: None,
                created_at: now.clone(),
                updated_at: now,
            };
            store.insert_comment(&workspace_id, &reply).await?;
            // Reference `comment.respond` dispatches the same domain event as
            // `comment.add`; publish `comment:added` so the comment channel
            // pushes the new reply without a re-read (§6.5).
            publish_event(
                &bus,
                comment_added_event(&workspace_id, &note_id, &reply.id),
            )
            .await;
            Ok(CommentRespondResult {
                success: true,
                message: "Reply added successfully".to_string(),
                comment: CommentWire::from_comment(&reply),
                thread: CommentRespondThread {
                    thread_id: target,
                    total_comments: group.len() + 1,
                },
            })
        })
    }

    fn comment_delete(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        comment_id: String,
    ) -> BoxFuture<'_, Result<CommentDeleteResult>> {
        let store = self.store.clone();
        Box::pin(async move {
            match store.delete_comment(&workspace_id, &comment_id).await {
                Ok(()) => Ok(CommentDeleteResult {
                    success: true,
                    message: format!("Comment {comment_id} deleted from note {note_id}"),
                }),
                Err(Error::NotFound(_)) => {
                    Err(Error::Internal("Failed to delete comment".to_string()))
                }
                Err(e) => Err(e),
            }
        })
    }

    fn comment_resolve_thread(
        &self,
        workspace_id: WorkspaceId,
        note_id: NoteId,
        thread_id: Option<String>,
        comment_id: Option<String>,
        resolved: bool,
    ) -> BoxFuture<'_, Result<CommentResolveThreadResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        Box::pin(async move {
            if thread_id.is_none() && comment_id.is_none() {
                return Err(Error::InvalidParams(
                    "Either threadId or commentId must be provided".to_string(),
                ));
            }
            fetch_note_peer(&store, &workspace_id, &note_id).await?;
            let all = store.list_comments(&note_id).await?;
            let target = match thread_id {
                Some(t) => t,
                None => {
                    let cid = comment_id.unwrap();
                    match all.iter().find(|c| c.id == cid) {
                        Some(c) => c.thread_id.clone(),
                        None => return Err(Error::Internal(format!("Comment not found: {cid}"))),
                    }
                }
            };
            let count = all.iter().filter(|c| c.thread_id == target).count();
            if count == 0 {
                return Err(Error::Internal(format!("Thread not found: {target}")));
            }
            let new_status = if resolved {
                CommentStatus::Resolved
            } else {
                CommentStatus::Open
            };
            store
                .set_thread_status(&workspace_id, &target, new_status, &now_iso())
                .await?;
            publish_event(
                &bus,
                comment_resolved_event(&workspace_id, &note_id, &target, resolved),
            )
            .await;
            Ok(CommentResolveThreadResult {
                success: true,
                thread_id: target,
                note_id,
                resolved,
                status: if resolved { "resolved" } else { "open" }.to_string(),
                comment_count: count,
            })
        })
    }

    fn event_agent_activity(
        &self,
        workspace_id: WorkspaceId,
        agent_id: Option<String>,
        minutes_ago: Option<i64>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        Box::pin(async move {
            if let Some(agent_id) = agent_id {
                // `getAgentFiles(agentId, 100)`: file:changed by that agent.
                let events = store
                    .query_events(&EventQuery {
                        workspace_id: Some(workspace_id),
                        event_types: vec![intent_core::events::FILE_CHANGED.to_string()],
                        actor_type: Some(ActorType::Agent),
                        actor_id: Some(agent_id),
                        limit: Some(100),
                        ..Default::default()
                    })
                    .await?;
                let files: Vec<FileActivity> =
                    events.iter().map(event_ops::file_activity_named).collect();
                serde_json::to_value(files)
                    .map_err(|e| Error::Internal(format!("serialize agent files failed: {e}")))
            } else {
                // `getAgentActivity(minutesAgo || 30)`: agent events in-window.
                let minutes = minutes_ago.filter(|&m| m != 0).unwrap_or(30);
                let events = store
                    .query_events(&EventQuery {
                        workspace_id: Some(workspace_id),
                        actor_type: Some(ActorType::Agent),
                        since: Some(iso_minutes_ago(minutes)),
                        ..Default::default()
                    })
                    .await?;
                let activity = event_ops::aggregate_agent_activity(&events);
                serde_json::to_value(activity)
                    .map_err(|e| Error::Internal(format!("serialize agent activity failed: {e}")))
            }
        })
    }

    fn event_workspace_summary(
        &self,
        workspace_id: WorkspaceId,
        minutes_ago: Option<i64>,
    ) -> BoxFuture<'_, Result<WorkspaceEventSummary>> {
        let store = self.store.clone();
        Box::pin(async move {
            // TS `workspaceSummary(minutesAgo || 60)`.
            let minutes = minutes_ago.filter(|&m| m != 0).unwrap_or(60);
            let events = store
                .query_events(&EventQuery {
                    workspace_id: Some(workspace_id),
                    since: Some(iso_minutes_ago(minutes)),
                    ..Default::default()
                })
                .await?;
            Ok(event_ops::build_workspace_summary(&events, minutes))
        })
    }

    fn event_query(
        &self,
        workspace_id: WorkspaceId,
        params: EventQueryParams,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        Box::pin(async move {
            // Opt-in pagination (TA-2 / §5.5): the `{ items, nextToken }` envelope
            // is returned only when the caller engages pagination (`paginate` or a
            // `page_token`); otherwise the legacy bare array is preserved verbatim.
            let paginate = params.paginate.unwrap_or(false) || params.page_token.is_some();
            // Mirror `buildQueryFilters`: each option is applied only when
            // truthy (empty strings / 0 are skipped); `limit || 50`.
            let legacy_limit = params.limit.filter(|&l| l != 0).unwrap_or(50);
            let mut q = EventQuery {
                workspace_id: Some(workspace_id),
                limit: Some(legacy_limit),
                ..Default::default()
            };
            if let Some(t) = params.event_type.filter(|s| !s.is_empty()) {
                // Subscribe-parity glob (monorepo#1538), mirroring
                // `event_type_matches` in events/filter.rs: bare `*` means no
                // type filter; `prefix:*` compiles to a SQL prefix match;
                // anything else (including `note*` without a colon) stays an
                // exact match.
                if t == "*" {
                    // No type filter.
                } else if let Some(stem) = t.strip_suffix(":*") {
                    q.event_type_prefix = Some(format!("{stem}:"));
                } else {
                    q.event_types = vec![t];
                }
            }
            if let Some(at) = params.actor_type.filter(|s| !s.is_empty()) {
                // An unrecognized actorType matches nothing (TS equals filter).
                match serde_json::from_value::<ActorType>(serde_json::Value::String(at)) {
                    Ok(parsed) => q.actor_type = Some(parsed),
                    Err(_) => {
                        return Ok(if paginate {
                            serde_json::json!({ "items": [], "nextToken": serde_json::Value::Null })
                        } else {
                            serde_json::json!([])
                        })
                    }
                }
            }
            if let Some(aid) = params.actor_id.filter(|s| !s.is_empty()) {
                q.actor_id = Some(aid);
            }
            if let Some(p) = params.path.filter(|s| !s.is_empty()) {
                q.path_prefix = Some(p);
            }
            if let Some(m) = params.minutes_ago.filter(|&m| m != 0) {
                q.since = Some(iso_minutes_ago(m));
            }
            if !paginate {
                // Legacy bare array (store yields newest→oldest).
                let events = store.query_events(&q).await?;
                return serde_json::to_value(events)
                    .map_err(|e| Error::Internal(format!("serialize events failed: {e}")));
            }
            // Paginated: clamp the page size, page backward via OFFSET, and fetch
            // one extra row to decide whether an older page remains. The store
            // already orders newest→oldest, so the page is in contract order.
            let limit = pagination::clamp_limit(params.limit);
            let offset = pagination::parse_offset(params.page_token.as_deref());
            q.limit = Some((limit + 1) as i64);
            q.offset = Some(offset as i64);
            let mut events = store.query_events(&q).await?;
            let has_more = events.len() > limit;
            if has_more {
                events.truncate(limit);
            }
            let next_token = if has_more {
                serde_json::Value::String(pagination::offset_token(offset + limit))
            } else {
                serde_json::Value::Null
            };
            let items = serde_json::to_value(events)
                .map_err(|e| Error::Internal(format!("serialize events failed: {e}")))?;
            Ok(serde_json::json!({
                "items": items,
                "nextToken": next_token,
            }))
        })
    }

    fn event_subscribe(
        &self,
        workspace_id: WorkspaceId,
        subscriber_agent_id: Option<AgentId>,
        event_types: Vec<String>,
        exclude_self: Option<bool>,
        batch_window: Option<i64>,
    ) -> BoxFuture<'_, Result<EventSubscribeResult>> {
        Box::pin(async move {
            if event_types.is_empty() {
                return Err(Error::Internal(
                    "eventTypes is required. Specify category wildcards like \"file:*\", \"task:*\" or specific types like \"file:changed\".".to_string(),
                ));
            }
            if let Some(subscriber) = &subscriber_agent_id {
                // Agent callers may not subscribe to agent events — they use
                // ws.agent.watch instead (monorepo#1229).
                event_subscriptions::validate_agent_event_types(&event_types)?;
                // Fail closed on a phantom subscriber before registering
                // (monorepo#568 precedent for agent.watchCompletion).
                self.validate_event_subscriber(&workspace_id, subscriber)
                    .await?;
            }
            // Registers the subscription with a live bus delivery task
            // (matching + batching + subscriber wake, monorepo#937); bare `*`
            // expands to the category wildcards inside registration
            // (narrowed to the non-agent categories for agent subscribers).
            let (subscription_id, resolved) = self
                .register_event_subscription(
                    &workspace_id,
                    subscriber_agent_id,
                    &event_types,
                    exclude_self,
                    batch_window,
                )
                .await;
            Ok(EventSubscribeResult {
                subscription_id,
                event_types: resolved,
            })
        })
    }

    fn event_unsubscribe(
        &self,
        _workspace_id: WorkspaceId,
        subscription_id: String,
    ) -> BoxFuture<'_, Result<EventUnsubscribeResult>> {
        Box::pin(async move {
            if subscription_id.is_empty() {
                return Err(Error::Internal("subscriptionId is required".to_string()));
            }
            if !self.remove_event_subscription(&subscription_id).await {
                return Err(Error::Internal("Subscription not found".to_string()));
            }
            Ok(EventUnsubscribeResult {
                ok: true,
                subscription_id,
            })
        })
    }

    // ========================================================================
    // git.* surface (PROTOCOL §5.6). Worktree resolution + wire policy live in
    // `git_ops`; the git operations themselves are in `intent-git` (core-only).
    // ========================================================================

    fn git_status(
        &self,
        workspace_id: WorkspaceId,
        git_root_id: Option<WorkspaceGitRootId>,
    ) -> BoxFuture<'_, Result<intent_core::GitStatus>> {
        let svc = self.clone();
        Box::pin(async move {
            // Unknown workspace / remote / non-repo all return the empty status
            // (the TS `getStatus` fallbacks), never an error — but an unknown
            // `gitRootId` is `-32602` (monorepo#2053). The root resolves
            // BEFORE the remote early-return so the id is validated even on a
            // remote workspace; a valid id then degrades to the same empty
            // result the primary gets.
            let ws = match svc.store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(intent_git::status::empty_status()),
                Err(e) => return Err(e),
            };
            let Some(path) = svc.resolve_git_read_root(&ws, git_root_id.as_ref()).await? else {
                return Ok(intent_git::status::empty_status());
            };
            if ws.is_remote {
                return Ok(intent_git::status::empty_status());
            }
            if !path.join(".git").exists() {
                return Ok(intent_git::status::empty_status());
            }
            // The scan runs on the blocking pool under per-worktree
            // single-flight coalescing, so a slow scan on a big repo neither
            // stalls other RPCs (the runtime-saturation vector
            // `git_fetch_bounded` closes for `git.fetch`) nor gets re-walked
            // once per concurrent caller (monorepo#1648).
            let started = std::time::Instant::now();
            let status = svc.scan_git_status(&path).await;
            if let Ok(s) = &status {
                tracing::debug!(
                    workspace_id = %workspace_id.as_str(),
                    files = s.files.len(),
                    total_ms = started.elapsed().as_millis() as u64,
                    "git.status: working-tree status scan"
                );
            }
            status.map(|s| (*s).clone())
        })
    }

    fn git_root_list(&self, workspace_id: WorkspaceId) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        Box::pin(async move {
            // A missing workspace is `NotFound` (router → -32602); a workspace
            // with no registered roots is an empty list (monorepo#2053).
            let _ = store.get_workspace(&workspace_id).await?;
            let roots = store.list_workspace_git_roots(&workspace_id).await?;
            // The per-root live branch reads are git I/O — batched onto the
            // blocking pool so this list endpoint never performs per-item
            // git operations on the RPC task (AGENTS.md cost contract).
            let git_roots = tokio::task::spawn_blocking(move || git_root_wire_rows(&roots))
                .await
                .map_err(|e| Error::Internal(format!("gitRoot.list task failed: {e}")))?;
            Ok(serde_json::json!({ "gitRoots": git_roots }))
        })
    }

    fn git_root_register(
        &self,
        workspace_id: WorkspaceId,
        path: String,
        agent_id: AgentId,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        Box::pin(async move {
            let ws = svc.store.get_workspace(&workspace_id).await?;
            let trimmed = path.trim();
            if trimmed.is_empty() {
                return Err(Error::InvalidParams("path is required".to_string()));
            }
            // A relative path resolves against the workspace worktree — the
            // caller is an agent whose cwd is the worktree, and resolving
            // against the daemon's own cwd would be surprising and
            // daemon-launch-dependent. Absolute paths pass through untouched.
            let requested = if std::path::Path::new(trimmed).is_absolute() {
                PathBuf::from(trimmed)
            } else {
                let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                    Error::InvalidParams(format!(
                        "Relative path requires a workspace worktree to resolve against: \
                         {trimmed}"
                    ))
                })?;
                worktree.join(trimmed)
            };
            // Canonicalize next — registration is idempotent by canonical
            // path, and the path may live anywhere on the host (no worktree
            // containment, monorepo#2053).
            let canonical = tokio::fs::canonicalize(&requested)
                .await
                .map_err(|_| Error::InvalidParams(format!("Path does not exist: {trimmed}")))?;
            // A repo root has a `.git` entry — a directory for a normal
            // clone, a file for linked worktrees and submodule checkouts.
            if !canonical.join(".git").exists() {
                return Err(Error::InvalidParams(format!(
                    "Not a git repository root (no .git entry): {}",
                    canonical.display()
                )));
            }
            // The workspace's own primary root is tracked implicitly; only
            // secondary roots are registrable.
            if let Some(primary) = git_ops::worktree_path(&ws) {
                if let Ok(primary) = tokio::fs::canonicalize(&primary).await {
                    if primary == canonical {
                        return Err(Error::InvalidParams(
                            "The workspace's primary git root is tracked implicitly; \
                             only secondary roots can be registered"
                                .to_string(),
                        ));
                    }
                }
            }
            // Best-effort repo owner/name detection from the root's `origin`
            // remote — nullable, non-github remotes are left unset. The
            // remote read is git I/O (the root may live on a network/FUSE
            // mount), so it runs on the blocking pool — never on the RPC task.
            let origin_dir = canonical.clone();
            let (repo_owner, repo_name) =
                tokio::task::spawn_blocking(move || intent_git::remote::origin_url(&origin_dir))
                    .await
                    .ok()
                    .and_then(|r| r.ok())
                    .flatten()
                    .and_then(|url| Self::parse_github_owner_repo(&url))
                    .map_or((None, None), |(o, n)| (Some(o), Some(n)));
            // Stamp the root's HEAD at registration time (fail-soft:
            // unreadable HEAD ⇒ NULL; the store merge never overwrites an
            // existing value on re-registration).
            let registered_commit_sha = Self::read_git_root_head_sha(&canonical).await;
            let ts = now_iso();
            let root = intent_core::WorkspaceGitRoot {
                id: WorkspaceGitRootId::new(),
                workspace_id,
                path: canonical.to_string_lossy().into_owned(),
                source: intent_core::WorkspaceGitRootSource::Agent,
                repo_owner,
                repo_name,
                registered_by_agent_ids: vec![agent_id],
                registered_commit_sha,
                pr_number: None,
                pr_url: None,
                pr_status: None,
                pull_requests: None,
                created_at: ts.clone(),
                updated_at: ts,
            };
            let stored = svc.register_git_root(&root).await?;
            // The wire row's live branch read is git I/O — off the RPC task.
            let row = tokio::task::spawn_blocking(move || {
                git_root_wire_rows(std::slice::from_ref(&stored))
                    .pop()
                    .unwrap_or_default()
            })
            .await
            .map_err(|e| Error::Internal(format!("ws.git.registerRoot task failed: {e}")))?;
            Ok(row)
        })
    }

    fn git_root_unregister(
        &self,
        workspace_id: WorkspaceId,
        path: String,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        Box::pin(async move {
            let ws = svc.store.get_workspace(&workspace_id).await?;
            let trimmed = path.trim();
            if trimmed.is_empty() {
                return Err(Error::InvalidParams("path is required".to_string()));
            }
            // Mirror `git_root_register`: a relative path resolves against
            // the workspace worktree so the spelling that registered a root
            // also unregisters it. No worktree → the raw spelling stands.
            let requested = match git_ops::worktree_path(&ws) {
                Some(worktree) if !std::path::Path::new(trimmed).is_absolute() => {
                    worktree.join(trimmed)
                }
                _ => PathBuf::from(trimmed),
            };
            // Canonicalize when the directory still exists so the same
            // spelling that registered the root resolves; fall back to the
            // raw path for roots whose directory is already gone.
            let lookup = match tokio::fs::canonicalize(&requested).await {
                Ok(p) => p.to_string_lossy().into_owned(),
                Err(_) => trimmed.to_string(),
            };
            let root = svc
                .store
                .find_workspace_git_root_by_path(&workspace_id, &lookup)
                .await?
                .ok_or_else(|| {
                    Error::NotFound(format!("No git root registered for path: {lookup}"))
                })?;
            svc.unregister_git_root(&root.id).await?;
            Ok(serde_json::json!({
                "ok": true,
                "gitRootId": root.id.as_str(),
                "path": root.path,
            }))
        })
    }

    fn git_root_path(
        &self,
        workspace_id: WorkspaceId,
        git_root_id: WorkspaceGitRootId,
    ) -> BoxFuture<'_, Result<String>> {
        let svc = self.clone();
        Box::pin(async move {
            // Unlike the workspace-scoped reads, a missing workspace is an
            // error here (the caller explicitly named a root to resolve).
            let ws = svc.store.get_workspace(&workspace_id).await?;
            let path = svc.resolve_git_read_root(&ws, Some(&git_root_id)).await?;
            // `resolve_git_read_root` with `Some(id)` always yields a path.
            path.map(|p| p.to_string_lossy().into_owned())
                .ok_or_else(|| Error::InvalidParams(format!("Unknown git root: {git_root_id}")))
        })
    }

    fn git_get_config(&self, workspace_id: WorkspaceId) -> BoxFuture<'_, Result<String>> {
        let store = self.store.clone();
        Box::pin(async move {
            // `NotFound` if the workspace is absent (router maps to `-32602`).
            // Remote workspaces return an empty string. For local workspaces,
            // attempts to read `.git/config` (resolving linked-worktree pointers),
            // then walks parent directories to find a containing repo (nested-repo
            // parity with FE). Returns empty string if no config found.
            let ws = store.get_workspace(&workspace_id).await?;
            if ws.is_remote {
                return Ok(String::new());
            }
            let Some(path) = git_ops::worktree_path(&ws) else {
                return Ok(String::new());
            };
            // Read `.git/config` from the worktree's git directory. For linked
            // worktrees, `.git` is a file containing `gitdir: <path>`. Resolve the
            // pointer, then look for `commondir` (which points to the main repo's
            // `.git` if present). Fallback to parent-walk for nested repo parity.
            let git_path = path.join(".git");
            let config_path = if git_path.is_file() {
                // Linked worktree: read the gitdir pointer file.
                match tokio::fs::read_to_string(&git_path).await {
                    Ok(content) => {
                        // Strip `gitdir:` prefix (tolerant of varied whitespace), quotes, and trim.
                        let trimmed = content.trim();
                        let gitdir = trimmed
                            .strip_prefix("gitdir:")
                            .map(|s| s.trim())
                            .map(|s| {
                                // If quoted, strip the quotes.
                                if s.starts_with('"') && s.ends_with('"') && s.len() > 1 {
                                    &s[1..s.len() - 1]
                                } else {
                                    s
                                }
                            })
                            .unwrap_or(trimmed);
                        // Resolve relative gitdir paths against the worktree directory.
                        let gitdir_path = if std::path::Path::new(gitdir).is_relative() {
                            path.join(gitdir)
                        } else {
                            std::path::PathBuf::from(gitdir)
                        };
                        // Check for commondir (points to main repo .git for linked worktrees).
                        let commondir_path = gitdir_path.join("commondir");
                        if let Ok(commondir_content) =
                            tokio::fs::read_to_string(&commondir_path).await
                        {
                            let commondir = commondir_content.trim();
                            gitdir_path.join(commondir).join("config")
                        } else {
                            gitdir_path.join("config")
                        }
                    }
                    Err(_) => git_path.join("config"),
                }
            } else {
                git_path.join("config")
            };
            match tokio::fs::read_to_string(&config_path).await {
                Ok(content) => Ok(content),
                Err(_) => {
                    // If direct read fails, try parent directories (mirroring the FE
                    // `readGitConfig` fallback logic for nested repos). Limit the walk
                    // to prevent data exposure from climbing too far.
                    const MAX_PARENT_LEVELS: usize = 5;
                    let mut current = path.as_path();
                    for _ in 0..MAX_PARENT_LEVELS {
                        if let Some(parent) = current.parent() {
                            let parent_git_config = parent.join(".git").join("config");
                            if let Ok(content) = tokio::fs::read_to_string(&parent_git_config).await
                            {
                                return Ok(content);
                            }
                            current = parent;
                        } else {
                            break;
                        }
                    }
                    // No config found in the parent chain (or hit depth limit).
                    Ok(String::new())
                }
            }
        })
    }

    fn git_stage(
        &self,
        workspace_id: WorkspaceId,
        paths: serde_json::Value,
    ) -> BoxFuture<'_, Result<Vec<String>>> {
        let store = self.store.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            // Reject `.`/`*`/`--all` and parse first (TS `ws.git.stage` order).
            let path_list = git_ops::parse_stage_paths(&paths)?;
            // All stage failures surface as `-32603` (TS wraps the whole path in
            // INTERNAL_ERROR), so a missing workspace/worktree is `Internal` too.
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to stage files: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to stage files: workspace has no worktree".to_string())
            })?;
            intent_git::stage::stage(&worktree, &path_list)?;
            // Index moved → the cached scan describes the pre-stage tree
            // (monorepo#1648).
            status_cache.invalidate(&worktree);
            Ok(path_list)
        })
    }

    fn git_unstage(
        &self,
        workspace_id: WorkspaceId,
        paths: serde_json::Value,
    ) -> BoxFuture<'_, Result<Vec<String>>> {
        let store = self.store.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            // Same `.`/`*`/`--all` rejection + CSV/array parse as `git.stage`.
            let path_list = git_ops::parse_stage_paths(&paths)?;
            // Mirror `git.stage`: every failure surfaces as `-32603`, so a
            // missing workspace/worktree is `Internal` too.
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to unstage files: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to unstage files: workspace has no worktree".to_string())
            })?;
            // `reset_default` is a no-op on already-unstaged paths → idempotent.
            intent_git::stage::unstage(&worktree, &path_list)?;
            status_cache.invalidate(&worktree);
            Ok(path_list)
        })
    }

    fn git_discard(
        &self,
        workspace_id: WorkspaceId,
        paths: serde_json::Value,
    ) -> BoxFuture<'_, Result<Vec<String>>> {
        let store = self.store.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            // Discard-specific parser: `.`/`*`/`--all` rejected in BOTH the
            // top-level string and every array element (closes the array-form
            // bypass that would otherwise let `["*"]` / `["--all"]` devolve
            // into a silent no-op). Error messages are discard-oriented.
            let path_list = git_ops::parse_discard_paths(&paths)?;
            // Workspace / worktree resolution mirrors `git.stage`: a missing
            // workspace or unset worktree is `Internal` (→ `-32603`). The
            // subsequent `intent_git::stage::discard` call may still return
            // `Error::InvalidParams` (→ `-32602`) for unsafe pathspecs
            // (e.g. `..` traversal, absolute paths outside the worktree) —
            // those propagate unchanged.
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to discard changes: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to discard changes: workspace has no worktree".to_string())
            })?;
            // Tracked paths → checkout from index; untracked → delete from
            // disk. Idempotent on clean/missing paths (matches reference).
            intent_git::stage::discard(&worktree, &path_list)?;
            status_cache.invalidate(&worktree);
            Ok(path_list)
        })
    }

    fn git_stage_hunk(
        &self,
        workspace_id: WorkspaceId,
        file_path: String,
        hunk_patch: String,
    ) -> BoxFuture<'_, Result<()>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            // Wire policy mirrors `git.stage`: every failure surfaces as
            // `-32603`. A missing workspace/worktree stays `Internal`.
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to stage hunk: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to stage hunk: workspace has no worktree".to_string())
            })?;
            // Read the post-mutation status snapshot INSIDE the lock so a
            // concurrent write can't slip a different state into the event
            // that this call is supposed to describe. The event itself is
            // published outside the lock (payload is already a Value).
            let status_json = locks
                .with_lock(&worktree, || async {
                    intent_git::stage::stage_hunk(&worktree, &file_path, &hunk_patch)?;
                    // Tree/index moved under the lock → the cached scan is
                    // now the pre-mutation snapshot (monorepo#1648).
                    status_cache.invalidate(&worktree);
                    let status = intent_git::status::status(&worktree)
                        .unwrap_or_else(|_| intent_git::status::empty_status());
                    Ok::<_, Error>(serde_json::to_value(&status).unwrap_or(serde_json::Value::Null))
                })
                .await?;
            // Notify the FE bridge so the changes view refreshes without a
            // follow-up `git.status` read (parity with `git.stage`).
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(())
        })
    }

    fn git_unstage_hunk(
        &self,
        workspace_id: WorkspaceId,
        file_path: String,
        hunk_patch: String,
    ) -> BoxFuture<'_, Result<()>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to unstage hunk: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to unstage hunk: workspace has no worktree".to_string())
            })?;
            // Status snapshot inside the lock — see the matching note on
            // `git_stage_hunk` above.
            let status_json = locks
                .with_lock(&worktree, || async {
                    intent_git::stage::unstage_hunk(&worktree, &file_path, &hunk_patch)?;
                    status_cache.invalidate(&worktree);
                    let status = intent_git::status::status(&worktree)
                        .unwrap_or_else(|_| intent_git::status::empty_status());
                    Ok::<_, Error>(serde_json::to_value(&status).unwrap_or(serde_json::Value::Null))
                })
                .await?;
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(())
        })
    }

    fn git_push(
        &self,
        workspace_id: WorkspaceId,
        force: bool,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let registry = self.settings_registry.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to push: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to push: workspace has no worktree".to_string())
            })?;
            // Resolve the GitHub token outside the lock (bounded async lookups)
            // so the credential chain can fall back to it for HTTPS github.com
            // remotes (see `intent_git::auth`).
            let token = github_git_token(registry.as_deref(), &worktree).await;
            // Resolve the currently-checked-out branch (FE parity — `git push`
            // with no args pushes HEAD's upstream, which for our worktrees is
            // the current branch on `origin`). Resolve inside the lock so a
            // concurrent checkout/rename cannot change HEAD between the read
            // and the push. The status snapshot for the follow-up
            // `changes:git-status` event is taken inside the lock too, so a
            // concurrent write cannot slip a different state into the event
            // this call is supposed to describe (same pattern as
            // `git_stage_hunk`/`git_unstage_hunk`).
            let (outcome, status_json) = locks
                .with_lock(&worktree, || async {
                    let branch =
                        intent_git::status::current_branch_at(&worktree).ok_or_else(|| {
                            Error::Internal(
                                "Failed to push: no branch checked out (detached HEAD?)"
                                    .to_string(),
                            )
                        })?;
                    let outcome = intent_git::push::push(
                        &worktree,
                        "origin",
                        &branch,
                        force,
                        token.as_deref(),
                    )?;
                    // The remote-tracking ref advanced → the cached scan's
                    // ahead/behind is stale (monorepo#1648).
                    status_cache.invalidate(&worktree);
                    let status = intent_git::status::status(&worktree)
                        .unwrap_or_else(|_| intent_git::status::empty_status());
                    let status_json =
                        serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
                    Ok::<_, Error>((outcome, status_json))
                })
                .await?;
            publish_event(
                &bus,
                git_push_event(&ws.id, &outcome.branch, &outcome.pushed_sha, force),
            )
            .await;
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(serde_json::json!({
                "branch": outcome.branch,
                "pushedSha": outcome.pushed_sha,
            }))
        })
    }

    fn git_fetch(&self, workspace_id: WorkspaceId) -> BoxFuture<'_, Result<()>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let registry = self.settings_registry.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to fetch: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to fetch: workspace has no worktree".to_string())
            })?;
            // Token resolved outside the lock — see the matching note on
            // `git_push` above.
            let token = github_git_token(registry.as_deref(), &worktree).await;
            // Resolve HEAD's branch inside the lock so a concurrent
            // checkout/rename cannot change it between the read and the fetch.
            // The status snapshot is taken inside the lock too, so the
            // follow-up `changes:git-status` event reflects the tree state
            // this fetch produced rather than a state a concurrent writer
            // slipped in between the unlock and the read (same pattern as
            // `git_stage_hunk`/`git_unstage_hunk`).
            let status_json = locks
                .with_lock(&worktree, || async {
                    let branch =
                        intent_git::status::current_branch_at(&worktree).ok_or_else(|| {
                            Error::Internal(
                                "Failed to fetch: no branch checked out (detached HEAD?)"
                                    .to_string(),
                            )
                        })?;
                    intent_git::fetch::fetch(&worktree, "origin", &branch, token.as_deref())?;
                    // Remote-tracking refs moved → cached ahead/behind is
                    // stale (monorepo#1648).
                    status_cache.invalidate(&worktree);
                    let status = intent_git::status::status(&worktree)
                        .unwrap_or_else(|_| intent_git::status::empty_status());
                    Ok::<_, Error>(serde_json::to_value(&status).unwrap_or(serde_json::Value::Null))
                })
                .await?;
            // Refresh the FE change view without a follow-up `git.status` read.
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(())
        })
    }

    fn git_create_branch(
        &self,
        workspace_id: WorkspaceId,
        branch_name: String,
        checkout: bool,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            if branch_name.trim().is_empty() {
                return Err(Error::InvalidParams("branchName is required".to_string()));
            }
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to create branch: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to create branch: workspace has no worktree".to_string())
            })?;
            let name = branch_name.clone();
            locks
                .with_lock(&worktree, || async {
                    let created = intent_git::branches::create_branch(&worktree, &name, checkout);
                    if checkout {
                        // HEAD moved → the cached scan's branch (and diff
                        // against it) is stale (monorepo#1648).
                        status_cache.invalidate(&worktree);
                    }
                    created
                })
                .await?;
            publish_event(&bus, git_branch_event(&ws.id, "create", &branch_name, None)).await;
            if checkout {
                let status = intent_git::status::status(&worktree)
                    .unwrap_or_else(|_| intent_git::status::empty_status());
                let status_json = serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
                publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            }
            Ok(serde_json::json!({ "branch": branch_name }))
        })
    }

    fn git_checkout_branch(
        &self,
        workspace_id: WorkspaceId,
        branch_name: String,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            if branch_name.trim().is_empty() {
                return Err(Error::InvalidParams("branchName is required".to_string()));
            }
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to checkout branch: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to checkout branch: workspace has no worktree".to_string())
            })?;
            let name = branch_name.clone();
            locks
                .with_lock(&worktree, || async {
                    let out = intent_git::branches::checkout_branch(&worktree, &name);
                    // HEAD and the working tree both moved (monorepo#1648).
                    status_cache.invalidate(&worktree);
                    out
                })
                .await?;
            publish_event(
                &bus,
                git_branch_event(&ws.id, "checkout", &branch_name, None),
            )
            .await;
            let status = intent_git::status::status(&worktree)
                .unwrap_or_else(|_| intent_git::status::empty_status());
            let status_json = serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(serde_json::json!({ "branch": branch_name }))
        })
    }

    fn git_rename_branch(
        &self,
        workspace_id: WorkspaceId,
        old_branch_name: String,
        new_branch_name: String,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let locks = self.worktree_locks.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            if old_branch_name.trim().is_empty() {
                return Err(Error::InvalidParams(
                    "oldBranchName cannot be empty".to_string(),
                ));
            }
            let trimmed_new = new_branch_name.trim().to_string();
            if trimmed_new.is_empty() {
                return Err(Error::InvalidParams(
                    "newBranchName cannot be empty".to_string(),
                ));
            }
            // Same-name rename is a no-op (TS parity — reference returns `ok`
            // without touching git).
            if old_branch_name == trimmed_new {
                return Ok(serde_json::json!({
                    "oldBranch": old_branch_name,
                    "newBranch": trimmed_new,
                }));
            }
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to rename branch: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to rename branch: workspace has no worktree".to_string())
            })?;
            let old = old_branch_name.clone();
            let new = trimmed_new.clone();
            locks
                .with_lock(&worktree, || async {
                    let out = intent_git::branches::rename_branch(&worktree, &old, &new);
                    // Renaming the checked-out branch changes the cached
                    // scan's `branch` field (monorepo#1648).
                    status_cache.invalidate(&worktree);
                    out
                })
                .await?;
            publish_event(
                &bus,
                git_branch_event(&ws.id, "rename", &trimmed_new, Some(&old_branch_name)),
            )
            .await;
            // Renaming the currently-checked-out branch changes the
            // `git.status` `branch` field, so refresh the FE change view.
            let status = intent_git::status::status(&worktree)
                .unwrap_or_else(|_| intent_git::status::empty_status());
            let status_json = serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(serde_json::json!({
                "oldBranch": old_branch_name,
                "newBranch": trimmed_new,
            }))
        })
    }

    fn git_remove_lock_file(
        &self,
        workspace_id: WorkspaceId,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let locks = self.worktree_locks.clone();
        Box::pin(async move {
            // Unknown workspace → surface as `-32603`; a bare `NotFound` here
            // would be misleading given the FE's `Result` shape.
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to remove lock file: {e}")))?;
            // Remote workspaces skip the local fs operation (TS parity — the
            // reference short-circuits `{ removed: false }` here too).
            if ws.is_remote {
                return Ok(serde_json::json!({ "removed": false }));
            }
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to remove lock file: workspace has no worktree".to_string())
            })?;
            // Hold the per-worktree lock so a stale-lock cleanup cannot race
            // with a healthy in-flight write and delete its live `index.lock`.
            let removed = locks
                .with_lock(&worktree, || async {
                    intent_git::worktree::remove_index_lock(&worktree)
                })
                .await?;
            Ok(serde_json::json!({ "removed": removed }))
        })
    }

    fn git_get_branches(
        &self,
        repo_path: String,
        include_remote: bool,
    ) -> BoxFuture<'_, Result<intent_core::GitBranches>> {
        Box::pin(async move {
            // Path-based read used by the workspace-create flow *before* the
            // repo is registered: any existing local git repo is accepted
            // (matching the ungated TS handler); nonexistent / non-git paths
            // are `-32602` (PROTOCOL §5.6).
            git_ops::validate_repo_path(&repo_path)?;
            intent_git::branches::get_branches(std::path::Path::new(&repo_path), include_remote)
        })
    }

    fn git_branch_status(
        &self,
        repo_path: String,
        branch_name: String,
    ) -> BoxFuture<'_, Result<intent_core::GitBranchStatus>> {
        Box::pin(async move {
            // Same repo-path validation as `git_get_branches` (PROTOCOL §5.6).
            git_ops::validate_repo_path(&repo_path)?;
            intent_git::branches::branch_status(std::path::Path::new(&repo_path), &branch_name)
        })
    }

    fn git_pull(
        &self,
        repo_path: String,
        branch_name: String,
    ) -> BoxFuture<'_, Result<intent_core::GitPullResult>> {
        let store = self.store.clone();
        let event_bus = self.event_bus.clone();
        let registry = self.settings_registry.clone();
        let status_cache = self.git_status_invalidator();
        Box::pin(async move {
            // Path-based like `git_get_branches`: the workspace-create auto-pull
            // runs *before* the repo is registered, so any existing local git
            // repo is accepted; nonexistent / non-git paths are `-32602`
            // (PROTOCOL §5.6).
            git_ops::validate_repo_path(&repo_path)?;
            if branch_name.trim().is_empty() {
                return Err(Error::InvalidParams("branchName is required".to_string()));
            }
            // libgit2's pull is blocking and has no cancellation, so drive it
            // through `spawn_blocking` + a wall-clock timeout to keep a slow /
            // hung remote from wedging the async runtime (the vector behind the
            // FE `git.pull` and `host.status` timeouts). On timeout the caller
            // gets the structured `{ ok: false, error }` failure shape — never
            // a JSON-RPC error — matching the TS PULL_BRANCH contract.
            let pull_path = std::path::PathBuf::from(&repo_path);
            let pull_branch = branch_name.clone();
            let token =
                github_git_token(registry.as_deref(), std::path::Path::new(&repo_path)).await;
            let outcome = git_pull_bounded(
                move || intent_git::pull::pull_branch(&pull_path, &pull_branch, token.as_deref()),
                GIT_PULL_TIMEOUT,
            )
            .await?;
            // Merged commits moved HEAD and possibly the tree
            // (monorepo#1648). Invalidated regardless of whether a workspace
            // row resolves below (the cache is worktree-keyed) and regardless
            // of `outcome.ok`: a pull that fetched successfully and then
            // failed to rebase or pop its stash has already changed
            // `origin/<branch>` and possibly the worktree.
            status_cache.invalidate(std::path::Path::new(&repo_path));
            // Best-effort workspace resolution: `git.pull` is path-scoped (the
            // workspace-create auto-pull runs before the workspace row exists),
            // so we look up any workspace pointing at this worktree and skip
            // event emission when none is found. Failing to find a workspace
            // is a normal path — no error, no event.
            if outcome.ok {
                if let Some(ws) = find_workspace_by_worktree_path(&store, &repo_path).await {
                    // `git:pull` mirrors the reserved `GitOperationEvent` FE
                    // shape; `changes:git-status` feeds the FE bridge's
                    // `git:status-changed` relay so the UI refreshes without a
                    // follow-up `git.status` read.
                    publish_event(&event_bus, git_pull_event(&ws.id, &branch_name)).await;
                    let status = intent_git::status::status(std::path::Path::new(&repo_path))
                        .unwrap_or_else(|_| intent_git::status::empty_status());
                    let status_json =
                        serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
                    publish_event(&event_bus, changes_git_status_event(&ws.id, status_json)).await;
                }
            }
            Ok(outcome)
        })
    }

    fn git_clone(
        &self,
        url: String,
        parent_dir: String,
        target_name: Option<String>,
        request_id: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let bus = self.event_bus.clone();
        let registry = self.settings_registry.clone();
        Box::pin(async move {
            if url.trim().is_empty() {
                return Err(Error::InvalidParams("url is required".to_string()));
            }
            let target = clone_ops::resolve_target_path(&parent_dir, &url, target_name.as_deref())?;
            if clone_ops::target_exists(&target) {
                // Stays -32603 per the documented git.clone contract
                // (PROTOCOL §5.6); the §9.1 clone failure taxonomy (and its
                // `workspace.create clone failed …` message shape) is scoped
                // to the workspace.create orchestration.
                return Err(Error::Internal(format!(
                    "target already exists: {}",
                    target.display()
                )));
            }
            let request_id = request_id.unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
            let bus = bus.ok_or_else(|| {
                Error::Internal("event bus not wired; git.clone requires streaming".to_string())
            })?;
            // Resolve a GitHub token for private HTTPS github.com clones
            // (monorepo#825): SSH / non-GitHub URLs skip resolution entirely;
            // the value travels to the child via the environment only.
            // Resolution runs inside the spawned task so the ack below stays
            // prompt (§5.6) — with `tokenSource: auto` the bounded secrets /
            // `gh` lookups can take a few seconds.
            let spawn_request_id = request_id.clone();
            let spawn_target = target.clone();
            tokio::spawn(async move {
                let token = github_git_token_for_url(registry.as_deref(), &url).await;
                clone_ops::spawn_clone(clone_ops::CloneJob {
                    request_id: spawn_request_id,
                    workspace_id: None,
                    url,
                    target_path: spawn_target,
                    token,
                    bus,
                    progress: None,
                    // Standalone `git.clone` keeps its historical plain
                    // (non-recursive) clone.
                    recurse_submodules: false,
                });
            });
            Ok(serde_json::json!({
                "requestId": request_id,
                "targetPath": target.to_string_lossy(),
            }))
        })
    }

    fn repo_list(&self) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let boot_root = self.workspaces_root.clone();
        let worktrees_location = self.configured_worktrees_location();
        Box::pin(async move {
            // Return the known repos immediately — don't block on the sync.
            let repos = store.list_known_repos().await?;
            // One-time background sync: register repos from existing workspaces
            // so pre-existing workspaces (created before this feature) get
            // picked up, and sweep out workspace-owned checkouts
            // (intent-hq/monorepo#2227). Spawned so it never blocks/fails the
            // response, and guarded to run at most once per process
            // (TS `repoRegistrySynced`).
            if REPO_REGISTRY_SYNCED
                .compare_exchange(
                    false,
                    true,
                    std::sync::atomic::Ordering::SeqCst,
                    std::sync::atomic::Ordering::SeqCst,
                )
                .is_ok()
            {
                let store = store.clone();
                tokio::spawn(async move {
                    // Same root set as the teardown sweeps: the boot root plus
                    // the currently configured `workspace.worktreesLocation`
                    // (workspaces provisioned there live there).
                    let mut roots = vec![boot_root.unwrap_or_else(default_workspaces_root)];
                    if let Some(location) = worktrees_location.filter(|l| !roots.contains(l)) {
                        roots.push(location);
                    }
                    if let Err(e) = sync_repos_from_workspaces(&store, &roots).await {
                        tracing::warn!(error = %e, "failed to sync workspace repos to registry");
                    }
                });
            }
            Ok(serde_json::json!({ "repos": repos }))
        })
    }

    fn repo_remove(&self, path: String) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        Box::pin(async move {
            let removed = store.remove_known_repo(&path).await?;
            Ok(serde_json::json!({ "removed": removed }))
        })
    }

    fn repo_warm_cache(&self, github_url: String) -> BoxFuture<'_, Result<serde_json::Value>> {
        let registry = self.settings_registry.clone();
        let warm_in_flight = self.warm_in_flight.clone();
        let workspaces_root = self.workspaces_root.clone();
        let worktrees_location = settings::worktrees_location(&self.effective_settings());
        // Same startup-pin precedence as `workspace.create`, so the warm
        // targets exactly the cache a subsequent create will hydrate from.
        let workspaces_root_pinned = self
            .settings_registry
            .as_deref()
            .and_then(|r| r.origin("workspaces.root"))
            == Some(SettingOrigin::Flag);
        Box::pin(async move {
            let url = github_url.trim().to_string();
            let Some((owner, repo)) = clone_ops::parse_owner_repo(&url) else {
                return Err(Error::InvalidParams(format!(
                    "githubUrl carries no owner/repo pair: {url}"
                )));
            };
            // Reject segments the cache ensure would refuse anyway (same
            // rules as repo_cache's validate_segment: path escapes, git
            // option lookalikes) BEFORE claiming the single-flight slot, so
            // a malformed URL can never block valid warms.
            for (what, value) in [("owner", owner.as_str()), ("repo", repo.as_str())] {
                let bad = value.is_empty()
                    || value == "."
                    || value == ".."
                    || value.starts_with('-')
                    || value.contains('/')
                    || value.contains('\\')
                    || value.contains('\0');
                if bad {
                    return Err(Error::InvalidParams(format!(
                        "githubUrl carries an invalid {what} segment: {value:?}"
                    )));
                }
            }
            let cache_root = resolve_workspaces_parent(
                workspaces_root,
                workspaces_root_pinned,
                &worktrees_location,
            )?
            .join(".repo-cache");
            // RAII clear for the single-flight slot: `Drop` runs even when
            // the detached task panics mid-ensure, so the flag can never
            // leak into a permanently-busy state. Poisoned locks recover via
            // `into_inner` — the guarded Option is trivially valid — so a
            // panic while the tiny critical section is held cannot brick the
            // method either.
            struct WarmSlotClear(Arc<Mutex<Option<(String, String)>>>);
            impl Drop for WarmSlotClear {
                fn drop(&mut self) {
                    *self
                        .0
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
                }
            }
            // Global single-flight: claim the slot or reject immediately with
            // the busy error naming the warm already in flight (never queue).
            {
                let mut slot = warm_in_flight
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                if let Some((o, r)) = slot.as_ref() {
                    return Err(Error::WarmInFlight {
                        owner: o.clone(),
                        repo: r.clone(),
                    });
                }
                *slot = Some((owner.clone(), repo.clone()));
            }
            let clear_on_drop = WarmSlotClear(warm_in_flight);
            // Detached background warm: token resolution (bounded secrets /
            // `gh` lookups) and the cache ensure both run off the RPC path.
            // Deliberately silent — no `git:clone:*` frames, no events; a
            // concurrent `workspace.create` for the same repo simply
            // serializes behind this ensure on the per-repo cache lock.
            let task_owner = owner.clone();
            let task_repo = repo.clone();
            tokio::spawn(async move {
                let _clear_on_drop = clear_on_drop;
                let token = github_git_token_for_url(registry.as_deref(), &url).await;
                let result = intent_git::repo_cache::ensure_cached_repo(
                    &cache_root,
                    &url,
                    &task_owner,
                    &task_repo,
                    token.as_deref(),
                )
                .await;
                match result {
                    Ok(path) => tracing::info!(
                        owner = %task_owner,
                        repo = %task_repo,
                        path = %path.display(),
                        "opportunistic repo cache warm completed"
                    ),
                    Err(e) => tracing::warn!(
                        owner = %task_owner,
                        repo = %task_repo,
                        error = %e,
                        "opportunistic repo cache warm failed"
                    ),
                }
            });
            Ok(serde_json::json!({ "started": true, "owner": owner, "repo": repo }))
        })
    }

    fn git_commit(
        &self,
        workspace_id: WorkspaceId,
        message: String,
        idempotency_key: Option<String>,
    ) -> BoxFuture<'_, Result<intent_core::GitCommitResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let this = self.clone();
        Box::pin(async move {
            // TS `ws.git.commit` gates on auto-commit (no userRequested
            // bypass), resolved per-workspace (override → global fallback).
            let auto_commit_enabled = this.effective_auto_commit(&workspace_id).await;
            let ws_scope = workspace_id.0.clone();
            let op_store = store.clone();
            let event_bus = bus.clone();
            let event_message = message.clone();
            let status_cache = this.git_status_invalidator();
            with_idempotency(
                &store,
                &ws_scope,
                idempotency_key,
                "git.commit",
                move || async move {
                    let store = op_store;
                    git_ops::assert_agent_commit_allowed(auto_commit_enabled, false)?;
                    // All commit failures surface as `-32603` (the TS handler wraps the
                    // whole path in INTERNAL_ERROR), so a missing workspace is `Internal`.
                    let ws = store
                        .get_workspace(&workspace_id)
                        .await
                        .map_err(|e| Error::Internal(format!("Failed to commit: {e}")))?;
                    let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                        Error::Internal("Failed to commit: workspace has no worktree".to_string())
                    })?;
                    let outcome = intent_git::commit::commit(&worktree, &message)?;
                    // Staged content became a commit → the cached scan still
                    // lists it as pending (monorepo#1648).
                    status_cache.invalidate(&worktree);
                    // Emissions live inside the idempotency scope so a replayed
                    // commit (same idempotencyKey) returns the cached result
                    // without re-firing events (parity with `workspace:created`
                    // §6.5). `git:commit` mirrors the reserved
                    // `GitOperationEvent` FE shape; `changes:git-status` feeds
                    // the FE bridge's `git:status-changed` relay so the UI
                    // refreshes without a follow-up `git.status` read.
                    publish_event(
                        &event_bus,
                        git_commit_event(&ws.id, &outcome.hash, &event_message, &outcome.files),
                    )
                    .await;
                    let status = intent_git::status::status(&worktree)
                        .unwrap_or_else(|_| intent_git::status::empty_status());
                    let status_json =
                        serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
                    publish_event(&event_bus, changes_git_status_event(&ws.id, status_json)).await;
                    Ok(intent_core::GitCommitResult {
                        hash: outcome.hash,
                        files: outcome.files,
                    })
                },
            )
            .await
        })
    }

    fn git_agent_commit(
        &self,
        workspace_id: WorkspaceId,
        message: String,
        agent_id: Option<AgentId>,
        linked_note_id: Option<NoteId>,
        files: Option<Vec<String>>,
        user_requested: bool,
    ) -> BoxFuture<'_, Result<intent_core::GitAgentCommitResult>> {
        let store = self.store.clone();
        let bus = self.event_bus.clone();
        let this = self.clone();
        Box::pin(async move {
            // userRequested bypasses the auto-commit gate (TS parity); the
            // gate reads the per-workspace resolution (override → global).
            let auto_commit_enabled = this.effective_auto_commit(&workspace_id).await;
            git_ops::assert_agent_commit_allowed(auto_commit_enabled, user_requested)?;
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|e| Error::Internal(format!("Failed to commit: {e}")))?;
            let worktree = git_ops::worktree_path(&ws).ok_or_else(|| {
                Error::Internal("Failed to commit: workspace has no worktree".to_string())
            })?;
            // Commit-set selection (TS parity, monorepo#939): an explicit
            // `files` list is committed as-is; without one, a `userRequested`
            // checkpoint commits only the already-staged paths (plain
            // `git commit` semantics — a user checkpoint must not sweep up
            // other agents' worktree changes), while an agent-initiated commit
            // commits only the paths the file-tracking attribution pipeline
            // credits to the committing agent (`tracked_changes` rows at stage
            // unstaged/staged), intersected with the actual worktree changes so
            // a stale attribution row never resurrects a committed/reverted
            // file. Without an `agent_id` attribution is impossible, so the
            // commit is refused rather than sweeping the whole worktree.
            let (to_commit, needs_stage, attribution_filtered) = match files {
                Some(f) if !f.is_empty() => {
                    git_ops::reject_submodule_internal_files(&worktree, &f)?;
                    (f, true, false)
                }
                _ if user_requested => (intent_git::commit::staged_paths(&worktree)?, false, false),
                _ => {
                    let Some(agent) = agent_id.as_ref() else {
                        return Err(Error::Internal(
                            "Agent-initiated commit without an agentId cannot be attributed: \
                             pass an explicit `files` list"
                                .to_string(),
                        ));
                    };
                    let attributed: HashSet<String> = store
                        .list_tracked_changes(&workspace_id)
                        .await?
                        .into_iter()
                        .filter(|r| {
                            matches!(r.stage.as_str(), "unstaged" | "staged")
                                && r.agent_id.as_deref() == Some(agent.as_str())
                        })
                        .map(|r| crate::file_tracking::normalize_path(&r.path))
                        .collect();
                    let changed = intent_git::commit::all_changed_paths(&worktree)?;
                    let filtered: Vec<String> = changed
                        .iter()
                        .filter(|p| attributed.contains(&crate::file_tracking::normalize_path(p)))
                        .cloned()
                        .collect();
                    // Drop submodule-internal paths before the emptiness
                    // check (monorepo#1714 follow-up): auto-commit must never
                    // flatten a submodule's gitlink into the superproject.
                    let (filtered, dropped_by_submodule) =
                        git_ops::drop_submodule_internal_paths(&worktree, filtered);
                    for (submodule, dropped) in &dropped_by_submodule {
                        tracing::debug!(
                            workspace = %workspace_id.0,
                            agent = %agent.as_str(),
                            submodule = %submodule,
                            dropped,
                            "agentCommit: dropped submodule-internal paths from \
                             attribution-filtered commit set"
                        );
                    }
                    if filtered.is_empty() && !changed.is_empty() {
                        // Diagnosable skip (monorepo#939 trade-off): agent
                        // work not visible to the attribution pipeline (e.g.
                        // terminal/shell edits) is no longer swept — surface
                        // it at debug so lost auto-commits can be traced
                        // without re-firing a warn on every idle while the
                        // worktree stays dirty.
                        tracing::debug!(
                            workspace = %workspace_id.0,
                            agent = %agent.as_str(),
                            dirty = changed.len(),
                            "agentCommit: worktree is dirty but no changes are \
                             attributed to this agent; nothing will be committed"
                        );
                    }
                    (filtered, true, true)
                }
            };
            if to_commit.is_empty() {
                return Err(Error::Internal(if user_requested {
                    "No staged changes found to commit".to_string()
                } else {
                    "No uncommitted changes found for this agent".to_string()
                }));
            }
            // With an explicit commit set (named `files` or the attribution
            // filter), commit exactly those paths (`git commit -- <paths>`
            // semantics) so paths another actor pre-staged are never swept
            // into this commit. The `userRequested` staged-only checkpoint
            // commits the index as-is.
            let outcome = if needs_stage {
                intent_git::commit::commit_paths_with_trailers(
                    &worktree,
                    &message,
                    agent_id.as_ref().map(AgentId::as_str),
                    linked_note_id.as_ref().map(NoteId::as_str),
                    &to_commit,
                )?
            } else {
                intent_git::commit::commit_with_trailers(
                    &worktree,
                    &message,
                    agent_id.as_ref().map(AgentId::as_str),
                    linked_note_id.as_ref().map(NoteId::as_str),
                )?
            };
            // Staged content became a commit → the cached scan still lists it
            // as pending (monorepo#1648).
            this.git_status_cache.invalidate(&worktree);
            if attribution_filtered {
                // Mirror `ac_commit`: move the committed paths' attribution
                // rows (staged/unstaged → committed) so the audit trail stays
                // consistent with the git stage. Best-effort, but loud — a
                // stuck row makes the next filtered commit resurrect the path.
                for path in &outcome.files {
                    let key = crate::file_tracking::normalize_path(path);
                    for from in ["staged", "unstaged"] {
                        if let Err(e) = store
                            .set_tracked_change_stage(&workspace_id, &key, from, "committed")
                            .await
                        {
                            tracing::warn!(
                                path = %key,
                                error = %e,
                                "agentCommit: failed to advance attribution row to committed"
                            );
                        }
                    }
                }
            }
            // Report the commit's actual delta (`outcome.files`), not the
            // requested set — with a pathspec-limited commit they match, and
            // for an explicit `files` list the delta is the truth (a named
            // but unchanged path is not part of the commit).
            let file_count = outcome.files.len() as i64;
            // `git:commit` mirrors the reserved `GitOperationEvent` FE shape;
            // `changes:git-status` feeds the FE bridge's `git:status-changed`
            // relay so the UI refreshes without a follow-up `git.status` read.
            publish_event(
                &bus,
                git_commit_event(&ws.id, &outcome.hash, &message, &outcome.files),
            )
            .await;
            let status = intent_git::status::status(&worktree)
                .unwrap_or_else(|_| intent_git::status::empty_status());
            let status_json = serde_json::to_value(&status).unwrap_or(serde_json::Value::Null);
            publish_event(&bus, changes_git_status_event(&ws.id, status_json)).await;
            Ok(intent_core::GitAgentCommitResult {
                hash: outcome.hash,
                files: outcome.files,
                file_count,
            })
        })
    }

    fn git_check_merge_conflicts(
        &self,
        workspace_id: WorkspaceId,
        target_branch: Option<String>,
    ) -> BoxFuture<'_, Result<intent_core::GitMergeConflicts>> {
        let store = self.store.clone();
        Box::pin(async move {
            // TS throws 'Could not find workspace git info' when the workspace or
            // its worktree can't be resolved.
            let ws = store
                .get_workspace(&workspace_id)
                .await
                .map_err(|_| Error::Internal("Could not find workspace git info".to_string()))?;
            let worktree = git_ops::worktree_path(&ws)
                .ok_or_else(|| Error::Internal("Could not find workspace git info".to_string()))?;

            let current_branch = intent_git::conflicts::current_branch(&worktree)?;
            if current_branch.is_empty() {
                return Err(Error::Internal(
                    "Failed to get current branch: No branch checked out (detached HEAD?)"
                        .to_string(),
                ));
            }

            let target = match target_branch {
                Some(t) => t,
                None => intent_git::conflicts::detect_default_branch(&worktree)?.ok_or_else(
                    || {
                        Error::Internal(
                            "Could not determine target branch. Please specify a targetBranch parameter."
                                .to_string(),
                        )
                    },
                )?,
            };

            // Same branch can't conflict with itself (TS short-circuit).
            if current_branch == target {
                return Ok(intent_core::GitMergeConflicts {
                    has_conflicts: false,
                    conflicted_files: Vec::new(),
                    cannot_determine: None,
                    target_branch: target,
                    current_branch,
                });
            }

            let mc =
                intent_git::conflicts::detect_merge_conflicts(&worktree, &current_branch, &target)?;
            Ok(intent_core::GitMergeConflicts {
                has_conflicts: mc.has_conflicts,
                conflicted_files: mc.conflicted_files,
                cannot_determine: if mc.cannot_determine {
                    Some(true)
                } else {
                    None
                },
                target_branch: target,
                current_branch,
            })
        })
    }

    fn git_changes(
        &self,
        workspace_id: WorkspaceId,
        git_root_id: Option<WorkspaceGitRootId>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        Box::pin(async move {
            // Same empty fallbacks as `git_status` (unknown/remote/non-repo →
            // empty list), but projecting only the working-tree file list.
            let empty = serde_json::json!([]);
            let ws = match svc.store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(empty),
                Err(e) => return Err(e),
            };
            // `gitRootId` is validated before the remote early-return (same
            // policy as `git_status`).
            let Some(path) = svc.resolve_git_read_root(&ws, git_root_id.as_ref()).await? else {
                return Ok(empty);
            };
            if ws.is_remote {
                return Ok(empty);
            }
            if !path.join(".git").exists() {
                return Ok(empty);
            }
            // The same working-tree scan `git.status` pays, so it goes through
            // the shared per-worktree single-flight (monorepo#1648): a burst
            // mixing `git.changes` with `git.status` walks the tree once.
            let status = svc.scan_git_status(&path).await?;
            Ok(serde_json::to_value(&status.files).unwrap_or(empty))
        })
    }

    fn git_diffs(
        &self,
        workspace_id: WorkspaceId,
        paths: Option<Vec<String>>,
        staged: bool,
        commit_hash: Option<String>,
        git_root_id: Option<WorkspaceGitRootId>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        let store = self.store.clone();
        let inflight = Arc::clone(&self.git_diffs_inflight);
        let slow_warns = Arc::clone(&self.git_diffs_slow_warns);
        let walk_probe = self.git_diffs_walk_probe.clone();
        Box::pin(async move {
            let empty = serde_json::json!([]);
            let ws = match store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(empty),
                Err(e) => return Err(e),
            };
            // `gitRootId` is validated before the remote early-return (same
            // policy as `git_status`).
            let Some(worktree) = svc.resolve_git_read_root(&ws, git_root_id.as_ref()).await? else {
                return Ok(empty);
            };
            if ws.is_remote {
                return Ok(empty);
            }
            if !worktree.join(".git").exists() {
                return Ok(empty);
            }
            // Defense-in-depth: absolute `paths` entries under the worktree
            // root are stripped to their worktree-relative form so a client
            // sending absolute paths still narrows the walk (entries outside
            // the root pass through verbatim and match nothing, as before).
            // This runs BEFORE the single-flight key is computed so
            // equivalent absolute/relative requests coalesce.
            // Sorting + deduping makes the identity order-insensitive, so
            // clients naming the same path set in a different order (or with
            // duplicates) still coalesce; `build_diffs` matches pathspecs as
            // a set, so the walk itself is unaffected.
            let paths = paths.map(|p| {
                let mut p = git_ops::normalize_diff_paths(&worktree, p);
                p.sort();
                p.dedup();
                p
            });
            // Concurrent calls with an identical request identity coalesce
            // onto one walk (single-flight). `Some([])` behaves exactly like
            // `None` in `build_diffs`, so both normalize onto the same key.
            let paths = paths.filter(|p| !p.is_empty());
            let key: git_diff_singleflight::DiffKey = (
                workspace_id.clone(),
                paths.clone(),
                staged,
                commit_hash.clone(),
                git_root_id.clone(),
            );
            loop {
                match inflight.join(&key) {
                    git_diff_singleflight::Join::Leader(flight) => {
                        // Full worktree hunk diffs can run for many seconds of
                        // pure libgit2 CPU. Never do that on a Tokio worker: it
                        // holds a bulk permit and can freeze the whole runtime
                        // so host.status never runs (seen as bulk permit held
                        // 5-40s with "nothing else" making progress).
                        let started = std::time::Instant::now();
                        let path_count = paths.as_ref().map(|p| p.len()).unwrap_or(0);
                        let walk_worktree = worktree.clone();
                        let walk_paths = paths.clone();
                        let walk_commit = commit_hash.clone();
                        let probe = walk_probe.clone();
                        let result = tokio::task::spawn_blocking(move || {
                            if let Some(probe) = &probe {
                                probe();
                            }
                            git_ops::build_diffs(
                                &walk_worktree,
                                walk_paths.as_deref(),
                                staged,
                                walk_commit.as_deref(),
                            )
                        })
                        .await
                        .map_err(|e| Error::Internal(format!("git.diffs task failed: {e}")))?;
                        let elapsed = started.elapsed();
                        if elapsed.as_millis() >= 250 {
                            // At most one WARN per workspace per 60s; further
                            // slow walks within the window drop to DEBUG so a
                            // busy workspace cannot flood stderr.
                            if slow_warns.should_warn(&workspace_id) {
                                tracing::warn!(
                                    workspace_id = %workspace_id.as_str(),
                                    total_ms = elapsed.as_millis() as u64,
                                    staged,
                                    path_count,
                                    "git.diffs: slow worktree hunk walk (offloaded to blocking pool)"
                                );
                            } else {
                                tracing::debug!(
                                    workspace_id = %workspace_id.as_str(),
                                    total_ms = elapsed.as_millis() as u64,
                                    staged,
                                    path_count,
                                    "git.diffs: slow worktree hunk walk (WARN rate-limited; offloaded to blocking pool)"
                                );
                            }
                        }
                        return match result {
                            Ok(value) => {
                                flight.finish(Ok(Arc::new(value.clone())));
                                Ok(value)
                            }
                            Err(e) => {
                                // Publish the inner message: every walk error
                                // is `Error::Internal` (map_git_err), and the
                                // follower re-wraps as `Error::Internal`, so
                                // coalesced callers observe the same variant
                                // and message (no double "internal error:"
                                // prefix).
                                flight.finish(Err(match &e {
                                    Error::Internal(msg) => msg.clone(),
                                    other => other.to_string(),
                                }));
                                Err(e)
                            }
                        };
                    }
                    git_diff_singleflight::Join::Follower(mut rx) => {
                        tracing::debug!(
                            workspace_id = %workspace_id.as_str(),
                            staged,
                            "git.diffs: coalesced into identical in-flight walk"
                        );
                        match rx.wait_for(|slot| slot.is_some()).await {
                            Ok(slot) => {
                                return match slot.clone().expect("wait_for guarantees Some") {
                                    Ok(shared) => Ok((*shared).clone()),
                                    Err(msg) => Err(Error::Internal(msg)),
                                };
                            }
                            // The leader vanished without publishing
                            // (cancelled RPC / panicked walk): retry — the
                            // next join elects a new leader.
                            Err(_) => continue,
                        }
                    }
                }
            }
        })
    }

    fn git_commit_details(
        &self,
        workspace_id: WorkspaceId,
        commit_hash: String,
        git_root_id: Option<WorkspaceGitRootId>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        let store = self.store.clone();
        Box::pin(async move {
            let empty = git_ops::empty_commit_details(&commit_hash);
            let ws = match store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(empty),
                Err(e) => return Err(e),
            };
            // `gitRootId` is validated before the remote early-return (same
            // policy as `git_status`).
            let Some(worktree) = svc.resolve_git_read_root(&ws, git_root_id.as_ref()).await? else {
                return Ok(empty);
            };
            if ws.is_remote {
                return Ok(empty);
            }
            if !worktree.join(".git").exists() {
                return Ok(empty);
            }
            let empty_for_err = empty.clone();
            let result = tokio::task::spawn_blocking(move || {
                git_ops::build_commit_details(&worktree, &commit_hash)
            })
            .await
            .map_err(|e| Error::Internal(format!("git.commitDetails task failed: {e}")))?;
            match result {
                Ok(value) => Ok(value),
                Err(Error::NotFound(_)) => Ok(empty_for_err),
                Err(e) => Err(e),
            }
        })
    }

    fn git_commits(
        &self,
        workspace_id: WorkspaceId,
        limit: Option<i64>,
        page_token: Option<String>,
        git_root_id: Option<WorkspaceGitRootId>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        let store = self.store.clone();
        Box::pin(async move {
            // §5.5 paginated read: clamp the page size to [1,200] (default 50)
            // and walk backward through the (newest-first) first-parent history
            // via an opaque skip token; the envelope is `{ items, nextToken }`.
            let limit = pagination::clamp_limit(limit);
            let skip = pagination::parse_offset(page_token.as_deref());
            let empty = serde_json::json!({ "items": [], "nextToken": serde_json::Value::Null });
            let ws = match store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(_) => return Ok(empty),
            };
            // `gitRootId` is validated before the remote early-return (same
            // policy as `git_status`).
            let Some(worktree) = svc.resolve_git_read_root(&ws, git_root_id.as_ref()).await? else {
                return Ok(empty);
            };
            if ws.is_remote {
                return Ok(empty);
            }
            if !worktree.join(".git").exists() {
                return Ok(empty);
            }
            // Fetch one past the page window to decide whether older commits
            // remain. `skip` comes from a client-provided token; treat window
            // math that would overflow as an empty page *before* doing any
            // git work (a saturated window would otherwise force a walk of
            // the entire history). The libgit2 revwalk runs on the blocking
            // pool so a slow walk on a big repo cannot stall other RPCs.
            let Some((page_end, fetch)) = skip
                .checked_add(limit)
                .and_then(|end| end.checked_add(1).map(|fetch| (end, fetch)))
            else {
                return Ok(empty);
            };
            // Metadata-only walk (`include_files = false`): the list payload
            // skips the O(commits) per-commit tree diff; clients fetch file
            // details on demand via `git.commitDetails`.
            let commits = tokio::task::spawn_blocking(move || {
                intent_git::history::history_since(&worktree, None, fetch, false)
            })
            .await
            .map_err(|e| Error::Internal(format!("git.commits task failed: {e}")))??;
            let has_more = commits.len() > page_end;
            let items: Vec<serde_json::Value> = commits
                .iter()
                .skip(skip)
                .take(limit)
                .map(git_ops::commit_to_commit_summary)
                .collect();
            let next_token = if has_more {
                serde_json::Value::String(pagination::offset_token(page_end))
            } else {
                serde_json::Value::Null
            };
            Ok(serde_json::json!({ "items": items, "nextToken": next_token }))
        })
    }

    fn git_show_file(
        &self,
        workspace_id: WorkspaceId,
        file_path: String,
        git_ref: String,
        git_root_id: Option<WorkspaceGitRootId>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let svc = self.clone();
        let store = self.store.clone();
        Box::pin(async move {
            // Same empty fallbacks as the other `git.*` reads (unknown/remote/
            // non-repo → empty content); a missing path at the ref is also
            // empty (legacy `git:show-file` parity), while a bad ref errors.
            let empty = serde_json::json!({ "content": "" });
            let ws = match store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(empty),
                Err(e) => return Err(e),
            };
            // `gitRootId` is validated before the remote early-return (same
            // policy as `git_status`).
            let Some(worktree) = svc.resolve_git_read_root(&ws, git_root_id.as_ref()).await? else {
                return Ok(empty);
            };
            if ws.is_remote {
                return Ok(empty);
            }
            if !worktree.join(".git").exists() {
                return Ok(empty);
            }
            let content = intent_git::show::show_file(&worktree, &git_ref, &file_path)?;
            Ok(serde_json::json!({ "content": content }))
        })
    }

    fn git_numstat(
        &self,
        workspace_id: WorkspaceId,
        staged: Option<bool>,
        base_ref: Option<String>,
        base_sha: Option<String>,
        target_ref: Option<String>,
        paths: Option<Vec<String>>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        Box::pin(async move {
            let empty = serde_json::json!([]);
            let ws = match store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(empty),
                Err(e) => return Err(e),
            };
            if ws.is_remote {
                return Ok(empty);
            }
            let Some(worktree) = git_ops::worktree_path(&ws) else {
                return Ok(empty);
            };
            if !worktree.join(".git").exists() {
                return Ok(empty);
            }
            let target = target_ref
                .as_deref()
                .filter(|s| !s.is_empty())
                .unwrap_or("HEAD");
            git_ops::build_numstat(
                &worktree,
                staged,
                base_ref.as_deref(),
                base_sha.as_deref(),
                target,
                paths.as_deref(),
            )
        })
    }

    fn git_branch_diff(
        &self,
        workspace_id: WorkspaceId,
        base_ref: Option<String>,
        base_sha: Option<String>,
        target_ref: Option<String>,
        paths: Option<Vec<String>>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        Box::pin(async move {
            // Router already rejects the missing-both-bases case as -32602
            // (see the `git.branchDiff` arm); this is a defense-in-depth
            // check for direct trait callers.
            if base_ref.as_deref().unwrap_or("").is_empty()
                && base_sha.as_deref().unwrap_or("").is_empty()
            {
                return Err(Error::InvalidParams(
                    "git.branchDiff requires baseRef or baseCommitSha".to_string(),
                ));
            }
            let empty = serde_json::json!([]);
            let ws = match store.get_workspace(&workspace_id).await {
                Ok(w) => w,
                Err(Error::NotFound(_)) => return Ok(empty),
                Err(e) => return Err(e),
            };
            if ws.is_remote {
                return Ok(empty);
            }
            let Some(worktree) = git_ops::worktree_path(&ws) else {
                return Ok(empty);
            };
            if !worktree.join(".git").exists() {
                return Ok(empty);
            }
            let target = target_ref
                .as_deref()
                .filter(|s| !s.is_empty())
                .unwrap_or("HEAD");
            git_ops::build_branch_diff(
                &worktree,
                base_ref.as_deref(),
                base_sha.as_deref(),
                target,
                paths.as_deref(),
            )
        })
    }

    fn git_get_remote_url(
        &self,
        repo_path: String,
        remote_name: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        Box::pin(async move {
            // Path-based validation like `git_get_branches`/`git_branch_status`:
            // nonexistent / non-git repo path → -32602 (PROTOCOL §5.6).
            git_ops::validate_repo_path(&repo_path)?;
            let name = remote_name
                .as_deref()
                .filter(|s| !s.is_empty())
                .unwrap_or("origin");
            let url = intent_git::remote::remote_url(std::path::Path::new(&repo_path), name)?;
            Ok(serde_json::json!({ "url": url }))
        })
    }

