    // ========================================================================
    // pr.* read surface (PROTOCOL §5.7). Maps onto the host-agnostic
    // `SourceControl` trait (§7.5); `pr.status` requires an active PR on the
    // workspace (else `-32603`). Pure mapping/aggregation lives in `pr_ops`.
    // ========================================================================

    fn pr_status(&self, workspace_id: WorkspaceId) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let injected = self.source_control.clone();
        Box::pin(async move {
            let ws = load_ws_for_pr(&store, &workspace_id).await?;
            let (owner, repo) = pr_ops::repo_of(&ws)?;
            let number = pr_ops::active_pr_number(&ws)?;
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            let pr = sc
                .get_pr(&repo_ref, number)
                .await
                .map_err(pr_ops::map_sc_err)?;
            let state = pr_ops::derive_status_state(&pr);
            let mergeable_state = pr
                .mergeable_state
                .clone()
                .unwrap_or_else(|| "unknown".to_string());
            let summary = pr_ops::build_status_summary(state, pr.mergeable, &mergeable_state);
            Ok(serde_json::json!({
                "prNumber": number,
                "title": pr.title,
                "url": pr.url,
                "state": state,
                "mergeable": pr.mergeable,
                "mergeableState": mergeable_state,
                "hasConflicts": mergeable_state == "dirty",
                "isDraft": state == "draft",
                "isMerged": state == "merged",
                "isClosed": state == "closed",
                "summary": summary,
            }))
        })
    }

    fn pr_refresh(&self, workspace_id: WorkspaceId) -> BoxFuture<'_, Result<serde_json::Value>> {
        let this = self.clone();
        Box::pin(async move {
            // `refresh_workspace_pr` owns persistence and the
            // `pr:linked`/`pr:updated`/`pr:unlinked` emission — no duplicate
            // event logic here; the RPC just reports the post-refresh state.
            let outcome = this.refresh_workspace_pr(&workspace_id).await?;
            let ws = this.store.get_workspace(&workspace_id).await?;
            Ok(serde_json::json!({
                "outcome": outcome.as_wire_str(),
                "prNumber": ws.pr_number,
                "prUrl": ws.pr_url,
                "prStatus": ws.pr_status,
                // Always an array on the wire — never null — matching the
                // `pr:*` event payloads (§6.5).
                "pullRequests": ws.pull_requests.as_deref().unwrap_or_default(),
            }))
        })
    }

    fn pr_state(
        &self,
        workspace_id: WorkspaceId,
        pr_number: u64,
        repo: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let store = self.store.clone();
        let injected = self.source_control.clone();
        Box::pin(async move {
            let ws = load_ws_for_pr(&store, &workspace_id).await?;
            // Cross-repo override (`{ repo: "owner/name" }`) wins over the
            // workspace repo; either way the resolved repo is echoed in the
            // result so a wrong-repo read is detectable.
            let (owner, repo) = match repo {
                Some(slug) => pr_ops::parse_repo_slug(&slug)?,
                None => pr_ops::repo_of(&ws)?,
            };
            let repo_slug = format!("{owner}/{repo}");
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            let pr = sc.get_pr(&repo_ref, pr_number).await.map_err(|e| match e {
                intent_sourcecontrol::Error::NotFound(_) => {
                    Error::Internal(format!("PR #{pr_number} not found in {repo_slug}"))
                }
                other => pr_ops::map_sc_err(other),
            })?;
            let state = pr_ops::derive_status_state(&pr);
            let mergeable_state = pr
                .mergeable_state
                .clone()
                .unwrap_or_else(|| "unknown".to_string());

            // The one-shot read composes EXACTLY the checklist the PR monitor
            // works with, so `ws.pr.snapshot`, monitor wakes and
            // `prMonitor.list` summaries all describe a PR with the same
            // object — this registers nothing and triggers no monitoring.
            // Every forge sub-read inside degrades on its own.
            let (requirements, review_comment_count) =
                pr_ops::merge_requirements_for_pr(sc.as_ref(), &repo_ref, pr_number, &pr).await;
            let unresolved_thread_count = requirements.threads.unresolved;
            // The conversation-comment count is not part of the checklist; a
            // failing read reports zero rather than failing the snapshot.
            let conversation_count = match sc.list_comments(&repo_ref, pr_number).await {
                Ok(comments) => comments.len() as i64,
                Err(e) => {
                    tracing::warn!(
                        error = %e,
                        pr_number,
                        "pr.snapshot: conversation comments unavailable, reporting zero"
                    );
                    0
                }
            };
            // The pre-existing compact blocks stay stable for callers that
            // already read them, but are projected off the checklist rather
            // than computed a second time. `checks.failedNames` lists every
            // failing check, in rollup order; `requirements.checks
            // .failingRequired` narrows it to the required ones.
            let failed_names: Vec<&str> = requirements
                .checks
                .items
                .iter()
                .filter(|c| c.status == "failed")
                .map(|c| c.name.as_str())
                .collect();

            Ok(serde_json::json!({
                "repo": repo_slug,
                "prNumber": pr_number,
                "title": pr.title,
                "url": pr.url,
                "state": state,
                "isDraft": state == "draft",
                "isMerged": state == "merged",
                "isClosed": state == "closed",
                "headSha": pr.head_sha,
                "updatedAt": pr.updated_at,
                "mergeable": pr.mergeable,
                "mergeableState": mergeable_state,
                "mergeBlockedReason": requirements.merge_blocked_reason,
                "checks": {
                    "total": requirements.checks.total,
                    "passed": requirements.checks.passed,
                    "failed": requirements.checks.failed,
                    "pending": requirements.checks.pending,
                    "failedNames": failed_names,
                },
                "reviews": {
                    "decision": requirements.approvals.decision,
                    "approvals": requirements.approvals.have,
                    "changesRequested": requirements.approvals.changes_requested,
                },
                "comments": {
                    "conversationCount": conversation_count,
                    "reviewCommentCount": review_comment_count,
                    "unresolvedThreadCount": unresolved_thread_count,
                    "totalCount": conversation_count + review_comment_count,
                },
                // The merge-requirements checklist: the same object
                // `ws.pr.monitor` returns and monitor wakes / list summaries
                // carry.
                "requirements": requirements,
            }))
        })
    }

    // ------------------------------------------------------------------------
    // `github.*` explicit-addressing surface (PROTOCOL §5.27). Every method
    // takes `(owner, repo[, number])` directly (no workspace/active-PR
    // resolution) and reuses the `intent-sourcecontrol` engine that backs
    // `pr.*`; the source-control handle and forge-error mapping are shared with
    // `pr_ops`, while the GitHub-shaped wire DTOs are rendered by `github_ops`.
    // ------------------------------------------------------------------------

    fn github_pulls_create(
        &self,
        owner: String,
        repo: String,
        title: String,
        body: String,
        head: String,
        base: String,
        draft: bool,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            // `head` is forwarded VERBATIM (no `owner:branch` login prefix) —
            // the engine sends `input.source_branch` as the raw `head`,
            // preserving the FE's same-repo-branch bypass (§5.27).
            let pr = sc
                .create_pr(
                    &repo_ref,
                    intent_sourcecontrol::NewPullRequest {
                        title,
                        body: Some(body),
                        source_branch: head,
                        target_branch: base,
                        draft,
                    },
                )
                .await
                .map_err(pr_ops::map_sc_err)?;
            Ok(serde_json::json!({ "pull": github_ops::pull_to_json(&pr) }))
        })
    }

    fn github_pulls_get(
        &self,
        owner: String,
        repo: String,
        number: u64,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            let pr = sc
                .get_pr(&repo_ref, number)
                .await
                .map_err(pr_ops::map_sc_err)?;
            Ok(serde_json::json!({ "pull": github_ops::pull_to_json(&pr) }))
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn github_pulls_list(
        &self,
        owner: String,
        repo: String,
        state: Option<String>,
        head: Option<String>,
        base: Option<String>,
        limit: Option<i64>,
        next_token: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let state = github_ops::parse_pr_state(state.as_deref())?;
            let limit = github_ops::clamp_limit(limit);
            let cursor = github_ops::decode_next_token(next_token.as_deref());
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            let page = sc
                .list_prs(
                    &repo_ref,
                    intent_sourcecontrol::PrQuery {
                        state,
                        base,
                        head,
                        author: None,
                        involvement: None,
                        search: None,
                        limit: Some(limit),
                        cursor,
                    },
                )
                .await
                .map_err(pr_ops::map_sc_err)?;
            let pulls: Vec<_> = page.items.iter().map(github_ops::pull_to_json).collect();
            Ok(serde_json::json!({
                "pulls": pulls,
                "nextToken": github_ops::next_token_value(page.next_cursor.as_deref()),
            }))
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn github_pulls_search(
        &self,
        owner: String,
        repo: String,
        filter: Option<String>,
        state: Option<String>,
        query: Option<String>,
        limit: Option<i64>,
        next_token: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let involvement = github_ops::parse_pr_involvement(filter.as_deref())?;
            let search = github_ops::normalize_search_query(query);
            // Search defaults to open PRs (FE `searchGitHubPullRequests`); a
            // `filter:"all"` with no free-text `query` carries no constraint
            // and so degrades to the plain `github.pulls.list` listing the
            // engine performs, while involvement and/or free text route
            // through `GET /search/issues`.
            let state = match state {
                Some(s) => github_ops::parse_pr_state(Some(s.as_str()))?,
                None => Some(intent_sourcecontrol::PrState::Open),
            };
            let limit = github_ops::clamp_limit(limit);
            let cursor = github_ops::decode_next_token(next_token.as_deref());
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            let page = sc
                .list_prs(
                    &repo_ref,
                    intent_sourcecontrol::PrQuery {
                        state,
                        base: None,
                        head: None,
                        author: None,
                        involvement,
                        search,
                        limit: Some(limit),
                        cursor,
                    },
                )
                .await
                .map_err(pr_ops::map_sc_err)?;
            let pulls: Vec<_> = page.items.iter().map(github_ops::pull_to_json).collect();
            Ok(serde_json::json!({
                "pulls": pulls,
                "nextToken": github_ops::next_token_value(page.next_cursor.as_deref()),
            }))
        })
    }

    fn github_pulls_merge(
        &self,
        owner: String,
        repo: String,
        number: u64,
        merge_method: Option<String>,
        commit_title: Option<String>,
        commit_message: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let method = pr_ops::validate_merge_method(merge_method)?;
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner, repo);
            let outcome = sc
                .merge_pr(
                    &repo_ref,
                    number,
                    method,
                    intent_sourcecontrol::MergeOptions {
                        commit_title,
                        commit_message,
                    },
                )
                .await
                .map_err(pr_ops::map_sc_err)?;
            Ok(serde_json::json!({
                "merged": outcome.merged,
                "message": outcome.message,
                "sha": outcome.sha,
            }))
        })
    }

    // ========================================================================
    // github.* browse / auth / identity (PROTOCOL §5.27)
    //
    // These reuse the same `SourceControl` engine as `pr.*` (via
    // `pr_ops::resolve_source_control` / `map_sc_err`) but address GitHub
    // directly by params, with no workspace/active-PR scoping. The PAT is read
    // once by the engine at build time and is NEVER logged or returned here.
    // ========================================================================

