    fn github_branches_list(
        &self,
        owner: String,
        repo: String,
        prefix: Option<String>,
        limit: Option<i64>,
        next_token: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let limit = github_ops::clamp_limit(limit);
            let cursor = github_ops::decode_next_token(next_token.as_deref());
            // A blank/whitespace `prefix` keeps the unfiltered listing
            // (parity with the trimmed, blanks-dropped search queries).
            let prefix = prefix
                .map(|p| p.trim().to_string())
                .filter(|p| !p.is_empty());
            let sc = pr_ops::resolve_source_control(injected).await?;
            let page = sc
                .list_remote_branches(
                    &owner,
                    &repo,
                    prefix.as_deref(),
                    intent_sourcecontrol::PageParams { limit, cursor },
                )
                .await
                .map_err(pr_ops::map_sc_err)?;
            Ok(serde_json::json!({
                "branches": github_browse_ops::branch_names(&page.items),
                "nextToken": github_ops::next_token_value(page.next_cursor.as_deref()),
            }))
        })
    }

    fn github_branches_list_cached(
        &self,
        owner: String,
        repo: String,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        // Mirror `workspace.create`'s parent resolution (worktreesLocation
        // unless startup-pinned) so a cache warmed by workspace creation under
        // a custom `workspace.worktreesLocation` is found by this reader too.
        // Unlike the write path this never creates the directory.
        let cache_parent = self
            .configured_worktrees_location()
            .or_else(|| self.workspaces_root.clone())
            .unwrap_or_else(default_workspaces_root);
        let registry = self.settings_registry.clone();
        let ls_remote_base = self.branches_ls_remote_base.clone();
        Box::pin(async move {
            let cache_root = cache_parent.join(".repo-cache");
            match intent_git::repo_cache::list_cached_branches(&cache_root, &owner, &repo).await? {
                Some(cached) => {
                    let mut result = serde_json::json!({
                        "cached": true,
                        "source": "cache",
                        "branches": cached.branches,
                    });
                    // `defaultBranch` is optional on the wire: omitted (not
                    // null) when `origin/HEAD` is unresolvable.
                    if let Some(default) = cached.default_branch {
                        result["defaultBranch"] = serde_json::Value::String(default);
                    }
                    Ok(result)
                }
                // Cold cache: fall back to one `git ls-remote` against the
                // GitHub remote (monorepo#1955) — one child process, one
                // round-trip, token offered via env exactly like the clone
                // pipeline. Any failure (offline, missing repo, no access)
                // folds to the pre-fallback `{ cached: false, branches: [] }`
                // — this method never errors for the FE seam.
                None => {
                    let base = ls_remote_base.as_deref().unwrap_or("https://github.com");
                    let url = format!("{base}/{owner}/{repo}.git");
                    let token = github_git_token_for_url(registry.as_deref(), &url).await;
                    match intent_git::ls_remote::ls_remote_branches(&url, token.as_deref()).await {
                        Ok(remote) => {
                            let mut result = serde_json::json!({
                                "cached": false,
                                "source": "ls-remote",
                                "branches": remote.branches,
                            });
                            if let Some(default) = remote.default_branch {
                                result["defaultBranch"] = serde_json::Value::String(default);
                            }
                            Ok(result)
                        }
                        Err(e) => {
                            tracing::debug!(
                                owner = %owner,
                                repo = %repo,
                                "branches.listCached ls-remote fallback failed: {e}"
                            );
                            Ok(serde_json::json!({
                                "cached": false,
                                "branches": [],
                            }))
                        }
                    }
                }
            }
        })
    }

    fn github_repo_config_get(
        &self,
        owner: String,
        repo: String,
        git_ref: Option<String>,
    ) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        Box::pin(async move {
            let sc = pr_ops::resolve_source_control(injected).await?;
            let repo_ref = intent_sourcecontrol::RepoRef::new(owner.clone(), repo.clone());
            let source = format!(
                "{}/{}@{}",
                owner,
                repo,
                git_ref.as_deref().unwrap_or("default")
            );
            // Missing file → { config: null, exists: false }. A present entry
            // parses tolerantly like the local `repoConfig.get`: invalid JSON,
            // non-object root, and mis-shaped contents payloads (directory,
            // non-base64/non-UTF-8 content) all fold to the empty config with
            // exists: true — never an error. Transport/auth failures still
            // surface like the other `github.*` methods.
            let content = match sc
                .get_file_content(
                    &repo_ref,
                    repo_config::REPO_CONFIG_REL_PATH,
                    git_ref.as_deref(),
                )
                .await
            {
                Ok(c) => c,
                Err(intent_sourcecontrol::Error::Decode(msg)) => {
                    tracing::warn!("Mis-shaped remote repo config at {}: {}", source, msg);
                    return Ok(serde_json::json!({
                        "config": intent_core::RepoConfig::default(),
                        "exists": true,
                    }));
                }
                Err(e) => return Err(pr_ops::map_sc_err(e)),
            };
            match content {
                Some(text) => {
                    let config = repo_config::parse_repo_config_tolerant(&text, &source);
                    Ok(serde_json::json!({ "config": config, "exists": true }))
                }
                None => Ok(serde_json::json!({
                    "config": serde_json::Value::Null,
                    "exists": false,
                })),
            }
        })
    }

    fn github_auth_status(&self) -> BoxFuture<'_, Result<serde_json::Value>> {
        let injected = self.source_control.clone();
        let state = self.github_auth_flow.clone();
        Box::pin(async move {
            // A missing/invalid token is the graceful "not configured" state,
            // NOT an error: report `isConfigured: false` instead of throwing.
            let is_configured = match pr_ops::resolve_source_control(injected).await {
                Ok(sc) => sc
                    .check_auth()
                    .await
                    .map(|s| s.authenticated)
                    .unwrap_or(false),
                Err(_) => false,
            };
            let slot = state.lock().await;
            Ok(github_auth_ops::auth_status_to_wire(
                is_configured,
                slot.as_ref(),
            ))
        })
    }

    fn github_connect(&self) -> BoxFuture<'_, Result<serde_json::Value>> {
        // Start (or return the still-pending) GitHub OAuth device flow
        // (§5.27). The daemon polls GitHub in the background; the token is
        // persisted server-side by the engine and never crosses the wire.
        let state = self.github_auth_flow.clone();
        let bus = self.event_bus.clone();
        let secrets = self.secrets.clone();
        let client_id = self
            .effective_settings()
            .source_control
            .github
            .oauth_client_id;
        let base_uri =
            github_auth_ops::resolve_login_base_uri(self.github_login_base_uri.as_deref());
        Box::pin(async move {
            // Short critical section: reuse a live flow / clear a terminal
            // one. The lock is NOT held across the network start below, so
            // cancelAuth / revoke / authStatus stay responsive meanwhile.
            {
                let mut slot = state.lock().await;
                // A connect while a flow is live returns the SAME codes — no
                // restart, no second poll task.
                if let Some(s) = slot.as_ref() {
                    if s.is_live() {
                        return Ok(github_auth_ops::connect_response(s));
                    }
                }
                // Replace any terminal/expired slot; its poll task (if any)
                // exits cooperatively once its generation is gone.
                *slot = None;
            }
            let (auth, flow) = intent_sourcecontrol::device_flow::start_at(
                &base_uri,
                &client_id,
                intent_sourcecontrol::device_flow::DEFAULT_SCOPES,
            )
            .await
            .map_err(pr_ops::map_sc_err)?;
            let mut slot = state.lock().await;
            // A concurrent connect raced us while the lock was released: keep
            // the resident live flow (single-flow invariant) and drop ours —
            // its handle never spawned a poll task, so nothing leaks.
            if let Some(s) = slot.as_ref() {
                if s.is_live() {
                    return Ok(github_auth_ops::connect_response(s));
                }
            }
            let flow_id = github_auth_ops::next_flow_id();
            let deadline =
                tokio::time::Instant::now() + std::time::Duration::from_secs(auth.expires_in);
            // gh CLI sync only makes sense against the production login host
            // (see `github_auth_ops::is_production_login_host`).
            let sync_gh = github_auth_ops::is_production_login_host(&base_uri);
            tokio::spawn(github_auth_ops::run_poll_loop(
                state.clone(),
                bus,
                secrets,
                flow_id,
                flow,
                deadline,
                sync_gh,
            ));
            let new_slot = github_auth_ops::FlowSlot {
                flow_id,
                user_code: auth.user_code,
                verification_uri: auth.verification_uri,
                interval: auth.interval,
                deadline,
                phase: github_auth_ops::FlowPhase::Pending,
            };
            let resp = github_auth_ops::connect_response(&new_slot);
            *slot = Some(new_slot);
            tracing::info!("github device flow started");
            Ok(resp)
        })
    }

    fn github_cancel_auth(&self) -> BoxFuture<'_, Result<serde_json::Value>> {
        let state = self.github_auth_flow.clone();
        Box::pin(async move {
            let mut slot = state.lock().await;
            // Only a pending flow is cancellable. A terminal slot (expired /
            // denied / error) is left intact so authStatus keeps surfacing
            // the outcome until the next connect replaces it. Removing the
            // slot orphans the poll task, which exits cooperatively at its
            // next tick (and reconciles a raced authorize by deleting the
            // just-persisted token — see `github_auth_ops::FlowSlot`).
            let cancelled = match slot.as_ref() {
                Some(s) if s.phase == github_auth_ops::FlowPhase::Pending => {
                    *slot = None;
                    true
                }
                _ => false,
            };
            Ok(serde_json::json!({ "ok": true, "cancelled": cancelled }))
        })
    }

    fn github_revoke(&self) -> BoxFuture<'_, Result<serde_json::Value>> {
        // Delete the stored `sourceControl.github.token` (device-flow slot of
        // the resolution chain) and orphan any in-flight flow (its poll task
        // exits cooperatively and reconciles a raced authorize by deleting
        // the just-persisted token). Env / `gh` CLI fallbacks are untouched —
        // authStatus reflects them on next probe. When gh's active login IS
        // the token being revoked (the login the authorize-side sync
        // created), gh is best-effort logged out too — same production-host
        // gate as the login sync, so mock-host tests never touch a real `gh`.
        let state = self.github_auth_flow.clone();
        let secrets = self.secrets.clone();
        let bus = self.event_bus.clone();
        let logout_gh = github_auth_ops::is_production_login_host(
            &github_auth_ops::resolve_login_base_uri(self.github_login_base_uri.as_deref()),
        );
        Box::pin(async move {
            // Capture the stored token BEFORE it is deleted so the detached
            // logout can match it against gh's active login. Fail-soft: a
            // load failure only skips the logout, never the revoke. 🔒 The
            // token stays in memory — never logged or embedded in errors.
            let revoked_token = if logout_gh {
                secrets
                    .load(github_auth_ops::SECRET_ACCOUNT)
                    .await
                    .unwrap_or_else(|e| {
                        tracing::debug!(
                            error = %e,
                            "could not read stored github token before revoke; \
                             skipping gh CLI logout"
                        );
                        None
                    })
            } else {
                None
            };
            {
                let mut slot = state.lock().await;
                *slot = None;
            }
            github_auth_ops::delete_stored_token(&secrets).await?;
            publish_event(&bus, github_auth_ops::auth_changed_event("revoked")).await;
            if logout_gh {
                // Detached + fail-soft (same pattern as the login sync): a
                // logout failure can never fail or delay the revoke.
                tokio::spawn(intent_sourcecontrol::gh_sync::logout_gh_after_revoke(
                    revoked_token,
                ));
            }
            Ok(serde_json::json!({ "ok": true }))
        })
    }

